INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_79882ee159b7495d', 'cat_tshirt', 'Áo Thun Sọc Phom Boxy Hack Dáng FlexFit™ Vải Co Giãn Thoáng Mát The No Style 241 Màu Trắng Đen Dáng Rộng Rãi F4', 'ao-thun-soc-phom-boxy-hack-dang-flexfit-vai-co-gian-thoang-mat-the-no-style-241-mau-trang-den-dang-rong-rai-f4', '0025059', 'Áo Thun Cổ Tròn FlexFit™ The No Style 241 1. Chất liệu FlexFit™ Extreme – Co giãn như lò xo Vải gân Rib 1x1 độc quyền: Định lượng 255gsm dày dặn, đầm tay. Độ đàn hồi 90%: Kết hợp 6% Spandex giúp phục hồi form tức thì. Vận động tự do: Thoải mái co giãn, không lo vải bị biến dạng hay nhão. 2. Công ngh', 'Áo Thun Cổ Tròn FlexFit™ The No Style 241 1. Chất liệu FlexFit™ Extreme – Co giãn như lò xo Vải gân Rib 1x1 độc quyền: Định lượng 255gsm dày dặn, đầm tay. Độ đàn hồi 90%: Kết hợp 6% Spandex giúp phục hồi form tức thì. Vận động tự do: Thoải mái co giãn, không lo vải bị biến dạng hay nhão. 2. Công nghệ Sọc dệt Yarn-dyed – Bền màu theo tuổi thọ áo Sợi màu trực tiếp: Họa tiết sọc được dệt từ sợi đã nhuộm, không phải in. Độ bền tuyệt đối: Không bong tróc, không nứt vỡ đường sọc khi kéo giãn. Màu sắc sắc nét: Giữ độ tươi mới và đều màu sau nhiều lần giặt. 3. Form dáng Loose Fit – Phóng khoáng &amp; Giấu khuyết điểm Khối Boxy thời thượng: Vai trễ và hạ nách sâu hiện đại. Khoảng không gian thở: Tạo độ thông thoáng giữa vải và da, không dính rít. Phong cách Unisex: Thiết kế phóng khoáng, tôn dáng cho cả nam và nữ. 4. Kỹ thuật may chuẩn cao cấp Vai áo: Gia cố dây chống giãn giúp giữ cầu vai phẳng, không chảy xệ. Lai &amp; Tay áo: Bản may 3cm tạo độ nặng, giữ áo luôn rũ thẳng vuông vức. Cổ áo: Xử lý lấy dấu 4 điểm chốt giúp vòng cổ tròn đều, chống vặn xoắn. TỔNG KẾT Chiếc áo sọc "quốc dân" cân bằng hoàn hảo giữa độ dày đứng form và sự co giãn linh hoạt, mang lại vẻ ngoài chỉn chu, bền bỉ cho tủ đồ tối giản. THÔNG TIN NHANH Chất liệu: 94% Cotton, 6% Spandex (Định lượng 255gsm). Chi tiết: F4 - Loose Fit (Dáng Rộng), vai trễ, sọc dệt Yarn-dyed, gia cố vai chống giãn. Lưu ý giặt ủi: Giặt nước lạnh, lộn trái khi giặt/phơi. Không sấy nóng hoặc vặn xoắn mạnh để bảo vệ sợi co giãn.', 'YAME', 282150, 297000, true, 5.0, 3274, 398, 4.6, 85, 'active', false, true, false, 'Áo Thun Sọc Phom Boxy Hack Dáng FlexFit™ Vải Co Giãn Thoáng Mát The No Style 241 Màu Trắng Đen Dáng Rộng Rãi F4', 'Áo Thun Cổ Tròn FlexFit™ The No Style 241 1. Chất liệu FlexFit™ Extreme – Co giãn như lò xo Vải gân Rib 1x1 độc quyền: Định lượng 255gsm dày dặn, đầm tay. Độ đàn hồi 90%: Kết hợp 6% Spandex giúp phục hồi form tức thì. Vận động tự do: Thoải mái co giãn, không lo vải bị biến dạng hay nhão. 2. Công ngh', '080426-sale-5, màu trắng, Quần áo, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
