INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_7d0395a32ff5410f', 'cat_tshirt', 'Áo Thun FlexFit™ Vải Co Giãn In Nổi 3D "Universe" The No Style 210 Màu Xám Nhạt Dáng Rộng Rãi F4', 'ao-thun-flexfit-vai-co-gian-in-noi-3d-universe-the-no-style-210-mau-xam-nhat-dang-rong-rai-f4', '0024986', 'Áo Thun Cổ Tròn Tay Ngắn FlexFit™ The No Style 210 1. Công Nghệ In Puff (In Nổi 3D) Sản phẩm ứng dụng kỹ thuật In Puff (in cao), tạo hiệu ứng 3D nổi bật với độ gồ ghề và đàn hồi nhẹ khi chạm vào. Công nghệ này giúp các khối màu graphic và typography tách biệt sắc nét, tạo chiều sâu thị giác và hạn c', 'Áo Thun Cổ Tròn Tay Ngắn FlexFit™ The No Style 210 1. Công Nghệ In Puff (In Nổi 3D) Sản phẩm ứng dụng kỹ thuật In Puff (in cao), tạo hiệu ứng 3D nổi bật với độ gồ ghề và đàn hồi nhẹ khi chạm vào. Công nghệ này giúp các khối màu graphic và typography tách biệt sắc nét, tạo chiều sâu thị giác và hạn chế tối đa tình trạng hình in bị dính vào nhau khi gấp áo. 2. Phom Dáng Boxy Loose Fit Cấu trúc phom hộp suông rộng hiện đại với chiều ngang được nới rộng 4cm và vai trễ 7cm (Drop Shoulder). Thiết kế này giúp "giấu dáng", che khuyết điểm cơ thể tối ưu. Vòng nách được hạ sâu thêm 0.6cm giúp triệt tiêu cảm giác cấn, gò bó dưới cánh tay, giữ cho vùng nách luôn thoáng khí. 3. Chất Liệu FlexFit™ 225gsm Sử dụng vải FlexFit™ Cotton Basic Single với định lượng 225gsm dày dặn. Chất liệu đóng vai trò "khung xương" vững chắc, giúp áo đứng form, không bị chảy xệ hay rúm ró khi phải "gánh" hình in lớn. Sợi 100% Compact Cotton giúp bề mặt mịn màng (Soft Touch), hạn chế xù lông và co giãn cơ học tự nhiên. 4. Hoàn Thiện Chi Tiết &amp; Độ Bền Mật độ chỉ: Kiểm soát ở mức 4.5 mũi/cm, đảm bảo đường may chắc chắn mà không làm đứt chân sợi vải. Nhãn in (Tagless): Thông tin size được in chuyển nhiệt trực tiếp, loại bỏ nhãn vải may kẹp gây ngứa gáy. Gia cố: Chân cổ sau được may lược dây treo tỉ mỉ, chống vặn xoắn và giữ phom cổ ổn định. TỔNG KẾT The No Style 210 là giải pháp hoàn hảo cho nỗi lo áo thun graphic bị biến dạng. Sự kết hợp giữa kỹ thuật in Puff 3D và nền vải Compact Cotton 225gsm tạo nên một sản phẩm có kết cấu vững chãi, thẩm mỹ cao và bền bỉ qua nhiều lần sử dụng. THÔNG TIN NHANH Chất liệu: FlexFit™ Cotton Basic Single (225gsm) - 100% Compact Cotton. Chi tiết sản phẩm: Phom Boxy Loose Fit, In Puff (In nổi), Vai trễ (Drop Shoulder). Lưu ý giặt / ủi: Giặt máy chế độ thường, nước lạnh hoặc ấm nhẹ (&lt; 40°C). Không sử dụng thuốc tẩy có Clo. Sấy khô ở nhiệt độ trung bình. Ủi ở nhiệt độ 160–200°C. Lưu ý: Phải ủi mặt trái, tuyệt đối không ủi trực tiếp lên hình in.', 'YAME', 282150, 297000, true, 5.0, 4414, 297, 3.9, 136, 'active', true, true, false, 'Áo Thun FlexFit™ Vải Co Giãn In Nổi 3D "Universe" The No Style 210 Màu Xám Nhạt Dáng Rộng Rãi F4', 'Áo Thun Cổ Tròn Tay Ngắn FlexFit™ The No Style 210 1. Công Nghệ In Puff (In Nổi 3D) Sản phẩm ứng dụng kỹ thuật In Puff (in cao), tạo hiệu ứng 3D nổi bật với độ gồ ghề và đàn hồi nhẹ khi chạm vào. Công nghệ này giúp các khối màu graphic và typography tách biệt sắc nét, tạo chiều sâu thị giác và hạn c', '110426-sale-5, màu xám, Quần áo, signature, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
