INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_3d85493307204e2e', 'cat_tshirt', 'Áo Thun FlexFit™ Co Giãn "7 Ngày Năng Động" Non Branded 047 Màu Nâu Đậm Dáng Rộng Rãi F4', 'ao-thun-flexfit-co-gian-7-ngay-nang-dong-non-branded-047-mau-nau-dam-dang-rong-rai-f4', '0024911', 'Áo Thun Cổ Tròn Tay Ngắn FlexFit™ Non Branded 047 Chất Liệu FlexFit™ Cotton 225gsm 100% Compact Cotton: Sợi cao cấp siêu bền, bề mặt mịn màng và nói không với xù lông. Co giãn tự nhiên: Kỹ thuật dệt Single Jersey giúp thoải mái vận động mà không cần pha sợi nhân tạo. Độ dày 225gsm: Trọng lượng lý tư', 'Áo Thun Cổ Tròn Tay Ngắn FlexFit™ Non Branded 047 Chất Liệu FlexFit™ Cotton 225gsm 100% Compact Cotton: Sợi cao cấp siêu bền, bề mặt mịn màng và nói không với xù lông. Co giãn tự nhiên: Kỹ thuật dệt Single Jersey giúp thoải mái vận động mà không cần pha sợi nhân tạo. Độ dày 225gsm: Trọng lượng lý tưởng, vừa đủ dày để giữ phom vừa đủ thoáng để da "thở". Giữ dáng bền lâu: Kết cấu vải chắc chắn, hạn chế tối đa tình trạng mất phom sau nhiều lần giặt. Kỹ thuật Rập Boxy (Loose Fit) Cấu trúc hình hộp: Nới rộng ngang ngực và ngang lai so với phom chuẩn, giúp giấu khuyết điểm vòng bụng hiệu quả. Cân bằng tỉ lệ tay: Tăng dài tay và cửa tay để tạo cảm giác tay thon gọn nhưng vẫn đảm bảo cử động thoải mái. Kết cấu lai áo: Sử dụng máy Kansai cuốn lai bản lớn, tạo độ nặng cần thiết để áo rũ đẹp và giữ chuẩn phom Loose Fit. Tiêu chuẩn Kỹ thuật &amp; Hoàn thiện Chống giãn cổ: Kỹ thuật móc xích áp dụng cho đường diễu cổ giúp đàn hồi tốt và hồi phom nhanh, không bị bai dão khi chui đầu. Đường may gia cố: Mật độ chỉ cao hơn tiêu chuẩn thông thường, đảm bảo độ bền kéo giãn cực cao. Xử lý sạch: Viền cổ bọc kín giúp tăng tính thẩm mỹ, tránh cộm ngứa và giữ form cổ không bị bè. Chi tiết hình in: Logo ép nhiệt Silicon có độ dày nổi rõ trên bề mặt vải, tạo hiệu ứng khối 3D sắc nét. TỔNG KẾT Non Branded 047 là sự kết hợp giữa kỹ thuật dựng rập hiện đại và công nghệ sợi dệt 100% Cotton bền bỉ. Sản phẩm giải quyết triệt để các vấn đề về mất phom hay dão cổ, mang lại trải nghiệm mặc thoải mái và chỉn chu suốt cả tuần dài. THÔNG TIN NHANH Chất liệu: FlexFit™ Cotton Basic Single 225gsm, 100% Compact Cotton Chi tiết sản phẩm: F4 - Loose Fit (Dáng Rộng), Logo ép nhiệt Silicon. Lưu ý giặt ủi: Giặt máy chế độ thường (&lt; 40°C). Không tẩy Clo. Sấy nhiệt độ trung bình. Ủi mặt trái ở 160–200°C.', 'YAME', 263150, 277000, true, 5.0, 3837, 235, 4.6, 67, 'active', false, true, false, 'Áo Thun FlexFit™ Co Giãn "7 Ngày Năng Động" Non Branded 047 Màu Nâu Đậm Dáng Rộng Rãi F4', 'Áo Thun Cổ Tròn Tay Ngắn FlexFit™ Non Branded 047 Chất Liệu FlexFit™ Cotton 225gsm 100% Compact Cotton: Sợi cao cấp siêu bền, bề mặt mịn màng và nói không với xù lông. Co giãn tự nhiên: Kỹ thuật dệt Single Jersey giúp thoải mái vận động mà không cần pha sợi nhân tạo. Độ dày 225gsm: Trọng lượng lý tư', '110426-sale-5, màu nâu, Quần áo, signature, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
