INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_b2e7562a8e9f4e01', 'cat_tshirt', 'Áo Thun ColorLock™ Cotton Mềm Mát Giữ Màu Có Ngăn Cắm Bút Tiện Lợi The Worker 003 Màu Vàng Dáng Rộng Rãi F4', 'ao-thun-colorlock-cotton-mem-mat-giu-mau-co-ngan-cam-but-tien-loi-the-worker-003-mau-vang-dang-rong-rai-f4', '0024889', 'Áo Thun Cổ Tròn Tay Ngắn The Worker 003 1. Kỹ Thuật Dựng Phom &amp; Tiện Ích Kết cấu chịu lực: Đường vai được gia cố bằng dây chống giãn (Mobilon tape) kết hợp cổ áo may móc xích (Coverstitch), giúp áo giữ phom chuẩn, không bị bai dão hay lượn sóng cổ sau nhiều lần giặt. Thiết kế thông minh: Phom dá', 'Áo Thun Cổ Tròn Tay Ngắn The Worker 003 1. Kỹ Thuật Dựng Phom &amp; Tiện Ích Kết cấu chịu lực: Đường vai được gia cố bằng dây chống giãn (Mobilon tape) kết hợp cổ áo may móc xích (Coverstitch), giúp áo giữ phom chuẩn, không bị bai dão hay lượn sóng cổ sau nhiều lần giặt. Thiết kế thông minh: Phom dáng Loose Fit với độ nới rộng ngực và hạ vai (Dropped Shoulder) mang lại sự thoải mái tối đa. Túi ngực tích hợp khe cắm bút (Pen slot) giữ bút cố định, tiện lợi cho công việc hàng ngày. 2. Công Nghệ Vải &amp; Độ Bền Màu Công nghệ ColorLock™: Hạt màu được đưa sâu vào lõi sợi giúp duy trì độ sâu màu sắc, hạn chế tối đa tình trạng bạc màu hay xuất hiện vệt trắng. Định lượng tối ưu: Vải Cotton 205-215gsm (độ dày trung bình), đảm bảo đứng phom, che khuyết điểm cơ thể nhưng vẫn thoáng khí, không gây nóng. 3. Trải Nghiệm Người Dùng (Tactile Experience) Thoải mái tuyệt đối: Bề mặt vải xử lý Dry-Touch mang lại cảm giác mộc, khô thoáng, không bết dính mồ hôi. Không co rút, không ngứa: Vải đã qua xử lý giặt trước (Pre-washed) để chống co rút. Thiết kế Tagless (in thông tin trực tiếp lên vải) loại bỏ hoàn toàn cảm giác cộm ngứa vùng gáy. TỔNG KẾT The Worker 003 là giải pháp toàn diện khắc phục 3 nhược điểm lớn của áo thun: Mất phom - Bạc màu - Cộm ngứa. Với hệ thống gia cố bền bỉ và các tiện ích tinh tế, đây là khoản đầu tư xứng đáng cho tủ đồ thiết yếu của bạn. THÔNG TIN NHANH Chất liệu: ColorLock™ Cotton Plus Single, 100% Cotton Chi tiết sản phẩm: Loose Fit, túi có khe bút, cổ bản to 2.5cm, không nhãn vải cổ Lưu ý giặt ủi: Lộn trái sản phẩm trước khi giặt/phơi. Giũ mạnh áo 2-3 lần sau khi vắt để vải bung ra tự nhiên. Ủi nhiệt độ 160°C – 200°C (tốt nhất khi vải hơi ẩm).', 'YAME', 263150, 277000, true, 5.0, 199, 349, 3.9, 59, 'active', false, true, false, 'Áo Thun ColorLock™ Cotton Mềm Mát Giữ Màu Có Ngăn Cắm Bút Tiện Lợi The Worker 003 Màu Vàng Dáng Rộng Rãi F4', 'Áo Thun Cổ Tròn Tay Ngắn The Worker 003 1. Kỹ Thuật Dựng Phom &amp; Tiện Ích Kết cấu chịu lực: Đường vai được gia cố bằng dây chống giãn (Mobilon tape) kết hợp cổ áo may móc xích (Coverstitch), giúp áo giữ phom chuẩn, không bị bai dão hay lượn sóng cổ sau nhiều lần giặt. Thiết kế thông minh: Phom dá', '110426-sale-5, F4 - Loose Fit (Dáng Rộng), màu vàng, Quần áo, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
