INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_46a30466bb47495e', 'cat_tshirt', 'Áo Thun Tôn Dáng FlexFit™ Siêu Đàn Hồi Non Branded 054 Màu Hồng Dáng Ôm Vừa F2', 'ao-thun-ton-dang-flexfit-sieu-dan-hoi-non-branded-054-mau-hong-dang-om-vua-f2', '0024617', 'Áo Thun Cổ Tròn Tay Ngắn Non Branded 054 1. Kỹ Thuật Rập "Grading" – Chuẩn Mực Slim Fit Mới Phom dáng Slim Fit của sản phẩm không chỉ là may nhỏ lại, mà là kết quả của quá trình tinh chỉnh rập (Grading) kỹ lưỡng từ phom gốc: Thân trên gọn gàng: Giảm 2cm ở ngực và vai để loại bỏ độ rộng thừa, giúp áo', 'Áo Thun Cổ Tròn Tay Ngắn Non Branded 054 1. Kỹ Thuật Rập "Grading" – Chuẩn Mực Slim Fit Mới Phom dáng Slim Fit của sản phẩm không chỉ là may nhỏ lại, mà là kết quả của quá trình tinh chỉnh rập (Grading) kỹ lưỡng từ phom gốc: Thân trên gọn gàng: Giảm 2cm ở ngực và vai để loại bỏ độ rộng thừa, giúp áo đứng phom. Hiệu ứng Tapered Hem: Lai áo được thu hẹp 4cm, tạo độ thắt nhẹ ở hông, khắc phục hoàn toàn tình trạng áo bị xòe hoặc bùng nhùng khi mặc. Tay áo tinh tế: Cửa tay giảm 1cm để ôm nhẹ bắp tay, tạo cảm giác khỏe khoắn. 2. Công Nghệ Vải FlexFit™ – Vận Động Không Giới Hạn Sản phẩm sử dụng dòng vải FlexFit™ Cotton Plus Single với công thức vật liệu vượt trội: Co giãn 4 chiều: Tỷ lệ 8% Spandex (cao gấp đôi thông thường) mang lại khả năng đàn hồi và hồi phục form tức thì, cho phép vận động mạnh mà không gò bó. Thoáng khí AirDry™: Kết cấu dệt Single Jersey kết hợp 92% Cotton tạo các khoảng hở vi mô giúp thoát ẩm nhanh, không gây bí bách. Định lượng 180gsm: Mức trọng lượng trung bình (Mid-weight) lý tưởng, đủ dày để không lộ nhưng vẫn nhẹ nhàng cho khí hậu nhiệt đới. 3. Chi Tiết Gia Cố Bền Bỉ Áo được may kỹ thuật cao với chi tiết cổ phối bán nguyệt (Half-moon Yoke) ốp bên trong. Chi tiết này không chỉ tăng tính thẩm mỹ mà còn giúp định hình vòng cổ chắc chắn, hạn chế tối đa tình trạng bai dão sau nhiều lần giặt. TỔNG KẾT Non Branded 054 là giải pháp cân bằng hoàn hảo giữa thẩm mỹ và công năng. Với kỹ thuật giảm lai 4cm để tôn dáng và chất liệu 8% Spandex co giãn như đồ thể thao, đây là chiếc áo thun lý tưởng cho người đàn ông hiện đại cần sự chỉn chu nhưng không muốn hy sinh sự thoải mái. THÔNG TIN NHANH Chất liệu: FlexFit™ Cotton Plus Single 180gsm, 92% Cotton 8% Spandex Chi tiết sản phẩm: Slim Fit, Lai Tapered (thu gọn), Cổ phối bán nguyệt. Lưu ý giặt ủi: Giặt máy chế độ nhẹ, lộn trái sản phẩm. Tuyệt đối KHÔNG sấy nóng để bảo vệ sợi Spandex. Ủi ở nhiệt độ thấp (khuyến nghị 110°C).', 'YAME', 95250, 127000, true, 25.0, 1717, 432, 4.4, 95, 'active', false, true, false, 'Áo Thun Tôn Dáng FlexFit™ Siêu Đàn Hồi Non Branded 054 Màu Hồng Dáng Ôm Vừa F2', 'Áo Thun Cổ Tròn Tay Ngắn Non Branded 054 1. Kỹ Thuật Rập "Grading" – Chuẩn Mực Slim Fit Mới Phom dáng Slim Fit của sản phẩm không chỉ là may nhỏ lại, mà là kết quả của quá trình tinh chỉnh rập (Grading) kỹ lưỡng từ phom gốc: Thân trên gọn gàng: Giảm 2cm ở ngực và vai để loại bỏ độ rộng thừa, giúp áo', '010426-sale, 010426-sale-quanao25, F2 - Slim Fit (Dáng Ôm Vừa), Gu đơn giản, màu hồng, Quần áo, Thời Trang Đơn Giản, Áo, Áo thun', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_1145fa793ad74906', 'cat_tshirt', 'Áo Thun Tôn Dáng FlexFit™ Siêu Đàn Hồi Non Branded 054 Màu Đỏ Đậm Dáng Ôm Vừa F2', 'ao-thun-ton-dang-flexfit-sieu-dan-hoi-non-branded-054-mau-do-dam-dang-om-vua-f2', '0024616', 'Áo Thun Cổ Tròn Tay Ngắn Non Branded 054 1. Kỹ Thuật Rập "Grading" – Chuẩn Mực Slim Fit Mới Phom dáng Slim Fit của sản phẩm không chỉ là may nhỏ lại, mà là kết quả của quá trình tinh chỉnh rập (Grading) kỹ lưỡng từ phom gốc: Thân trên gọn gàng: Giảm 2cm ở ngực và vai để loại bỏ độ rộng thừa, giúp áo', 'Áo Thun Cổ Tròn Tay Ngắn Non Branded 054 1. Kỹ Thuật Rập "Grading" – Chuẩn Mực Slim Fit Mới Phom dáng Slim Fit của sản phẩm không chỉ là may nhỏ lại, mà là kết quả của quá trình tinh chỉnh rập (Grading) kỹ lưỡng từ phom gốc: Thân trên gọn gàng: Giảm 2cm ở ngực và vai để loại bỏ độ rộng thừa, giúp áo đứng phom. Hiệu ứng Tapered Hem: Lai áo được thu hẹp 4cm, tạo độ thắt nhẹ ở hông, khắc phục hoàn toàn tình trạng áo bị xòe hoặc bùng nhùng khi mặc. Tay áo tinh tế: Cửa tay giảm 1cm để ôm nhẹ bắp tay, tạo cảm giác khỏe khoắn. 2. Công Nghệ Vải FlexFit™ – Vận Động Không Giới Hạn Sản phẩm sử dụng dòng vải FlexFit™ Cotton Plus Single với công thức vật liệu vượt trội: Co giãn 4 chiều: Tỷ lệ 8% Spandex (cao gấp đôi thông thường) mang lại khả năng đàn hồi và hồi phục form tức thì, cho phép vận động mạnh mà không gò bó. Thoáng khí AirDry™: Kết cấu dệt Single Jersey kết hợp 92% Cotton tạo các khoảng hở vi mô giúp thoát ẩm nhanh, không gây bí bách. Định lượng 180gsm: Mức trọng lượng trung bình (Mid-weight) lý tưởng, đủ dày để không lộ nhưng vẫn nhẹ nhàng cho khí hậu nhiệt đới. 3. Chi Tiết Gia Cố Bền Bỉ Áo được may kỹ thuật cao với chi tiết cổ phối bán nguyệt (Half-moon Yoke) ốp bên trong. Chi tiết này không chỉ tăng tính thẩm mỹ mà còn giúp định hình vòng cổ chắc chắn, hạn chế tối đa tình trạng bai dão sau nhiều lần giặt. TỔNG KẾT Non Branded 054 là giải pháp cân bằng hoàn hảo giữa thẩm mỹ và công năng. Với kỹ thuật giảm lai 4cm để tôn dáng và chất liệu 8% Spandex co giãn như đồ thể thao, đây là chiếc áo thun lý tưởng cho người đàn ông hiện đại cần sự chỉn chu nhưng không muốn hy sinh sự thoải mái. THÔNG TIN NHANH Chất liệu: FlexFit™ Cotton Plus Single 180gsm, 92% Cotton 8% Spandex Chi tiết sản phẩm: Slim Fit, Lai Tapered (thu gọn), Cổ phối bán nguyệt. Lưu ý giặt ủi: Giặt máy chế độ nhẹ, lộn trái sản phẩm. Tuyệt đối KHÔNG sấy nóng để bảo vệ sợi Spandex. Ủi ở nhiệt độ thấp (khuyến nghị 110°C).', 'YAME', 95250, 127000, true, 25.0, 2922, 444, 4.9, 22, 'active', false, true, false, 'Áo Thun Tôn Dáng FlexFit™ Siêu Đàn Hồi Non Branded 054 Màu Đỏ Đậm Dáng Ôm Vừa F2', 'Áo Thun Cổ Tròn Tay Ngắn Non Branded 054 1. Kỹ Thuật Rập "Grading" – Chuẩn Mực Slim Fit Mới Phom dáng Slim Fit của sản phẩm không chỉ là may nhỏ lại, mà là kết quả của quá trình tinh chỉnh rập (Grading) kỹ lưỡng từ phom gốc: Thân trên gọn gàng: Giảm 2cm ở ngực và vai để loại bỏ độ rộng thừa, giúp áo', '010426-sale, 010426-sale-quanao25, F2 - Slim Fit (Dáng Ôm Vừa), Gu đơn giản, màu đỏ, Quần áo, Thời Trang Đơn Giản, Áo, Áo thun', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
