INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_a0f786cf9e2a4518', 'cat_tshirt', 'Áo Thun FlexFit™ Cotton Thoáng Da "BE KIND BE YOU" The No Style 113 Màu Trắng Dáng Rộng Rãi F4', 'ao-thun-flexfit-cotton-thoang-da-be-kind-be-you-the-no-style-113-mau-trang-dang-rong-rai-f4', '0023367', 'ID sản phẩm: The No Style 113 Áo thun dáng rộng Cotton Compact co giãn, thoáng mát, in Trame. 1. Kiểu sản phẩm: Áo Thun Cổ Tròn Tay Ngắn 2. Ưu điểm: -Vải Cotton cao cấp: Vải Cotton Compact 2S cao cấp, mềm mại, thoát ẩm tốt, giúp bạn luôn khô thoáng. -Hình in độc đáo: Hình in lấy cảm hứng từ tượng đi', 'ID sản phẩm: The No Style 113 Áo thun dáng rộng Cotton Compact co giãn, thoáng mát, in Trame. 1. Kiểu sản phẩm: Áo Thun Cổ Tròn Tay Ngắn 2. Ưu điểm: -Vải Cotton cao cấp: Vải Cotton Compact 2S cao cấp, mềm mại, thoát ẩm tốt, giúp bạn luôn khô thoáng. -Hình in độc đáo: Hình in lấy cảm hứng từ tượng điêu khắc Hy Lạp độc đáo, tạo điểm nhấn cho chiếc áo. -In bền màu, sắc nét: In bằng công nghệ in trame và in dẻo, tạo hình ảnh sắc nét, bền màu, không bong tróc. 3. Chất liệu: Vải cotton compact 2S(100% Cotton) 4. Kỹ thuật: Áo được in bằng công nghệ in trame và in dẻo, tạo nên những hình ảnh sắc nét, bền màu và không bị bong tróc. 5. Phù hợp với ai: Phù hợp với mọi người, đặc biệt là những ai yêu thích phong cách đơn giản, thoải mái. 6. Thuộc Bộ Sưu Tập: NoStyle, gu nào cũng có, mặc đẹp, mặc độc, mặc đúng mốt. Không giới hạn phong cách, từ tối giản đến phá cách, giúp bạn mặc đẹp, mặc độc, mặc đúng mốt. 7. Các tên thường gọi hoặc tìm kiếm về sản phẩm này: Áo thun cổ tròn, Áo thun tay ngắn, Áo thun form rộng, Áo thun in hình.', 'YAME', 235450, 277000, true, 15.0, 185, 23, 4.0, 40, 'active', false, true, false, 'Áo Thun Flex