INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_123f977a280f462e', 'cat_tshirt', 'Áo Thun FlexFit™ Siêu Co Giãn Lai V Tôn Dáng The Trainer 001 Màu Đen Dáng Ôm Vừa F2', 'ao-thun-flexfit-sieu-co-gian-lai-v-ton-dang-the-trainer-001-mau-den-dang-om-vua-f2', '0024055', 'Áo Thun Cổ Tròn Tay Ngắn FlexFit™ The Trainer 001 1. Kỹ thuật Rập Anatomic Contouring (Điêu khắc hình thể) Cấu trúc V-shape: Thực hiện cắt giảm mạnh thông số chiều ngang với phần ngực giảm 4cm và lai giảm 5cm so với thông số thông thường. Kỹ thuật này tạo độ ôm sát cơ thể (Compression Fit), giúp tôn', 'Áo Thun Cổ Tròn Tay Ngắn FlexFit™ The Trainer 001 1. Kỹ thuật Rập Anatomic Contouring (Điêu khắc hình thể) Cấu trúc V-shape: Thực hiện cắt giảm mạnh thông số chiều ngang với phần ngực giảm 4cm và lai giảm 5cm so với thông số thông thường. Kỹ thuật này tạo độ ôm sát cơ thể (Compression Fit), giúp tôn vinh đường nét cơ bắp và loại bỏ vải thừa gây cản trở. Tối ưu hóa chi trên: Thu hẹp vai 2cm và ngắn tay 3cm nhằm khoe trọn nhóm cơ Delta, bắp tay, đồng thời giảm ma sát tại vùng nách khi thực hiện các động tác đẩy/kéo. Kỹ thuật High Scye (Nâng đáy nách): Đáy nách được nâng cao thêm 0.4cm giúp áo bám sát chuyển động vai (Lift function), ngăn hiện tượng thân áo bị kéo xô lệch khi giơ tay cao. 2. Công nghệ Vật liệu FlexFit™ Nylon Ultra Jersey Cân bằng độ dày: Vải có định lượng 175gsm (Medium Weight), đủ nhẹ để thoáng mát nhưng đủ đầm tay để giữ phom dáng sắc nét, không bị dính da khi đổ mồ hôi. Độ đàn hồi vượt trội: Thành phần chứa 13% Spandex cho khả năng co giãn 4 chiều, giúp vải quay về trạng thái ban đầu ngay sau khi kéo căng, hạn chế tối đa tình trạng biến dạng cấu trúc sau nhiều lần giặt. 3. Kết cấu May &amp; Hệ thống Thông gió Panel Integration (Phối lưới): Sử dụng máy chắp chuyên dụng ráp nối các mảng lưới tại vai và sườn, tạo hệ thống thông gió (Ventilation System) giúp thoát nhiệt nhanh. Đường may Flatlock: Các đường ráp nối được xử lý phẳng mịn, giảm độ cộm, tránh gây kích ứng da trong quá trình vận động mạnh. Gia cố tà áo: Thiết kế xẻ sườn, diễu định hình và đánh bọ chốt giúp tăng biên độ mở hông, hỗ trợ các bài tập chân như Squat hay Lunge. 4. Tiêu chuẩn Hoàn thiện Công nghiệp Bảo vệ cấu trúc vải: Sử dụng kim siêu nhỏ để may toàn bộ sản phẩm, ngăn chặn hiện tượng đứt sợi hoặc tạo lỗ kim trên bề mặt vải Nylon Jersey. Định hình lai (Hemming): Lai tay và lai áo may Kansai 2cm giúp giữ phom phẳng phiu, không bị quăn mép. Clean Finish: Đường may cổ sau được bọc viền tỉ mỉ, triệt tiêu ma sát gây ngứa vùng gáy. An toàn đêm: Logo Heat-transfer phản quang giúp tăng tính', 'YAME', 222750, 297000, true, 25.0, 3736, 260, 4.4, 57, 'active', false, true, true, 'Áo Thun FlexFit™ Siêu Co Giãn Lai V Tôn Dáng The Trainer 001 Màu Đen Dáng Ôm Vừa F2', 'Áo Thun Cổ Tròn Tay Ngắn FlexFit™ The Trainer 001 1. Kỹ thuật Rập Anatomic Contouring (Điêu khắc hình thể) Cấu trúc V-shape: Thực hiện cắt giảm mạnh thông số chiều ngang với phần ngực giảm 4cm và lai giảm 5cm so với thông số thông thường. Kỹ thuật này tạo độ ôm sát cơ thể (Compression Fit), giúp tôn', '010426-sale, 010426-sale-quanao25, Công Nghệ, F2 - Slim Fit (Dáng Ôm Vừa), Gu thể thao, màu đen, Quần áo, Thời Trang Thể Thao, Áo, Áo thun', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
