INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_18db1626c7044611', 'cat_polo', 'Áo Polo Khóa Kéo ColorLock™ Vải Thoát Nhiệt Vải Chống Lem Màu The Weekend 006 Màu Trắng Xanh Dương Dáng Vừa Vặn F3', 'ao-polo-khoa-keo-colorlock-vai-thoat-nhiet-vai-chong-lem-mau-the-weekend-006-mau-trang-xanh-duong-dang-vua-van-f3', '0024818', 'Áo Thun Cổ Polo Tay Ngắn ColorLock™ The Weekend 006 1. Chuẩn mực ColorLock™ Sử dụng kỹ thuật nhuộm sợi từ lõi (Yarn-Dyed) trước khi dệt. Các đường sọc màu được tách biệt hoàn toàn, đảm bảo không nhiễm màu chéo và giữ độ sắc nét bền bỉ theo thời gian. 2. Kết cấu vải Pique 215gsm Kiểu dệt mắt lưới tổ ', 'Áo Thun Cổ Polo Tay Ngắn ColorLock™ The Weekend 006 1. Chuẩn mực ColorLock™ Sử dụng kỹ thuật nhuộm sợi từ lõi (Yarn-Dyed) trước khi dệt. Các đường sọc màu được tách biệt hoàn toàn, đảm bảo không nhiễm màu chéo và giữ độ sắc nét bền bỉ theo thời gian. 2. Kết cấu vải Pique 215gsm Kiểu dệt mắt lưới tổ ong tạo các "cửa thông gió" tự nhiên giúp áo dày dặn, đứng phom nhưng vẫn thoát nhiệt cực tốt, mang lại sự thông thoáng trong thời tiết nóng ẩm. 3. Hệ rập Regular Fit Tối ưu vận động Thiết kế nách tròn kết hợp chất liệu co giãn: giúp cử động tay linh hoạt. Chi tiết xẻ tà: giúp vạt áo luôn phẳng phiu, không bị đùn hay giật ngược khi ngồi. 4. Gia cố độ bền phom dáng Đường vai chạy dây chống giãn: ngăn chảy xệ. Cổ áo cấu trúc chân sơ mi (Collar Stand) kết hợp khóa kéo Zipper: giúp cổ luôn đứng vững, không bị đổ nếp. Phối chân cổ sau: Đóng vai trò làm khung giữ phom cổ đứng đẹp, không bị đổ. TỔNG KẾT The Weekend 006 là giải pháp trang phục chuyên nghiệp dành cho người năng động. Sản phẩm giải quyết triệt để bài toán kinh tế nhờ độ bền màu tuyệt đối và khả năng giữ phom dáng ổn định sau rất nhiều lần sử dụng. THÔNG TIN NHANH Chất liệu: ColorLock™ Cotton Blend Ultra Pique 215gsm, 65% Cotton 35% Polyester Chi tiết sản phẩm: F3 - Regular Fit (Dáng Tiêu Chuẩn), Cổ Zipper, Phối chân cổ giữ phom, xẻ tà. Lưu ý giặt / ủi Lộn trái khi giặt, Phơi trong bóng râm (kỵ nắng gắt để giữ sợi vải mềm mại).', 'YAME', 434150, 457000, true, 5.0, 3801, 388, 4.5, 168, 'active', false, true, false, 'Áo Polo Khóa Kéo ColorLock™ Vải Thoát Nhiệt Vải Chống Lem Màu The Weekend 006 Màu Trắng Xanh Dương Dáng Vừa Vặn F3', 'Áo Thun Cổ Polo Tay Ngắn ColorLock™ The Weekend 006 1. Chuẩn mực ColorLock™ Sử dụng kỹ thuật nhuộm sợi từ lõi (Yarn-Dyed) trước khi dệt. Các đường sọc màu được tách biệt hoàn toàn, đảm bảo không nhiễm màu chéo và giữ độ sắc nét bền bỉ theo thời gian. 2. Kết cấu vải Pique 215gsm Kiểu dệt mắt lưới tổ ', '110426-sale-5, màu trắng, Quần áo, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
