INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_0cc5a64cf6514b73', 'cat_polo', 'Áo Polo Cổ V Không Gò Bó FlexFit™ Co Giãn Êm Ái The Weekend 007 Màu Trắng Dáng Vừa Vặn F3', 'ao-polo-co-v-khong-go-bo-flexfit-co-gian-em-ai-the-weekend-007-mau-trang-dang-vua-van-f3', '0024824', 'Áo Thun Cổ Polo Tay Ngắn The Weekend 007 1. Thiết Kế Cổ V Johnny Collar Định Hình Cấu trúc: Thiết kế Johnny Collar (cổ bỏ khuy) phóng khoáng. Gia cố kỹ thuật: Trụ cổ được ép keo lụa bản to 2cm cắt xéo và gia cố đường may bọ (Bartack) tại chân trụ. Hiệu quả: Khắc phục hoàn toàn tình trạng cổ áo bị đổ', 'Áo Thun Cổ Polo Tay Ngắn The Weekend 007 1. Thiết Kế Cổ V Johnny Collar Định Hình Cấu trúc: Thiết kế Johnny Collar (cổ bỏ khuy) phóng khoáng. Gia cố kỹ thuật: Trụ cổ được ép keo lụa bản to 2cm cắt xéo và gia cố đường may bọ (Bartack) tại chân trụ. Hiệu quả: Khắc phục hoàn toàn tình trạng cổ áo bị đổ rạp hay nhăn nhúm. Cổ áo luôn đứng phom, phẳng phiu ngay cả sau khi giặt, giúp người mặc "lên đồ" nhanh gọn mà không cần chỉnh sửa. 2. Chất Liệu FlexFit™ Cotton Plus Jacquard Công nghệ dệt: Computerized Knit Jacquard (dệt vi tính). Hoa văn được tạo từ cấu trúc sợi đan cài, đảm bảo sắc nét và bền bỉ, không bong tróc như hình in. Thành phần ưu việt: 64% Cotton: Bề mặt bông xốp (Natural Touch), thoáng khí tối ưu nhờ công nghệ AirDry™. 32% Polyester: Giữ phom ổn định, chống chảy nhão. 4% Spandex: Tạo độ đàn hồi FlexFit™ &gt;90%, co giãn thoải mái theo chuyển động. 3. Kỹ Thuật Rập &amp; Phom Dáng Phom dáng: Regular Fit (suông tiêu chuẩn) phù hợp nhiều dáng người. Tối ưu vận động: Vòng nách được nâng cao (hạ nách giảm 0.4cm) giúp triệt tiêu vải thừa, tạo cảm giác gọn gàng và hạn chế giật lai áo khi giơ tay. Độ bền chi tiết: Đường ráp vai được chạy dây chống giãn (mobilon tape) chìm, giữ bờ vai luôn vuông vắn, không bị biến dạng khi treo móc. TỔNG KẾT The Weekend 007 chứng minh rằng để mặc đẹp, bạn không nhất thiết phải tốn nhiều công sức. Với cấu trúc vải Jacquard bền bỉ và thiết kế cổ Johnny Collar đã được định hình sẵn bằng kỹ thuật ép keo, chiếc áo này luôn trong trạng thái "sẵn sàng" ngay khi lấy ra khỏi tủ. Đây là khoản đầu tư xứng đáng cho những ai ưu tiên sự gãy gọn, tiện lợi và cần một trang phục "đa nhiệm" cho mọi hoàn cảnh. THÔNG TIN NHANH Chất liệu: FlexFit™ Cotton Plus Jacquard 190gsm, 64% Cotton 32% Polyester 4% Spandex Chi tiết sản phẩm: Regular Fit, Cổ V Johnny Collar không cúc, dệt Jacquard họa tiết chìm Lưu ý giặt / ủi: Lộn trái khi giặt/phơi; Giặt nước lạnh (&lt;40°C); Không sấy nóng; Ủi nhiệt độ thấp (110°C-120°C).', 'YAME', 301150, 317000, true, 5.0, 1168, 284, 4.0, 151, 'active', false, true, false, 'Áo Polo Cổ V Không Gò Bó FlexFit™ Co Giãn Êm Ái The Weekend 007 Màu Trắng Dáng Vừa Vặn F3', 'Áo Thun Cổ Polo Tay Ngắn The Weekend 007 1. Thiết Kế Cổ V Johnny Collar Định Hình Cấu trúc: Thiết kế Johnny Collar (cổ bỏ khuy) phóng khoáng. Gia cố kỹ thuật: Trụ cổ được ép keo lụa bản to 2cm cắt xéo và gia cố đường may bọ (Bartack) tại chân trụ. Hiệu quả: Khắc phục hoàn toàn tình trạng cổ áo bị đổ', '110426-sale-5, F3 - Regular Fit (Dáng Tiêu Chuẩn), màu trắng, Quần áo, signature, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
