INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_469bb17e300349bd', 'cat_polo', 'Áo Polo Sợi Làm Mát IceVibes™ Mặc Đi Nắng Giải Nhiệt Nhanh Chóng The Minimalist 015 Màu Xanh Dương Đậm 2 Form 10 Size', 'ao-polo-soi-lam-mat-icevibes-mac-di-nang-giai-nhiet-nhanh-chong-the-minimalist-015-mau-xanh-duong-dam-2-form-10-size', '0024898', 'Áo Thun Cổ Polo Tay Ngắn The Minimalist 015 1. Chất liệu IceVibes™ 260gsm: Giải nhiệt vật lý Sản phẩm sử dụng dòng vải IceVibes™ Polyester Plus Pique với định lượng dày dặn 260gsm, giúp áo lên phom đứng dáng. Công nghệ sợi Aerocool®: Sợi có thiết diện cắt ngang hình cỏ 4 lá (clover-leaf) tạo ra 4 rã', 'Áo Thun Cổ Polo Tay Ngắn The Minimalist 015 1. Chất liệu IceVibes™ 260gsm: Giải nhiệt vật lý Sản phẩm sử dụng dòng vải IceVibes™ Polyester Plus Pique với định lượng dày dặn 260gsm, giúp áo lên phom đứng dáng. Công nghệ sợi Aerocool®: Sợi có thiết diện cắt ngang hình cỏ 4 lá (clover-leaf) tạo ra 4 rãnh dọc thân sợi. Hiệu năng: Các rãnh này tối ưu hóa hiện tượng mao dẫn, giúp thoát nhiệt và mồ hôi tức thì. Độ bền tính năng: Khả năng làm mát đến từ cấu trúc vật lý của sợi nên tồn tại vĩnh viễn, không bị suy giảm sau nhiều lần giặt. 2. Công nghệ Bonding &amp; Trụ Zipper: Tối giản đường may Ép Seam &amp; Bonding: Loại bỏ đường chỉ may truyền thống ở tà và lai áo bằng máy ép áp suất, giúp gấu áo phẳng lì, mỏng nhẹ và liền mạch. Trụ khóa Zipper: Nẹp trụ được ủi định hình, may mí phản quang và ép keo chuyên dụng. Kỹ thuật này giúp dây kéo nằm phẳng tuyệt đối, loại bỏ lỗi lượn sóng (wavy) thường gặp. 3. Kỹ thuật "Khóa" Form: Gia cố điểm chịu lực Hệ thống gia cố kết cấu giúp tăng tuổi thọ sản phẩm tại các vị trí trọng yếu: Chống bai vai: Sử dụng dây chống giãn (Mobilon tape) chạy dọc đường may vai, giữ phom vai vuông vức, chống chảy xệ. Đường may chịu lực: Mật độ chỉ tiêu chuẩn 4.5 mũi/cm, đảm bảo đường may đanh chắc khi vải co giãn 4 chiều. Chống rách tà: Vị trí xẻ tà hông được gia cố bằng kỹ thuật đánh bọ (Bartack). 4. Hệ Thống Rập Dual-Fit: 2 Phom Dáng - 10 Dải Size Không áp đặt một chuẩn mực duy nhất, The Minimalist 015 phát triển song song hai bộ rập kỹ thuật: Regular Fit (Vừa vặn) và Loose Fit (Rộng rãi). Với tổng cộng 10 tùy chọn size, các điểm nhảy (grading) được tính toán chính xác để tương thích với độ co giãn 4 chiều, giúp bạn tìm được chiếc áo vừa vặn như may đo dù thuộc hình thể nào. TỔNG KẾT The Minimalist 015 là sự cân bằng giữa tính thẩm mỹ và hiệu năng kỹ thuật. Với chất liệu IceVibes™ 260gsm làm mát từ lõi sợi cùng công nghệ may Bonding hiện đại, sản phẩm đảm bảo sự chỉn chu, đứng dáng nhưng vẫn thoáng mát và bền bỉ theo thời gian. THÔNG TIN NHANH Chất liệu:', 'YAME', 377150, 397000, true, 5.0, 3250, 10, 4.1, 139, 'active', false, true, true, 'Áo Polo Sợi Làm Mát IceVibes™ Mặc Đi Nắng Giải Nhiệt Nhanh Chóng The Minimalist 015 Màu Xanh Dương Đậm 2 Form 10 Size', 'Áo Thun Cổ Polo Tay Ngắn The Minimalist 015 1. Chất liệu IceVibes™ 260gsm: Giải nhiệt vật lý Sản phẩm sử dụng dòng vải IceVibes™ Polyester Plus Pique với định lượng dày dặn 260gsm, giúp áo lên phom đứng dáng. Công nghệ sợi Aerocool®: Sợi có thiết diện cắt ngang hình cỏ 4 lá (clover-leaf) tạo ra 4 rã', '110426-sale-5, F3 - Regular Fit (Dáng Tiêu Chuẩn) & F4 - Loose Fit (Dáng Rộng), màu xanh dương, Quần áo, signature, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
