INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_70ed98e6c29640e1', 'cat_polo', 'Áo Polo Vải Cá Sấu Phối Mảng Màu AirDry™ Mặc Nhẹ Thoát Mồ Hôi Tốt The Weekend 003 Màu Nâu Xanh Lá Dáng Vừa Vặn F3', 'ao-polo-vai-ca-sau-phoi-mang-mau-airdry-mac-nhe-thoat-mo-hoi-tot-the-weekend-003-mau-nau-xanh-la-dang-vua-van-f3', '0024768', 'Áo Thun Cổ Polo Tay Ngắn The Weekend 003 1. Tinh Tế Trong Từng Đường Kẻ (Yarn-Dye &amp; Canh Sọc) The Weekend 003 nâng tầm chiếc áo Polo cơ bản bằng công nghệ dệt Yarn-Dye (nhuộm sợi), trong đó các sợi vải được nhuộm màu riêng biệt trước khi dệt thay vì in ấn thông thường. Điều này mang lại họa tiết', 'Áo Thun Cổ Polo Tay Ngắn The Weekend 003 1. Tinh Tế Trong Từng Đường Kẻ (Yarn-Dye &amp; Canh Sọc) The Weekend 003 nâng tầm chiếc áo Polo cơ bản bằng công nghệ dệt Yarn-Dye (nhuộm sợi), trong đó các sợi vải được nhuộm màu riêng biệt trước khi dệt thay vì in ấn thông thường. Điều này mang lại họa tiết sọc sắc nét, có chiều sâu và bền màu tuyệt đối. Đặc biệt, kỹ thuật may "Canh Sọc" (Stripe Matching) được áp dụng khắt khe, đảm bảo các đường kẻ nối liền mạch hoàn hảo, không lệch pha giữa thân và tay áo. 2. Phom Dáng Regular Fit Tối Ưu Dựa trên nền tảng Regular Fit thoải mái, sản phẩm được đội ngũ thiết kế rập tinh chỉnh bằng cách giảm vòng nách 0.4cm và nâng nhẹ đáy nách. Thay đổi nhỏ này giúp triệt tiêu lượng vải thừa dưới cánh tay, giúp người mặc trông gọn gàng hơn mà vẫn đảm bảo cử động thoải mái. Phần cổ áo sử dụng công nghệ ép keo phối hợp (Keo vải &amp; Keo lụa), giúp lá cổ luôn phẳng phiu và đứng dáng sang trọng. 3. Công Nghệ Vải AirDry™ Thoáng Mát Sản phẩm sử dụng chất liệu AirDry™ Polyester Basic Pique với định lượng 180gsm (Lightweight) mỏng nhẹ. Cấu trúc dệt mắt lưới cá sấu (Pique) tạo ra các lỗ thông hơi tự nhiên, kết hợp với tỷ lệ vàng 54% Polyester - 43% Cotton giúp áo vừa hút ẩm tốt, vừa đẩy hơi ẩm bay hơi nhanh chóng, giữ cơ thể luôn khô thoáng. TỔNG KẾT The Weekend 003 không chỉ là một chiếc áo để mặc đẹp, mà là một sản phẩm được thiết kế để bền bỉ và tôn dáng. Từ kỹ thuật dệt nhuộm sợi cao cấp đến những tinh chỉnh nhỏ nhất ở vòng nách và cổ áo, tất cả tạo nên một tổng thể hoàn hảo cho quý ông hiện đại – người luôn đòi hỏi sự chỉn chu trong mọi hoàn cảnh. THÔNG TIN NHANH Chất liệu: AirDry™ Polyester Basic Pique 180gsm, 54% Polyester - 43% Cotton - 3% Spandex Chi tiết sản phẩm: Cổ ép keo đứng form, Vai chạy dây chống giãn (mobilon tape), Sọc dệt Yarn-Dye Lưu ý giặt / ủi: Giặt nước &lt; 40°C, Bắt buộc lộn trái, Phơi vắt ngang trong bóng râm, Ủi 110°C – 120°C (Ký hiệu bàn ủi 1 chấm •) Xuất xứ: Việt Nam', 'YAME', 377150, 397000, true, 5.0, 4942, 424, 4.3, 12, 'active', false, true, false, 'Áo Polo Vải Cá Sấu Phối Mảng Màu AirDry™ Mặc Nhẹ Thoát Mồ Hôi Tốt The Weekend 003 Màu Nâu Xanh Lá Dáng Vừa Vặn F3', 'Áo Thun Cổ Polo Tay Ngắn The Weekend 003 1. Tinh Tế Trong Từng Đường Kẻ (Yarn-Dye &amp; Canh Sọc) The Weekend 003 nâng tầm chiếc áo Polo cơ bản bằng công nghệ dệt Yarn-Dye (nhuộm sợi), trong đó các sợi vải được nhuộm màu riêng biệt trước khi dệt thay vì in ấn thông thường. Điều này mang lại họa tiết', '130426-sale-5, F3 - Regular Fit (Dáng Tiêu Chuẩn), màu nâu, Quần áo, signature, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
