INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_f9083313e1204f75', 'cat_polo', 'Áo Polo Dáng Vuông Che Khuyết Điểm FlexFit™ Co Giãn Thoải Mái The Worker 005 Màu Xanh Dương Đậm Dáng Rộng Rãi F4', 'ao-polo-dang-vuong-che-khuyet-diem-flexfit-co-gian-thoai-mai-the-worker-005-mau-xanh-duong-dam-dang-rong-rai-f4', '0024815', 'Áo Thun Cổ Polo Tay Ngắn FlexFit™ The Worker 005 1. Chất liệu FlexFit™ (260gsm) – Dày dặn &amp; Thoáng khí Định lượng 260gsm: Vải dày dặn, tạo độ đứng phom tự nhiên nhưng không gây bí bách. 100% Cotton Compact: Công nghệ sợi nén giúp bề mặt vải đanh mịn, hạn chế tối đa tình trạng xù lông (pilling) s', 'Áo Thun Cổ Polo Tay Ngắn FlexFit™ The Worker 005 1. Chất liệu FlexFit™ (260gsm) – Dày dặn &amp; Thoáng khí Định lượng 260gsm: Vải dày dặn, tạo độ đứng phom tự nhiên nhưng không gây bí bách. 100% Cotton Compact: Công nghệ sợi nén giúp bề mặt vải đanh mịn, hạn chế tối đa tình trạng xù lông (pilling) sau khi giặt. Co giãn cơ học: Không pha Spandex, vải vẫn có độ đàn hồi nhờ cấu trúc dệt Single Jersey, đảm bảo thấm hút và thoát ẩm vượt trội. 2. Kỹ thuật rập Boxy Shape – Tối ưu vận động Vai trễ (Drop Shoulder): Tăng thông số vai thêm 8cm, hạ thấp điểm rơi để giải phóng áp lực lên cơ vai khi cử động. Cân bằng nách: Giảm nhẹ vòng nách 0.4cm giúp vùng dưới cánh tay ôm gọn, không bị đùn vải thừa gây mất thẩm mỹ. Form suông rộng: Nới rộng ngực và lai áo (+2cm), giúp che khuyết điểm vòng bụng hiệu quả. 3. Chi tiết hoàn thiện &amp; Độ bền kết cấu Gia cố vai: Đường ráp vai được may kẹp dây chống giãn (mobilon tape) để chống chảy xệ theo thời gian. Ép keo định hình: Nẹp nút và đáp túi sử dụng keo lụa UD9975 cao cấp, giúp cổ áo luôn phẳng phiu, không gãy gập. Túi ngực đa năng: Thiết kế khe cắm bút riêng biệt, được đóng bọ (bartacking) 6mm chắc chắn tại các điểm chịu lực để chống rách. TỔNG KẾT The Worker 005 là sự kết hợp giữa phom dáng Boxy thoải mái và độ bền kỹ thuật cao. Với chất liệu Cotton Compact 260gsm và các chi tiết gia cố chuyên sâu, sản phẩm đảm bảo giữ phom ổn định và mang lại trải nghiệm mặc "dễ thở" suốt ngày dài. THÔNG TIN NHANH Chất liệu: FlexFit™ Cotton Basic Single (100% Compact Cotton) - 260gsm. Chi tiết sản phẩm: Phom Boxy (Loose Fit), túi ngực có khe bút, cổ ép keo định hình, gia cố vai mobilon. Lưu ý giặt ủi: Giặt máy chế độ thường (nước &lt; 40°C), không dùng thuốc tẩy Clo, giũ mạnh cho phẳng trước khi phơi, ủi ở nhiệt độ trung bình (160–200°C).', 'YAME', 310650, 327000, true, 5.0, 2032, 26, 4.8, 198, 'active', true, true, false, 'Áo Polo Dáng Vuông Che Khuyết Điểm FlexFit™ Co Giãn Thoải Mái The Worker 005 Màu Xanh Dương Đậm Dáng Rộng Rãi F4', 'Áo Thun Cổ Polo Tay Ngắn FlexFit™ The Worker 005 1. Chất liệu FlexFit™ (260gsm) – Dày dặn &amp; Thoáng khí Định lượng 260gsm: Vải dày dặn, tạo độ đứng phom tự nhiên nhưng không gây bí bách. 100% Cotton Compact: Công nghệ sợi nén giúp bề mặt vải đanh mịn, hạn chế tối đa tình trạng xù lông (pilling) s', 'F4 - Loose Fit (Dáng Rộng), Gu đơn giản, màu xanh dương, Quần áo, signature0226, signature0426, Thời Trang Đơn Giản, Áo, Áo thun', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
