INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_0cbde54ede414e52', 'cat_polo', 'Áo Polo Sọc Tay Trẻ Trung FlexFit™ Vải Mềm Mịn Vai Raglan Cử Động Thoải Mái The No Style 240 Màu Xanh Lá Trắng Dáng Rộng Rãi F4', 'ao-polo-soc-tay-tre-trung-flexfit-vai-mem-min-vai-raglan-cu-dong-thoai-mai-the-no-style-240-mau-xanh-la-trang-dang-rong-rai-f4', '0024830', 'Áo Thun Cổ Polo Tay Ngắn FlexFit™ The No Style 240 ĐIỂM NHẤN CẤU TRÚC &amp; PHOM DÁNG Hệ rập Loose Fit: Thiết kế phom hộp (Boxy Shape) hiện đại, nới rộng thông số ngực và hạ sâu nách giúp áo không bám dính vào cơ thể, che khuyết điểm vòng bụng hiệu quả. Cấu trúc Raglan trễ vai: Loại bỏ đường may tại', 'Áo Thun Cổ Polo Tay Ngắn FlexFit™ The No Style 240 ĐIỂM NHẤN CẤU TRÚC &amp; PHOM DÁNG Hệ rập Loose Fit: Thiết kế phom hộp (Boxy Shape) hiện đại, nới rộng thông số ngực và hạ sâu nách giúp áo không bám dính vào cơ thể, che khuyết điểm vòng bụng hiệu quả. Cấu trúc Raglan trễ vai: Loại bỏ đường may tại đỉnh vai, kết hợp tăng chiều dài tay giúp giải phóng hoàn toàn cử động vùng cánh tay, tạo cảm giác thoải mái tuyệt đối. Tỉ lệ cân đối: Chiều dài áo được tính toán nhảy size theo chiều dọc, đảm bảo độ phủ mông chuẩn xác và giữ phom dáng chỉn chu cho người mặc. VẬT LIỆU &amp; CÔNG NGHỆ HOÀN THIỆN FlexFit™ Cotton 225gsm: Chất liệu 100% Compact Cotton dệt Single Jersey với bề mặt mịn màng, dai chắc, hạn chế tối đa tình trạng xù lông và bai dão sau nhiều lần giặt. Cổ áo định hình: Gia cố bằng lớp keo lụa chuyên dụng giúp cổ áo luôn ngay ngắn, đứng phom lịch sự nhưng vẫn giữ được độ mềm mại đặc trưng của sợi tự nhiên. Kỹ thuật may gia cố: Trụ khóa được xử lý chốt chặn và viền tỉ mỉ giúp chống rách vải. Mật độ chỉ dày đảm bảo độ bền vững cho các đường ráp sườn khi vận động mạnh. TỔNG KẾT The No Style 240 là giải pháp cân bằng giữa vật liệu bền bỉ và cấu trúc Raglan tự do, mang lại trải nghiệm mặc thoáng mát, che khuyết điểm hiệu quả cho người yêu thích phong cách tối giản. THÔNG TIN NHANH Chất liệu: FlexFit™ Cotton Basic Single 225gsm, 100% Cotton (Cotton Compact). Chi tiết sản phẩm: F4 - Loose Fit (Dáng Rộng), tay Raglan, trụ khóa dây kéo. Lưu ý giặt/ủi: Giặt máy chế độ thường (&lt; 40°C), lộn trái khi phơi, không dùng thuốc tẩy chứa Clo, ủi ở nhiệt độ trung bình (160–200°C).', 'YAME', 282150, 297000, true, 5.0, 1369, 405, 4.6, 94, 'active', false, true, false, 'Áo Polo Sọc Tay Trẻ Trung FlexFit™ Vải Mềm Mịn Vai Raglan Cử Động Thoải Mái The No Style 240 Màu Xanh Lá Trắng Dáng Rộng Rãi F4', 'Áo Thun Cổ Polo Tay Ngắn FlexFit™ The No Style 240 ĐIỂM NHẤN CẤU TRÚC &amp; PHOM DÁNG Hệ rập Loose Fit: Thiết kế phom hộp (Boxy Shape) hiện đại, nới rộng thông số ngực và hạ sâu nách giúp áo không bám dính vào cơ thể, che khuyết điểm vòng bụng hiệu quả. Cấu trúc Raglan trễ vai: Loại bỏ đường may tại', 'F4 - Loose Fit (Dáng Rộng), Gu thiết kế, màu xanh lá, Quần áo, signature0226, signature0426, Thời Trang Không Đơn Giản, Áo, Áo thun', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_d0ba3424ccae4db4', 'cat_polo', 'Áo Polo Sọc Tay Trẻ Trung FlexFit™ Vải Mềm Mịn Vai Raglan Cử Động Thoải Mái The No Style 240 Màu Xanh Dương Xám Dáng Rộng Rãi F4', 'ao-polo-soc-tay-tre-trung-flexfit-vai-mem-min-vai-raglan-cu-dong-thoai-mai-the-no-style-240-mau-xanh-duong-xam-dang-rong-rai-f4', '0024831', 'Áo Thun Cổ Polo Tay Ngắn FlexFit™ The No Style 240 ĐIỂM NHẤN CẤU TRÚC &amp; PHOM DÁNG Hệ rập Loose Fit: Thiết kế phom hộp (Boxy Shape) hiện đại, nới rộng thông số ngực và hạ sâu nách giúp áo không bám dính vào cơ thể, che khuyết điểm vòng bụng hiệu quả. Cấu trúc Raglan trễ vai: Loại bỏ đường may tại', 'Áo Thun Cổ Polo Tay Ngắn FlexFit™ The No Style 240 ĐIỂM NHẤN CẤU TRÚC &amp; PHOM DÁNG Hệ rập Loose Fit: Thiết kế phom hộp (Boxy Shape) hiện đại, nới rộng thông số ngực và hạ sâu nách giúp áo không bám dính vào cơ thể, che khuyết điểm vòng bụng hiệu quả. Cấu trúc Raglan trễ vai: Loại bỏ đường may tại đỉnh vai, kết hợp tăng chiều dài tay giúp giải phóng hoàn toàn cử động vùng cánh tay, tạo cảm giác thoải mái tuyệt đối. Tỉ lệ cân đối: Chiều dài áo được tính toán nhảy size theo chiều dọc, đảm bảo độ phủ mông chuẩn xác và giữ phom dáng chỉn chu cho người mặc. VẬT LIỆU &amp; CÔNG NGHỆ HOÀN THIỆN FlexFit™ Cotton 225gsm: Chất liệu 100% Compact Cotton dệt Single Jersey với bề mặt mịn màng, dai chắc, hạn chế tối đa tình trạng xù lông và bai dão sau nhiều lần giặt. Cổ áo định hình: Gia cố bằng lớp keo lụa chuyên dụng giúp cổ áo luôn ngay ngắn, đứng phom lịch sự nhưng vẫn giữ được độ mềm mại đặc trưng của sợi tự nhiên. Kỹ thuật may gia cố: Trụ khóa được xử lý chốt chặn và viền tỉ mỉ giúp chống rách vải. Mật độ chỉ dày đảm bảo độ bền vững cho các đường ráp sườn khi vận động mạnh. TỔNG KẾT The No Style 240 là giải pháp cân bằng giữa vật liệu bền bỉ và cấu trúc Raglan tự do, mang lại trải nghiệm mặc thoáng mát, che khuyết điểm hiệu quả cho người yêu thích phong cách tối giản. THÔNG TIN NHANH Chất liệu: FlexFit™ Cotton Basic Single 225gsm, 100% Cotton (Cotton Compact). Chi tiết sản phẩm: F4 - Loose Fit (Dáng Rộng), tay Raglan, trụ khóa dây kéo. Lưu ý giặt/ủi: Giặt máy chế độ thường (&lt; 40°C), lộn trái khi phơi, không dùng thuốc tẩy chứa Clo, ủi ở nhiệt độ trung bình (160–200°C).', 'YAME', 282150, 297000, true, 5.0, 2873, 213, 4.8, 19, 'active', false, true, false, 'Áo Polo Sọc Tay Trẻ Trung FlexFit™ Vải Mềm Mịn Vai Raglan Cử Động Thoải Mái The No Style 240 Màu Xanh Dương Xám Dáng Rộng Rãi F4', 'Áo Thun Cổ Polo Tay Ngắn FlexFit™ The No Style 240 ĐIỂM NHẤN CẤU TRÚC &amp; PHOM DÁNG Hệ rập Loose Fit: Thiết kế phom hộp (Boxy Shape) hiện đại, nới rộng thông số ngực và hạ sâu nách giúp áo không bám dính vào cơ thể, che khuyết điểm vòng bụng hiệu quả. Cấu trúc Raglan trễ vai: Loại bỏ đường may tại', '110426-sale-5, F4 - Loose Fit (Dáng Rộng), Gu thiết kế, màu xanh dương, Quần áo, signature0226, signature0426, Thời Trang Không Đơn Giản, Áo, Áo thun', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
