INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_c2cd68cbe50348c3', 'cat_polo', 'Áo Polo Vải Coffee Thoáng Mát Khử Mùi Non Iron 006 Màu Đỏ Đậm Dáng Vừa Vặn F3', 'ao-polo-vai-coffee-thoang-mat-khu-mui-non-iron-006-mau-do-dam-dang-vua-van-f3', '0024237', 'ID sản phẩm: Non Iron 006 Áo Polo tay ngắn Coffee mát mẻ, chống tia UV, khử mùi hôi, đa dạng màu sắc. 1. Kiểu sản phẩm: Áo Polo tay ngắn 2. Ưu điểm: Với công nghệ ép liền mạch hiện đại, chiếc áo thun này mang đến trải nghiệm hoàn toàn mới. Đường may ép sản phẩm, không gây khó chịu, giúp bạn thoải má', 'ID sản phẩm: Non Iron 006 Áo Polo tay ngắn Coffee mát mẻ, chống tia UV, khử mùi hôi, đa dạng màu sắc. 1. Kiểu sản phẩm: Áo Polo tay ngắn 2. Ưu điểm: Với công nghệ ép liền mạch hiện đại, chiếc áo thun này mang đến trải nghiệm hoàn toàn mới. Đường may ép sản phẩm, không gây khó chịu, giúp bạn thoải mái vận động cả ngày. Thiết kế tối giản, tinh tế, tôn giáo lên vẻ đẹp nam tính và hiện đại. Chất liệu cao cấp, co giãn tốt, rút hút mồ hôi nhanh chóng, mang đến cảm giác dễ chịu, tự tin. Hãy để chiếc áo thun liền mạch trở thành người đồng hành cùng thiết bị của bạn. 3. Chất liệu: Polyester Pique Coffee 100% 4. Kỹ thuật: • Cổ áo polyester không chỉ tạo điểm nhấn thời trang mà còn tăng cường độ bền cho sản phẩm, giúp áo luôn giữ được phong cách hoàn hảo sau nhiều lần giặt sạch. • Nhãn ép phản quang hiện đại không chỉ là một chi tiết trang trí độc đáo mà còn giúp bạn an toàn hơn khi di chuyển trong điều kiện thiếu sáng. • Nút xoa bóp đồng tinh không chỉ tăng tính thẩm mỹ cho áo mà còn giúp bạn dễ dàng điều chỉnh toàn bộ độ an toàn của cổ áo. • Thiết kế lai xẻ V thông minh giúp bạn thoải mái vận động mà không bị bó phần hông khi vận động. Công nghệ ép liền mạch, chiếc áo ôm cơ thể, không còn cảm giác cột hay khó chịu ở vị trí lai, tay, thắt lưng đến tự do vận động tối đa. 5. Phù hợp với: Người làm việc văn phòng tạo nên vẻ ngoài lịch sự, chuyên nghiệp. Người yêu thích phong cách thời trang đơn giản, thanh lịch. Những ai muốn tìm kiếm một chiếc áo vừa thoải mái vừa thời trang. 6. Phong cách: Tối giản, cơ bản, giản dị 7. Tìm kiếm sản phẩm: Áo polo nam, áo polo cổ bẻ, áo polo cá sấu cà phê, áo polo cao cấp, áo polo chống nắng.', 'YAME', 303450, 357000, true, 15.0, 830, 66, 4.8, 53, 'active', false, true, false, 'Áo Polo Vải Coffee Thoáng Mát Khử Mùi Non Iron 006 Màu Đỏ Đậm Dáng Vừa Vặn F3', 'ID sản phẩm: Non Iron 006 Áo Polo tay ngắn Coffee mát mẻ, chống tia UV, khử mùi hôi, đa dạng màu sắc. 1. Kiểu sản phẩm: Áo Polo tay ngắn 2. Ưu điểm: Với công nghệ ép liền mạch hiện đại, chiếc áo thun này mang đến trải nghiệm hoàn toàn mới. Đường may ép sản phẩm, không gây khó chịu, giúp bạn thoải má', '010426-sale, 010426-sale-quanao15, 130426-sale-5, F3 - Regular Fit (Dáng Tiêu Chuẩn), Gu đơn giản, màu đỏ, Quần áo, Thời Trang Công Nghệ, Áo, Áo thun', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
