INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_f8ee382745074710', 'cat_polo', 'Áo Polo Cotton Điều Hòa Nhiệt Thêu "amiable" The No Style 176 Màu Cam Dáng Rộng Rãi F4', 'ao-polo-cotton-dieu-hoa-nhiet-theu-amiable-the-no-style-176-mau-cam-dang-rong-rai-f4', '0023453', 'ID sản phẩm: The No Style 176 Áo Polo Basic thoáng mát, kiểm soát mùi, điều hòa nhiệt tốt, đa dạng màu sắc. 1. Kiểu sản phẩm: Áo Polo tay ngắn dáng rộng 2. Ưu điểm: Nhiều màu sắc để bạn chọn lựa, có logo nhỏ trên ngực giúp áo bớt đơn điệu. Thoát ẩm tốt, bề mặt mềm mại, kiểm soát mùi, điều hòa nhiệt.', 'ID sản phẩm: The No Style 176 Áo Polo Basic thoáng mát, kiểm soát mùi, điều hòa nhiệt tốt, đa dạng màu sắc. 1. Kiểu sản phẩm: Áo Polo tay ngắn dáng rộng 2. Ưu điểm: Nhiều màu sắc để bạn chọn lựa, có logo nhỏ trên ngực giúp áo bớt đơn điệu. Thoát ẩm tốt, bề mặt mềm mại, kiểm soát mùi, điều hòa nhiệt. 3. Chất liệu: Cotton Compact 2S, thành phần 100% Cotton 4. Kỹ thuật: Thêu đắp giống, tạo ra họa tiết sống động, giúp sản phẩm trở nên bắt mắt và độc đáo. 5. Phù hợp với ai: Mọi người cả nam và nữ, có thể dễ dàng phối hợp với nhiều phong cách thời trang khác nhau, từ năng động đến lịch lãm 6. Thuộc Bộ Sưu Tập nào: No Style, phong cách đa dạng, thời trang đỉnh cao, cá tính và hợp xu hướng 7. Các tên thường gọi hoặc tìm kiếm về sản phẩm này: Áo polo xám, áo polo tay ngắn, áo polo dáng rộng, áo polo cotton.', 'YAME', 215250, 287000, true, 25.0, 2177, 318, 4.5, 104, 'active', false, true, false, 'Áo Polo Cotton Điều Hòa Nhiệt Thêu "amiable" The No Style 176 Màu Cam Dáng Rộng Rãi F4', 'ID sản phẩm: The No Style 176 Áo Polo Basic thoáng mát, kiểm soát mùi, điều hòa nhiệt tốt, đa dạng màu sắc. 1. Kiểu sản phẩm: Áo Polo tay ngắn dáng rộng 2. Ưu điểm: Nhiều màu sắc để bạn chọn lựa, có logo nhỏ trên ngực giúp áo bớt đơn điệu. Thoát ẩm tốt, bề mặt mềm mại, kiểm soát mùi, điều hòa nhiệt.', '010426-sale, 010426-sale-quanao25, F4 - Loose Fit (Dáng Rộng), Gu thiết kế, màu cam, Quần áo, Thời Trang Không Đơn Giản, Áo, Áo thun', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_ae58b2e4379e457b', 'cat_polo', 'Áo Polo Cổ Khóa Kéo Vải Thoáng Khí Seventy Seven 018 Màu Be Đen Dáng Rộng Rãi F4', 'ao-polo-co-khoa-keo-vai-thoang-khi-seventy-seven-018-mau-be-den-dang-rong-rai-f4', '0023242', 'ID sản phẩm: Seventy Seven 018 Áo polo raplan rộng co giãn , hạn chế xù lông, trẻ trung năng động. 1. Kiểu sản phẩm: Áo Thun Polo cổ bẻ, tay ngắn và dáng rộng. 2. Ưu điểm: ●Thoáng khí : Chất liệu vải Pique thoáng nhẹ, dễ chịu giữ bạn khô ráo và thoải mái trong suốt ngày. ● Co giãn 4 chiều: Áo có khả', 'ID sản phẩm: Seventy Seven 018 Áo polo raplan rộng co giãn , hạn chế xù lông, trẻ trung năng động. 1. Kiểu sản phẩm: Áo Thun Polo cổ bẻ, tay ngắn và dáng rộng. 2. Ưu điểm: ●Thoáng khí : Chất liệu vải Pique thoáng nhẹ, dễ chịu giữ bạn khô ráo và thoải mái trong suốt ngày. ● Co giãn 4 chiều: Áo có khả năng co giãn theo 4 hướng, giúp bạn dễ dàng vận động mà không bị hạn chế. ● Hạn chế xù lông: Vải không bị xù lông sau thời gian sử dụng, giữ cho áo luôn mới mẻ. ● Thoáng khí: Thiết kế thoáng khí giúp bạn cảm thấy dễ chịu, đặc biệt trong những ngày nắng nóng. 3. Chất liệu: Sản phẩm được làm từ vải Pique (cá sấu 4 chiều), có thành phần 95% Polyester và 5% Spandex. 4. Kỹ thuật: Áo có họa tiết in dẻo trên bề mặt, tạo điểm nhấn thú vị. 5. Phù hợp với ai: Áo Polo phù hợp với mọi người, đặc biệt là trong các hoạt động thể thao, dạo phố, hay khi bạn muốn trang nhã và thoải mái. 6. Thuộc Bộ Sưu Tập: Bộ sưu tập Seventy Seven - thời trang trung tính, dễ phối dễ lựa chọn 7. Các tên thường gọi hoặc tìm kiếm về sản phẩm này: Áo thun Polo cổ bẻ, áo thun Polo cá sấu, áo thun Polo dáng rộng, Áo thun Polo Seventy Seven, Áo thun Polo màu, Áo pique.', 'YAME', 170250, 227000, true, 25.0, 1648, 477, 4.7, 30, 'active', false, true, false, 'Áo Polo Cổ Khóa Kéo Vải Thoáng Khí Seventy Seven 018 Màu Be Đen Dáng Rộng Rãi F4', 'ID sản phẩm: Seventy Seven 018 Áo polo raplan rộng co giãn , hạn chế xù lông, trẻ trung năng động. 1. Kiểu sản phẩm: Áo Thun Polo cổ bẻ, tay ngắn và dáng rộng. 2. Ưu điểm: ●Thoáng khí : Chất liệu vải Pique thoáng nhẹ, dễ chịu giữ bạn khô ráo và thoải mái trong suốt ngày. ● Co giãn 4 chiều: Áo có khả', '010426-sale, 010426-sale-quanao25, F4 - Loose Fit (Dáng Rộng), Gu đơn giản, màu be, Quần áo, Thời Trang Đơn Giản, Áo, Áo thun', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
