INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_4e173c5af0f64bf7', 'cat_polo', 'Áo Polo ColorLock™ Giữ Màu Tốt, Mặc Thoáng Vai Raglan Dễ Cử Động The No Style 225 Màu Xám Đen Dáng Vừa Vặn F3', 'ao-polo-colorlock-giu-mau-tot-mac-thoang-vai-raglan-de-cu-dong-the-no-style-225-mau-xam-den-dang-vua-van-f3', '0024753', 'Áo Thun Cổ Polo Tay Ngắn ColorLock™ The No Style 225 1. ColorLock™ Khắc Phục Triệt Để Tình Trạng Lem Màu Chống nhiễm màu (Anti-bleeding): Sử dụng công nghệ nhuộm thấm sâu vào lõi sợi, "khóa" chặt hạt màu. Điều này ngăn chặn tuyệt đối rủi ro màu tối (tay áo) lem sang màu sáng (thân áo) khi giặt máy. ', 'Áo Thun Cổ Polo Tay Ngắn ColorLock™ The No Style 225 1. ColorLock™ Khắc Phục Triệt Để Tình Trạng Lem Màu Chống nhiễm màu (Anti-bleeding): Sử dụng công nghệ nhuộm thấm sâu vào lõi sợi, "khóa" chặt hạt màu. Điều này ngăn chặn tuyệt đối rủi ro màu tối (tay áo) lem sang màu sáng (thân áo) khi giặt máy. Bền màu (Color Fastness): Giữ màu đen có độ sâu (deep black), không bị bạc phếch hay xuống sắc theo thời gian sử dụng. 2. Chất Liệu Pique 250gsm Đứng Phom &amp; Thoáng Khí Định lượng 250gsm (Mid-Heavy): Vải dày dặn giúp áo lên phom đứng, đanh chắc và che khuyết điểm cơ thể tốt hơn so với các loại vải thun mỏng. Cấu trúc "Lỗ thở" (AirDry™): Kiểu dệt mắt cá sấu (Pique) tạo ra các lỗ thông hơi tự nhiên, giúp không khí lưu thông, giảm bí bách dù vải dày. Kháng xù lông: Kết cấu sợi dai hạn chế hiện tượng vón cục (pilling) ở vùng nách và sườn áo. 3. Thiết Kế Tay Raglan Tối Ưu Vận Động Không giới hạn vai: Loại bỏ đường may vai truyền thống, giúp áo tự động điều chỉnh ôm theo độ xuôi vai của từng người (không lo kích vai hoặc dư vai). Co giãn 4 chiều (FlexFit™): Tỷ lệ 5% Spandex kết hợp cùng đường may móc xích tại nách giúp áo chịu lực tốt, hỗ trợ tối đa cho các động tác vung tay mạnh (Golf, Tennis). 4. Độ Hoàn Thiện Chi Tiết Trụ dây kéo ẩn (Hidden Zipper): Thiết kế dây kéo giấu kín tinh tế, được may viền và diễu thành phẩm 6mm tạo vẻ ngoài phẳng phiu, hiện đại. Đường may tiêu chuẩn: Mật độ 4.5 mũi/cm đảm bảo kết cấu chắc chắn cho vải dày, sử dụng chỉ Cotton 40/2 êm ái, không gây ngứa da. TỔNG KẾT The No Style 225 là mẫu Polo kỹ thuật đề cao tính ứng dụng và độ bền. Với nền tảng vải 250gsm giữ phom và công nghệ ColorLock™ chống lem màu, sản phẩm giải quyết triệt để nỗi lo "áo xuống cấp" sau khi giặt. Thiết kế tay Raglan mang lại sự thoải mái tuyệt đối, biến chiếc áo thành lựa chọn đa năng: lịch sự nơi công sở và linh hoạt trên sân tập. THÔNG TIN NHANH Chất liệu: ColorLock™ Polyester Plus Pique 250gsm, 95% Polyester 5% Spandex Chi tiết sản phẩm: Regular Fit, Tay Raglan, Trụ dây ké', 'YAME', 234650, 247000, true, 5.0, 707, 101, 4.3, 154, 'active', false, true, false, 'Áo Polo ColorLock™ Giữ Màu Tốt, Mặc Thoáng Vai Raglan Dễ Cử Động The No Style 225 Màu Xám Đen Dáng Vừa Vặn F3', 'Áo Thun Cổ Polo Tay Ngắn ColorLock™ The No Style 225 1. ColorLock™ Khắc Phục Triệt Để Tình Trạng Lem Màu Chống nhiễm màu (Anti-bleeding): Sử dụng công nghệ nhuộm thấm sâu vào lõi sợi, "khóa" chặt hạt màu. Điều này ngăn chặn tuyệt đối rủi ro màu tối (tay áo) lem sang màu sáng (thân áo) khi giặt máy. ', '130426-sale-5, F3 - Regular Fit (Dáng Tiêu Chuẩn), Gu thiết kế, màu xám, Quần áo, signature0226, signature0426, Thời Trang Không Đơn Giản, Áo, Áo thun', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_73a76c88113043d4', 'cat_polo', 'Áo Polo ColorLock™ Giữ Màu Tốt, Mặc Thoáng Vai Raglan Dễ Cử Động The No Style 225 Màu Đen Xám Dáng Vừa Vặn F3', 'ao-polo-colorlock-giu-mau-tot-mac-thoang-vai-raglan-de-cu-dong-the-no-style-225-mau-den-xam-dang-vua-van-f3', '0024752', 'Áo Thun Cổ Polo Tay Ngắn ColorLock™ The No Style 225 1. ColorLock™ Khắc Phục Triệt Để Tình Trạng Lem Màu Chống nhiễm màu (Anti-bleeding): Sử dụng công nghệ nhuộm thấm sâu vào lõi sợi, "khóa" chặt hạt màu. Điều này ngăn chặn tuyệt đối rủi ro màu tối (tay áo) lem sang màu sáng (thân áo) khi giặt máy. ', 'Áo Thun Cổ Polo Tay Ngắn ColorLock™ The No Style 225 1. ColorLock™ Khắc Phục Triệt Để Tình Trạng Lem Màu Chống nhiễm màu (Anti-bleeding): Sử dụng công nghệ nhuộm thấm sâu vào lõi sợi, "khóa" chặt hạt màu. Điều này ngăn chặn tuyệt đối rủi ro màu tối (tay áo) lem sang màu sáng (thân áo) khi giặt máy. Bền màu (Color Fastness): Giữ màu đen có độ sâu (deep black), không bị bạc phếch hay xuống sắc theo thời gian sử dụng. 2. Chất Liệu Pique 250gsm Đứng Phom &amp; Thoáng Khí Định lượng 250gsm (Mid-Heavy): Vải dày dặn giúp áo lên phom đứng, đanh chắc và che khuyết điểm cơ thể tốt hơn so với các loại vải thun mỏng. Cấu trúc "Lỗ thở" (AirDry™): Kiểu dệt mắt cá sấu (Pique) tạo ra các lỗ thông hơi tự nhiên, giúp không khí lưu thông, giảm bí bách dù vải dày. Kháng xù lông: Kết cấu sợi dai hạn chế hiện tượng vón cục (pilling) ở vùng nách và sườn áo. 3. Thiết Kế Tay Raglan Tối Ưu Vận Động Không giới hạn vai: Loại bỏ đường may vai truyền thống, giúp áo tự động điều chỉnh ôm theo độ xuôi vai của từng người (không lo kích vai hoặc dư vai). Co giãn 4 chiều (FlexFit™): Tỷ lệ 5% Spandex kết hợp cùng đường may móc xích tại nách giúp áo chịu lực tốt, hỗ trợ tối đa cho các động tác vung tay mạnh (Golf, Tennis). 4. Độ Hoàn Thiện Chi Tiết Trụ dây kéo ẩn (Hidden Zipper): Thiết kế dây kéo giấu kín tinh tế, được may viền và diễu thành phẩm 6mm tạo vẻ ngoài phẳng phiu, hiện đại. Đường may tiêu chuẩn: Mật độ 4.5 mũi/cm đảm bảo kết cấu chắc chắn cho vải dày, sử dụng chỉ Cotton 40/2 êm ái, không gây ngứa da. TỔNG KẾT The No Style 225 là mẫu Polo kỹ thuật đề cao tính ứng dụng và độ bền. Với nền tảng vải 250gsm giữ phom và công nghệ ColorLock™ chống lem màu, sản phẩm giải quyết triệt để nỗi lo "áo xuống cấp" sau khi giặt. Thiết kế tay Raglan mang lại sự thoải mái tuyệt đối, biến chiếc áo thành lựa chọn đa năng: lịch sự nơi công sở và linh hoạt trên sân tập. THÔNG TIN NHANH Chất liệu: ColorLock™ Polyester Plus Pique 250gsm, 95% Polyester 5% Spandex Chi tiết sản phẩm: Regular Fit, Tay Raglan, Trụ dây ké', 'YAME', 234650, 247000, true, 5.0, 4797, 63, 4.5, 189, 'active', false, true, false, 'Áo Polo ColorLock™ Giữ Màu Tốt, Mặc Thoáng Vai Raglan Dễ Cử Động The No Style 225 Màu Đen Xám Dáng Vừa Vặn F3', 'Áo Thun Cổ Polo Tay Ngắn ColorLock™ The No Style 225 1. ColorLock™ Khắc Phục Triệt Để Tình Trạng Lem Màu Chống nhiễm màu (Anti-bleeding): Sử dụng công nghệ nhuộm thấm sâu vào lõi sợi, "khóa" chặt hạt màu. Điều này ngăn chặn tuyệt đối rủi ro màu tối (tay áo) lem sang màu sáng (thân áo) khi giặt máy. ', '130426-sale-5, F3 - Regular Fit (Dáng Tiêu Chuẩn), Gu thiết kế, màu đen, Quần áo, signature0226, signature0426, Thời Trang Không Đơn Giản, Áo, Áo thun', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
