INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_a53b9797f3fe4f2b', 'cat_polo', 'Áo Polo Tay Ngắn Họa Tiết Sọc The No Style 025 Màu Trắng Đen Dáng Rộng Rãi F4', 'ao-polo-tay-ngan-hoa-tiet-soc-the-no-style-025-mau-trang-den-dang-rong-rai-f4', '0023427', 'ID sản phẩm: The No Style 025 Áo Polo sọc ngang trẻ trung mềm mại, kiểm soát mùi, sọc màu. 1. Kiểu sản phẩm: Áo thun polo tay ngắn. 2. Ưu điểm: Thoát ẩm tốt, bề mặt vải mềm mại, kiểm soát mùi hiệu quả, điều hòa nhiệt độ và thân thiện với môi trường. 3. Chất liệu: Vải Cotton Compact 2S (100% Cotton).', 'ID sản phẩm: The No Style 025 Áo Polo sọc ngang trẻ trung mềm mại, kiểm soát mùi, sọc màu. 1. Kiểu sản phẩm: Áo thun polo tay ngắn. 2. Ưu điểm: Thoát ẩm tốt, bề mặt vải mềm mại, kiểm soát mùi hiệu quả, điều hòa nhiệt độ và thân thiện với môi trường. 3. Chất liệu: Vải Cotton Compact 2S (100% Cotton). 4. Kỹ thuật: Áo được trang trí bằng kỹ thuật thêu, màu thêu cùng màu sọc mang lại sự đồng điệu cho sản phẩm. Họa tiết in sọc ngang lặp lại tạo nên một phong cách trẻ trung và năng động, đồng thời giúp áo trở nên nổi bật và dễ phối đồ. Họa tiết sọc ngang cũng giúp tạo cảm giác thân hình cân đối hơn khi mặc. 5. Phù hợp với ai: Phù hợp với người yêu thích phong cách trẻ trung và năng động, người ưa chuộng sự thoải mái và tiện dụng, người quan tâm đến môi trường, người có phong cách đa dạng 6. Thuộc Bộ Sưu Tập: Bộ sưu tập No Style - mang đến sự đa dạng về phong cách 7. Các tên thường gọi hoặc tìm kiếm về sản phẩm này: Áo polo nam dáng rộng có dây kéo, áo thun cotton thoáng khí cao cấp, áo thun polo, áo thun polo nam, áo thun polo sọc.', 'YAME', 267750, 357000, true, 25.0, 2105, 308, 4.2, 43, 'active', false, true, false, 'Áo Polo Tay Ngắn Họa Tiết Sọc The No Style 025 Màu Trắng Đen Dáng Rộng Rãi F4', 'ID sản phẩm: The No Style 025 Áo Polo sọc ngang trẻ trung mềm mại, kiểm soát mùi, sọc màu. 1. Kiểu sản phẩm: Áo thun polo tay ngắn. 2. Ưu điểm: Thoát ẩm tốt, bề mặt vải mềm mại, kiểm soát mùi hiệu quả, điều hòa nhiệt độ và thân thiện với môi trường. 3. Chất liệu: Vải Cotton Compact 2S (100% Cotton).', '010426-sale, 010426-sale-quanao25, F4 - Loose Fit (Dáng Rộng), Gu thiết kế, màu xám, Quần áo, Thời Trang Không Đơn Giản, Áo, Áo thun', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
