INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_13477900ef554d70', 'cat_polo', 'Áo Polo Tay Ngắn Vải Coffee Khử Mùi The Minimalist 007 Màu Cam Đậm Dáng Vừa Vặn F3', 'ao-polo-tay-ngan-vai-coffee-khu-mui-the-minimalist-007-mau-cam-dam-dang-vua-van-f3', '0024455', 'ID sản phẩm: The Minimalist 007 Áo Polo Basic Polyester Pique Coffee mát mẻ, chống tia UV, khử mùi hôi, màu sắc đa dạng . 1. Kiểu sản phẩm: Áo Polo tay ngắn 2. Ưu điểm: Với công nghệ ép seamless hiện đại, chiếc áo thun này mang đến trải nghiệm hoàn toàn mới. Đường may ép phẳng mềm mại, không gây cộm', 'ID sản phẩm: The Minimalist 007 Áo Polo Basic Polyester Pique Coffee mát mẻ, chống tia UV, khử mùi hôi, màu sắc đa dạng . 1. Kiểu sản phẩm: Áo Polo tay ngắn 2. Ưu điểm: Với công nghệ ép seamless hiện đại, chiếc áo thun này mang đến trải nghiệm hoàn toàn mới. Đường may ép phẳng mềm mại, không gây cộm, giúp bạn thoải mái vận động cả ngày dài. Thiết kế tối giản, tinh tế, tôn lên vẻ đẹp nam tính và hiện đại. Chất liệu cao cấp, co giãn tốt, thoát ẩm nhanh chóng, mang đến cảm giác dễ chịu, tự tin. Hãy để chiếc áo thun seamless trở thành người bạn đồng hành thân thiết của bạn. 3. Chất liệu: Polyester Pique Coffee 100% 4. Kỹ thuật: • Cổ áo polyester không chỉ tạo điểm nhấn thời trang mà còn tăng cường độ bền cho sản phẩm, giúp áo luôn giữ được form dáng hoàn hảo sau nhiều lần giặt. • Nhãn ép phản quang hiện đại không chỉ là một chi tiết trang trí độc đáo mà còn giúp bạn an toàn hơn khi di chuyển trong điều kiện thiếu sáng. • Nút bóp đồng điệu tinh tế không chỉ tăng tính thẩm mỹ cho áo mà còn giúp bạn dễ dàng điều chỉnh độ ôm sát của cổ áo. • Thiết kế lai xẻ V thông minh giúp bạn thoải mái vận động mà không bị gò bó phần hông khi vận động. Công nghệ ép seamless, chiếc áo ôm trọn cơ thể, không còn cảm giác cộm hay khó chịu ở các vị trí lai, tay, lưng mang đến sự tự do vận động tối đa. 5. Phù hợp với: Người làm việc văn phòng tạo nên vẻ ngoài lịch sự, chuyên nghiệp.', 'YAME', 277950, 327000, true, 15.0, 4375, 372, 4.5, 61, 'active', false, true, false, 'Áo Polo Tay Ngắn Vải Coffee Khử Mùi The Minimalist 007 Màu Cam Đậm Dáng Vừa Vặn F3', 'ID sản phẩm: The Minimalist 007 Áo Polo Basic Polyester Pique Coffee mát mẻ, chống tia UV, khử mùi hôi, màu sắc đa dạng . 1. Kiểu sản phẩm: Áo Polo tay ngắn 2. Ưu điểm: Với công nghệ ép seamless hiện đại, chiếc áo thun này mang đến trải nghiệm hoàn toàn mới. Đường may ép phẳng mềm mại, không gây cộm', '010426-sale, 010426-sale-quanao15, 130426-sale-5, F3 - Regular Fit (Dáng Tiêu Chuẩn), Gu đơn giản, màu cam, Quần áo, Thời Trang Công Nghệ, Vị Nhân Sinh, Áo', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
