INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_b5212633616e402d', 'cat_polo', 'Áo Polo ColorLock™ Vải Cá Sấu Đứng Dáng Khóa Màu Sâu Seventy Seven 019 Màu Đen Xám Dáng Ôm Vừa F2', 'ao-polo-colorlock-vai-ca-sau-dung-dang-khoa-mau-sau-seventy-seven-019-mau-den-xam-dang-om-vua-f2', '0023246', 'Áo Thun Cổ Polo Tay Ngắn ColorLock™ Seventy Seven 019 1. Phom Dáng Standard (Dáng Vừa): Gọn Gàng &amp; Linh Hoạt Thiết kế tối ưu: Khắc phục nhược điểm thùng thình của phom Regular cũ và sự gò bó của Slimfit. Kỹ thuật High Armhole: Nâng cao nách áo giúp loại bỏ vải thừa đùn ở nách, đồng thời giữ thân', 'Áo Thun Cổ Polo Tay Ngắn ColorLock™ Seventy Seven 019 1. Phom Dáng Standard (Dáng Vừa): Gọn Gàng &amp; Linh Hoạt Thiết kế tối ưu: Khắc phục nhược điểm thùng thình của phom Regular cũ và sự gò bó của Slimfit. Kỹ thuật High Armhole: Nâng cao nách áo giúp loại bỏ vải thừa đùn ở nách, đồng thời giữ thân áo không bị xô lệch khi giơ tay. Tỷ lệ hiện đại: Thu gọn sườn áo và cắt ngắn tay áo 4cm giúp người mặc trông cao ráo, trẻ trung và khỏe khoắn hơn. 2. Chất Liệu Pique ColorLock™: Bền Bỉ &amp; Thoáng Khí Định lượng 220gsm: Vải có độ dày dặn lý tưởng để giữ phom áo đứng, che khuyết điểm cơ thể tốt. Cấu trúc "Biết thở": Kiểu dệt mắt lưới (Pique) tạo các khe hở vi mô giúp thoát hơi nóng và mồ hôi nhanh chóng, không gây bí bách. Công nghệ Khóa màu: Chống bạc màu và loang lổ tuyệt đối, giữ áo luôn mới sau thời gian dài sử dụng. 3. Kết Cấu "Khung Xương" Chắc Chắn Đường may Móc xích: Áp dụng tại các điểm nối phối màu, tạo độ đàn hồi "giảm xóc", giúp áo co giãn theo chuyển động mà không lo đứt chỉ. Trụ cổ ép keo định hình: Gia cố lớp dựng chuyên dụng giúp cổ áo luôn phẳng lì, đứng dáng, không bị rộp hay gãy nếp sau khi giặt. TỔNG KẾT Seventy Seven 019 là giải pháp "2 trong 1" hoàn hảo cho nam giới hiện đại: Đủ lịch sự cho môi trường công sở, đủ thoải mái cho các hoạt động di chuyển. Sản phẩm giữ phom ổn định, bền màu và phẳng phiu suốt cả ngày dài mà không tốn nhiều công sức bảo quản. THÔNG TIN NHANH Chất liệu: Vải Pique (Cá sấu) công nghệ ColorLock™, định lượng 220gsm. Chi tiết: Phom Standard Fit, nách cao, cổ bẻ ép keo dựng, đường may móc xích. Lưu ý giặt ủi Giặt máy thoải mái, không cần chế độ giặt nhẹ Vải tự phẳng sau khi phơi Hạn chế sấy ở nhiệt độ quá cao', 'YAME', 192950, 227000, true, 15.0, 1451, 89, 4.2, 8, 'active', false, true, false, 'Áo Polo ColorLock™ Vải Cá Sấu Đứng Dáng Khóa Màu Sâu Seventy Seven 019 Màu Đen Xám Dáng Ôm Vừa F2', 'Áo Thun Cổ Polo Tay Ngắn ColorLock™ Seventy Seven 019 1. Phom Dáng Standard (Dáng Vừa): Gọn Gàng &amp; Linh Hoạt Thiết kế tối ưu: Khắc phục nhược điểm thùng thình của phom Regular cũ và sự gò bó của Slimfit. Kỹ thuật High Armhole: Nâng cao nách áo giúp loại bỏ vải thừa đùn ở nách, đồng thời giữ thân', '010426-sale, 010426-sale-quanao15, Cá Nhân Hóa, F2 - Slim Fit (Dáng Ôm Vừa), Gu đơn giản, màu đen, Quần áo, signature, signature0226, Thời Trang Đơn Giản', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
