INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_444c1265787c48e8', 'cat_polo', 'Áo Polo Vải Làm Mát IceVibes™ The CEO 001 Màu Nâu Nhạt Dáng Vừa Vặn F3', 'ao-polo-vai-lam-mat-icevibes-the-ceo-001-mau-nau-nhat-dang-vua-van-f3', '0024445', 'Áo Thun Cổ Polo Tay Ngắn The CEO 001 1. Công Nghệ Tản Nhiệt IceVibes™ &amp; Sợi High-TPI Sản phẩm giải quyết bài toán "vải dày gây nóng" bằng kỹ thuật vật lý. Dù sở hữu định lượng 210gsm (dày dặn, đứng form), vải được xử lý bằng công nghệ dệt High-TPI (tăng độ xoắn sợi lên 25%). Hiệu quả: Sợi đanh, ', 'Áo Thun Cổ Polo Tay Ngắn The CEO 001 1. Công Nghệ Tản Nhiệt IceVibes™ &amp; Sợi High-TPI Sản phẩm giải quyết bài toán "vải dày gây nóng" bằng kỹ thuật vật lý. Dù sở hữu định lượng 210gsm (dày dặn, đứng form), vải được xử lý bằng công nghệ dệt High-TPI (tăng độ xoắn sợi lên 25%). Hiệu quả: Sợi đanh, triệt tiêu lông vải, kết hợp lớp phủ hồ lạnh giúp bề mặt phẳng mịn tối đa. Cơ chế: Tăng diện tích tiếp xúc với da để dẫn truyền nhiệt ra ngoài tức thì (Cool Touch). 2. Bề Mặt "Silk-Like" &amp; Giảm Ma Sát Loại bỏ cảm giác thô ráp nhờ cấu trúc dệt Single Jersey hoàn thiện bề mặt mượt như lụa (Silk-Like). Vận động: Tỷ lệ 8% Spandex cung cấp độ co giãn 4 chiều (FlexFit™) và độ nảy (bounce). Lợi ích: Giảm ma sát lên da, tạo khoảng hở vi mô khi vận động để không khí lưu thông, chống bết dính. 3. Kỹ Thuật Rập &amp; Độ Bền Kết Cấu Sự thoải mái và độ bền được tính toán qua thông số rập và kỹ thuật may công nghiệp: Rập "Thở": Nâng đáy nách (-0.4cm) giúp tay chuyển động độc lập với thân áo. Thu gọn lai áo (-3cm) để triệt tiêu vải thừa nhưng vẫn giữ độ rộng ngực tiêu chuẩn cho khí nóng thoát ra. Gia cố: Thiết kế Nẹp giấu nút Hidden Placket tối giản, kết hợp đóng Bọ khóa tại chân trụ để chịu lực căng cường độ cao. TỔNG KẾT The CEO 001 là giải pháp kỹ thuật cân bằng giữa hai thái cực: Chỉn chu về thị giác (nhờ vải dày 210gsm, nẹp giấu nút) và Thoải mái về vật lý (nhờ công nghệ High-TPI tản nhiệt). Đây là lựa chọn tối ưu cho người dùng cần sự bền bỉ của kết cấu may công nghiệp và hiệu suất thoáng mát của trang phục thể thao. THÔNG TIN NHANH Chất liệu: IceVibes™ Cotton Plus Single 210gsm, 92% Cotton 8% Spandex Chi tiết kỹ thuật: Dáng vừa, Nẹp giấu nút (Hidden Placket) Lưu ý giặt ủi: Giặt máy chế độ nhẹ (Gentle), nước lạnh (&lt;40°C), luôn lộn trái. Tuyệt đối KHÔNG sấy nóng. Ủi nhiệt độ thấp (110°C - 120°C), không kéo giãn vải khi ủi.', 'YAME', 243950, 287000, true, 15.0, 2727, 263, 4.4, 164, 'active', true, true, true, 'Áo Polo Vải Làm Mát IceVibes™ The CEO 001 Màu Nâu Nhạt Dáng Vừa Vặn F3', 'Áo Thun Cổ Polo Tay Ngắn The CEO 001 1. Công Nghệ Tản Nhiệt IceVibes™ &amp; Sợi High-TPI Sản phẩm giải quyết bài toán "vải dày gây nóng" bằng kỹ thuật vật lý. Dù sở hữu định lượng 210gsm (dày dặn, đứng form), vải được xử lý bằng công nghệ dệt High-TPI (tăng độ xoắn sợi lên 25%). Hiệu quả: Sợi đanh, ', '010426-sale, 010426-sale-quanao15, Công Nghệ, F3 - Regular Fit (Dáng Tiêu Chuẩn), Gu đơn giản, màu nâu, Quần áo, signature, signature0226, Thời Trang Công Nghệ', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
