INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_f6e3a8d99f364b1a', 'cat_polo', 'Áo Polo Vải Cá Sấu ColorLock™ Giặt Không Phai Màu, Đứng Dáng Non Branded 003 Màu Hồng Dáng Ôm Vừa F2', 'ao-polo-vai-ca-sau-colorlock-giat-khong-phai-mau-dung-dang-non-branded-003-mau-hong-dang-om-vua-f2', '0023746', 'Áo Thun Cổ Polo Tay Ngắn Non Branded 003 1. Tối Ưu Hóa Phom Dáng Modern Fit Thân áo Semi-fitted: Giảm 2cm vòng ngực và 3cm lai áo. Kết cấu này loại bỏ độ thùng thình hai bên sườn, tạo độ ôm vừa phải theo cơ thể. Nách áo High Armhole: Hạ nách giảm 2.4cm (nách cạn hơn). Kỹ thuật này giúp "treo" tay áo', 'Áo Thun Cổ Polo Tay Ngắn Non Branded 003 1. Tối Ưu Hóa Phom Dáng Modern Fit Thân áo Semi-fitted: Giảm 2cm vòng ngực và 3cm lai áo. Kết cấu này loại bỏ độ thùng thình hai bên sườn, tạo độ ôm vừa phải theo cơ thể. Nách áo High Armhole: Hạ nách giảm 2.4cm (nách cạn hơn). Kỹ thuật này giúp "treo" tay áo cao hơn, triệt tiêu hiện tượng thân áo bị giật ngược lên khi giơ tay cao. Ống tay gọn gàng: Giảm độ dài 4cm và cửa tay 1cm. Điều chỉnh này khắc phục nhược điểm tay áo dài lửng lơ và bị loe, giúp ống tay ôm gọn bắp tay. 2. Nâng Cấp Chi Tiết &amp; Độ Bền Cổ áo có chân (Collar Stand): Thiết kế chân cổ riêng biệt (tương tự sơ mi) giúp lá cổ nằm êm, đứng dáng và lịch sự hơn cổ dệt liền. Trụ áo tinh tế: May 1 kim giấu kín đường vắt sổ. Các góc trụ được cắt gọt tỉ mỉ trước khi may lộn để đảm bảo không bị cộm hay thừa vải. Gia cố vai: Chạy dây chống giãn kết hợp vắt sổ giúp vai áo không bị chảy xệ. 3. Chất Liệu ColorLock™ &amp; Hiệu Suất Định hình form dáng: Sử dụng vải ColorLock™ Polyester Plus Pique 220gsm dày dặn, giúp áo đứng form nhưng vẫn thoáng mát nhờ cấu trúc dệt mắt lưới. Co giãn 4 chiều: Tích hợp 5% sợi Spandex (FlexFit™) đảm bảo sự vận động linh hoạt, thoải mái dù áo có độ ôm gọn gàng. Bền màu tối ưu: Công nghệ ColorLock™ khóa màu sâu vào lõi sợi, hạn chế phai màu khi giặt. TỔNG KẾT Sự thay đổi lớn đến từ những điều chỉnh nhỏ: giảm 2cm ngực, nâng 2.4cm nách và thu ngắn 4cm tay áo. Non Branded 003 là minh chứng cho việc sự tinh tế không nằm ở logo, mà nằm ở cách chiếc áo "ứng xử" với cơ thể người mặc thông qua bộ rập Modern Fit được tính toán kỹ lưỡng. THÔNG TIN NHANH Chất liệu: 95% Polyester, 5% Spandex (Định lượng 220gsm). Chi tiết sản phẩm: Dáng vừa, áo có chân cổ Lưu ý giặt /ủi: Giặt máy chế độ nhẹ (nước &lt; 40°C), không dùng thuốc tẩy Clo, ủi ở nhiệt độ thấp (110–120°C), nên lộn trái khi giặt và phơi.', 'YAME', 168150, 177000, true, 5.0, 2555, 354, 4.5, 76, 'active', false, true, false, 'Áo Polo Vải Cá Sấu ColorLock™ Giặt Không Phai Màu, Đứng Dáng Non Branded 003 Màu Hồng Dáng Ôm Vừa F2', 'Áo Thun Cổ Polo Tay Ngắn Non Branded 003 1. Tối Ưu Hóa Phom Dáng Modern Fit Thân áo Semi-fitted: Giảm 2cm vòng ngực và 3cm lai áo. Kết cấu này loại bỏ độ thùng thình hai bên sườn, tạo độ ôm vừa phải theo cơ thể. Nách áo High Armhole: Hạ nách giảm 2.4cm (nách cạn hơn). Kỹ thuật này giúp "treo" tay áo', 'F2 - Slim Fit (Dáng Ôm Vừa), GIÁ THẬT TỐT, màu hồng, Quần áo, signature, signature0226, signature0426, Áo, Áo thun', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
