INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_af3922318bee4ea6', 'cat_shirt_short', 'Áo Sơ Mi Tay Ngắn Vải Xước Như Linen AirDry™ Mịn Mặc Mát Giải Nhiệt Mùa Hè The No Style 216 Màu Đen Dáng Vừa Vặn F3', 'ao-so-mi-tay-ngan-vai-xuoc-nhu-linen-airdry-min-mac-mat-giai-nhiet-mua-he-the-no-style-216-mau-den-dang-vua-van-f3', '0024841', 'Áo Sơ Mi Tay Ngắn AirDry™ The No Style 216 1. Chất liệu "Linen Look" êm mượt Mát lạnh tức thì: Cốt liệu Rayon chủ đạo mang lại cảm giác trơn mướt, giải nhiệt ngay khi chạm da. Thoáng khí tự nhiên: Kỹ thuật dệt xước (Slub) tạo các khe hở siêu nhỏ giúp mồ hôi bay hơi nhanh, bề mặt vải nhìn mộc mạc như', 'Áo Sơ Mi Tay Ngắn AirDry™ The No Style 216 1. Chất liệu "Linen Look" êm mượt Mát lạnh tức thì: Cốt liệu Rayon chủ đạo mang lại cảm giác trơn mướt, giải nhiệt ngay khi chạm da. Thoáng khí tự nhiên: Kỹ thuật dệt xước (Slub) tạo các khe hở siêu nhỏ giúp mồ hôi bay hơi nhanh, bề mặt vải nhìn mộc mạc nhưng không hề thô ráp. Giữ dáng ổn định: Kết cấu pha nhẹ Polyester đóng vai trò "khung xương", giúp áo không bị rũ hay mất form sau ngày dài vận động. 2. Kỹ thuật may Cuốn Sườn (Flat Felled Seam) Loại bỏ hoàn toàn mép vải thừa (vắt sổ) gây ngứa ngáy. Mép vải được cuộn kín vào trong, giúp mặt trái áo phẳng lì, êm ái tuyệt đối. Đường may chắc chắn, chịu lực tốt gấp nhiều lần so với kỹ thuật may thường. 3. Hoàn thiện tinh tế &amp; Tiện dụng Cổ Cuban ép keo lụa: Đứng dáng, phóng khoáng nhưng vẫn mềm mại, không bị rộp hay cứng đơ. Cầu vai (Đô sau) 2 lớp: Giúp áo chịu lực tốt, tạo cảm giác vai rộng và nam tính hơn. Tiện ích: Túi ngực được ủi định hình vuông vức, không nhăn nhúm. Tích hợp dây treo (Hanger Loop) giúp treo áo giữ form dễ dàng. TỔNG KẾT The No Style 216 là chiếc sơ mi cân bằng giữa sự thoải mái của đồ đi biển và sự chỉn chu cần thiết. Mảnh ghép hoàn hảo cho những ai tìm kiếm sự phóng khoáng nhưng vẫn đề cao trải nghiệm xúc giác êm ái. THÔNG TIN NHANH Chất liệu: AirDry™ Rayon Blend Basic Slub 183gsm, 91% Rayon 9% Polyester. Chi tiết sản phẩm: Phom Regular Fit, Cổ Cuban, May cuốn sườn toàn bộ, Dây treo (Hanger Loop). Lưu ý giặt ủi: Vải kỵ nước nóng và lực vắt mạnh. Khuyên dùng túi giặt chế độ nhẹ hoặc giặt tay. Không vặn xoắn áo. Ủi hơi nước ở mặt trái.', 'YAME', 282150, 297000, true, 5.0, 3167, 136, 4.7, 35, 'active', false, true, false, 'Áo Sơ Mi Tay Ngắn Vải Xước Như Linen AirDry™ Mịn Mặc Mát Giải Nhiệt Mùa Hè The No Style 216 Màu Đen Dáng Vừa Vặn F3', 'Áo Sơ Mi Tay Ngắn AirDry™ The No Style 216 1. Chất liệu "Linen Look" êm mượt Mát lạnh tức thì: Cốt liệu Rayon chủ đạo mang lại cảm giác trơn mướt, giải nhiệt ngay khi chạm da. Thoáng khí tự nhiên: Kỹ thuật dệt xước (Slub) tạo các khe hở siêu nhỏ giúp mồ hôi bay hơi nhanh, bề mặt vải nhìn mộc mạc như', '110426-sale-5, màu đen, Quần áo, signature, signature0226, signature0426, xuhuong220426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_a00cc44a42e942cd', 'cat_shirt_short', 'Áo Sơ Mi Tay Ngắn Vải Xước Như Linen AirDry™ Mịn Mặc Mát Giải Nhiệt Mùa Hè The No Style 216 Màu Nâu Nhạt Dáng Vừa Vặn F3', 'ao-so-mi-tay-ngan-vai-xuoc-nhu-linen-airdry-min-mac-mat-giai-nhiet-mua-he-the-no-style-216-mau-nau-nhat-dang-vua-van-f3', '0024840', 'Áo Sơ Mi Tay Ngắn AirDry™ The No Style 216 1. Chất liệu "Linen Look" êm mượt Mát lạnh tức thì: Cốt liệu Rayon chủ đạo mang lại cảm giác trơn mướt, giải nhiệt ngay khi chạm da. Thoáng khí tự nhiên: Kỹ thuật dệt xước (Slub) tạo các khe hở siêu nhỏ giúp mồ hôi bay hơi nhanh, bề mặt vải nhìn mộc mạc như', 'Áo Sơ Mi Tay Ngắn AirDry™ The No Style 216 1. Chất liệu "Linen Look" êm mượt Mát lạnh tức thì: Cốt liệu Rayon chủ đạo mang lại cảm giác trơn mướt, giải nhiệt ngay khi chạm da. Thoáng khí tự nhiên: Kỹ thuật dệt xước (Slub) tạo các khe hở siêu nhỏ giúp mồ hôi bay hơi nhanh, bề mặt vải nhìn mộc mạc nhưng không hề thô ráp. Giữ dáng ổn định: Kết cấu pha nhẹ Polyester đóng vai trò "khung xương", giúp áo không bị rũ hay mất form sau ngày dài vận động. 2. Kỹ thuật may Cuốn Sườn (Flat Felled Seam) Loại bỏ hoàn toàn mép vải thừa (vắt sổ) gây ngứa ngáy. Mép vải được cuộn kín vào trong, giúp mặt trái áo phẳng lì, êm ái tuyệt đối. Đường may chắc chắn, chịu lực tốt gấp nhiều lần so với kỹ thuật may thường. 3. Hoàn thiện tinh tế &amp; Tiện dụng Cổ Cuban ép keo lụa: Đứng dáng, phóng khoáng nhưng vẫn mềm mại, không bị rộp hay cứng đơ. Cầu vai (Đô sau) 2 lớp: Giúp áo chịu lực tốt, tạo cảm giác vai rộng và nam tính hơn. Tiện ích: Túi ngực được ủi định hình vuông vức, không nhăn nhúm. Tích hợp dây treo (Hanger Loop) giúp treo áo giữ form dễ dàng. TỔNG KẾT The No Style 216 là chiếc sơ mi cân bằng giữa sự thoải mái của đồ đi biển và sự chỉn chu cần thiết. Mảnh ghép hoàn hảo cho những ai tìm kiếm sự phóng khoáng nhưng vẫn đề cao trải nghiệm xúc giác êm ái. THÔNG TIN NHANH Chất liệu: AirDry™ Rayon Blend Basic Slub 183gsm, 91% Rayon 9% Polyester. Chi tiết sản phẩm: Phom Regular Fit, Cổ Cuban, May cuốn sườn toàn bộ, Dây treo (Hanger Loop). Lưu ý giặt ủi: Vải kỵ nước nóng và lực vắt mạnh. Khuyên dùng túi giặt chế độ nhẹ hoặc giặt tay. Không vặn xoắn áo. Ủi hơi nước ở mặt trái.', 'YAME', 282150, 297000, true, 5.0, 3266, 227, 4.9, 70, 'active', false, true, false, 'Áo Sơ Mi Tay Ngắn Vải Xước Như Linen AirDry™ Mịn Mặc Mát Giải Nhiệt Mùa Hè The No Style 216 Màu Nâu Nhạt Dáng Vừa Vặn F3', 'Áo Sơ Mi Tay Ngắn AirDry™ The No Style 216 1. Chất liệu "Linen Look" êm mượt Mát lạnh tức thì: Cốt liệu Rayon chủ đạo mang lại cảm giác trơn mướt, giải nhiệt ngay khi chạm da. Thoáng khí tự nhiên: Kỹ thuật dệt xước (Slub) tạo các khe hở siêu nhỏ giúp mồ hôi bay hơi nhanh, bề mặt vải nhìn mộc mạc như', '110426-sale-5, màu nâu, Quần áo, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_9097d0aba37549ff', 'cat_shirt_short', 'Áo Sơ Mi Tay Ngắn Giấu Bụng DurableTex™ Vải Dày Dặn Đứng Form Multi Color Jean 003 Màu Nâu Đậm Dáng Rộng Rãi F4', 'ao-so-mi-tay-ngan-giau-bung-durabletex-vai-day-dan-dung-form-multi-color-jean-003-mau-nau-dam-dang-rong-rai-f4', '0024933', 'Áo Sơ Mi Tay Ngắn Multi Color Jean 003 1. Chất Liệu DurableTex™ Bền Bỉ &amp; Jean Look Vải DurableTex™ 11.5oz: Dệt kiểu Twill (Vân chéo) từ 100% Cotton tự nhiên. Cấu trúc này mang lại độ dày dặn, đứng phom (Shape Retention) nhưng vẫn đảm bảo độ thoáng khí, không gây hầm bí. Hiệu ứng Jean Look: Bề mặ', 'Áo Sơ Mi Tay Ngắn Multi Color Jean 003 1. Chất Liệu DurableTex™ Bền Bỉ &amp; Jean Look Vải DurableTex™ 11.5oz: Dệt kiểu Twill (Vân chéo) từ 100% Cotton tự nhiên. Cấu trúc này mang lại độ dày dặn, đứng phom (Shape Retention) nhưng vẫn đảm bảo độ thoáng khí, không gây hầm bí. Hiệu ứng Jean Look: Bề mặt vải bụi bặm, nam tính, hạn chế nhăn nhàu tốt hơn vải dệt trơn thông thường. 2. Phom dáng Loose Fit / Boxy Cấu trúc Loose Fit / Boxy: Thiết kế nới rộng Ngực và Lai áo (+4cm) giúp triệt tiêu độ ôm gò bó, che khuyết điểm vòng bụng và ngăn tình trạng hớt vạt khi cài nút. Vai trễ (Drop Shoulder): Hạ nách sâu (+1cm) và tăng thông số vai (+3cm) đưa điểm rơi ra ngoài khớp vai tự nhiên, giúp cánh tay cử động linh hoạt, không bị kích nách. 3. Quy trình May "Hạng nặng" Chỉ Cotton 20/3: Sử dụng chỉ se 3 sợi tiết diện lớn thay vì chỉ mảnh thông thường, giúp chịu lực căng của vải dày và tạo hiệu ứng đường may nổi khối (high-low) đẹp mắt. May móc xích (Chainstitch): Áp dụng kỹ thuật cuốn sườn và vai bằng máy 2 kim móc xích, tạo đường gân "gân bò" (roping effect) chắc chắn và thẩm mỹ. 4. Chi tiết Hoàn thiện &amp; Phụ liệu Lai áo bản lớn (4cm): May gấp mí to bản giúp dằn trọng lượng, giữ tà áo luôn thẳng thớm, không bị quăn mép hay hớt lên. Cổ áo ép keo dựng: Sử dụng keo UD9975 ép mặt chính cho lá cổ và nẹp khuy, đảm bảo đứng form, không bị dộp (bubbling) sau khi giặt. Khuy &amp; Nút đồng bộ: Khuy đầu được đóng bằng máy chuyên dụng, thông số ăn khớp hoàn hảo với nút kim loại để thao tác cài nhẹ nhàng nhưng chắc chắn. Gia cố chịu lực: Đóng bọ (Bartack) tại hai góc miệng túi đắp để chống toạc rách khi chứa vật nặng. TỔNG KẾT Sản phẩm cân bằng hoàn hảo giữa thẩm mỹ Workwear bụi bặm và sự thoải mái khi sử dụng. Lý tưởng để mặc độc lập hoặc khoác ngoài (Layering) như một chiếc Shacket bền bỉ theo năm tháng. THÔNG TIN NHANH Chất liệu: DurableTex™ Cotton Ultra Twill (100% Cotton) - Định lượng 11.5oz. Chi tiết sản phẩm: Phom Boxy &amp; Loose Fit, Vai trễ (Drop Shoulder), Nút kim loại, Túi ngực ', 'YAME', 405650, 427000, true, 5.0, 2331, 225, 4.1, 158, 'active', false, true, false, 'Áo Sơ Mi Tay Ngắn Giấu Bụng DurableTex™ Vải Dày Dặn Đứng Form Multi Color Jean 003 Màu Nâu Đậm Dáng Rộng Rãi F4', 'Áo Sơ Mi Tay Ngắn Multi Color Jean 003 1. Chất Liệu DurableTex™ Bền Bỉ &amp; Jean Look Vải DurableTex™ 11.5oz: Dệt kiểu Twill (Vân chéo) từ 100% Cotton tự nhiên. Cấu trúc này mang lại độ dày dặn, đứng phom (Shape Retention) nhưng vẫn đảm bảo độ thoáng khí, không gây hầm bí. Hiệu ứng Jean Look: Bề mặ', '110426-sale-5, F4 - Loose Fit (Dáng Rộng), màu nâu, Quần áo, signature, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
