INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_5bcdb57ea6af4db6', 'cat_shirt_short', 'Áo Sơ Mi Tay Ngắn Mát Như Vải Đũi AirDry™ Thoát Mồ Hôi Nhanh The No Style 117 Màu Xanh Lá Đậm Dáng Rộng Rãi F4', 'ao-so-mi-tay-ngan-mat-nhu-vai-dui-airdry-thoat-mo-hoi-nhanh-the-no-style-117-mau-xanh-la-dam-dang-rong-rai-f4', '0025007', 'Áo Sơ Mi Tay Ngắn The No Style 117 1. Chất Liệu AirDry™ Rayon Plus Slub (155gsm) Kết cấu lai (Hybrid): Tỷ lệ 49% Rayon tạo độ rủ mềm tự nhiên, kết hợp 51% Polyester &amp; Nylon đóng vai trò "cốt thép" giúp vải bền, chịu lực kéo tốt và hạn chế co rút tối đa. Non-sticky (Không bết dính): Bề mặt dệt xư', 'Áo Sơ Mi Tay Ngắn The No Style 117 1. Chất Liệu AirDry™ Rayon Plus Slub (155gsm) Kết cấu lai (Hybrid): Tỷ lệ 49% Rayon tạo độ rủ mềm tự nhiên, kết hợp 51% Polyester &amp; Nylon đóng vai trò "cốt thép" giúp vải bền, chịu lực kéo tốt và hạn chế co rút tối đa. Non-sticky (Không bết dính): Bề mặt dệt xước (Slub 3D) tạo độ lồi lõm, giảm diện tích tiếp xúc với da. Kết hợp các khe hở vi mô giúp lưu thông khí, đảm bảo áo không dính bết vào lưng ngay cả khi đổ mồ hôi. Hiệu ứng nhăn tự nhiên (Casual Look): Vải có độ nhăn nhẹ đặc trưng (ít nhăn hơn Linen). Hiệu ứng này giúp bạn không cần phải ủi phẳng lì, mặc lên vẫn đẹp theo phong cách tự nhiên. 2. Kỹ Thuật Rập Vertical Curved &amp; Phom Loose Fit Cúp dọc định hình: Hai đường rã cúp thân trước (Vertical Curved Panels) tạo khối 3D, giúp kiểm soát độ bay của vải Rayon, giữ phom áo đứng và không bị "lùng bùng". Tối ưu vận động: Phom dáng Loose Fit với vai trễ (+11cm) và dung sai ngực/lai nới rộng (+4cm) tạo không gian thoáng khí, mang lại sự thoải mái tuyệt đối. 3. Độ Bền &amp; Hoàn Thiện Chi Tiết Chống nhăn đường may (Anti-puckering): Sử dụng keo tan chạy kèm trong đường sườn và nách giúp "chết" đường may, ngăn chặn tuyệt đối tình trạng nhăn nhúm sau khi giặt. May cuốn &amp; Móc xích: Sử dụng máy 2 kim móc xích (Chainstitch) giúp đường may đàn hồi tốt theo cử động cơ thể, mặt trong êm ái không gây ngứa. TỔNG KẾT No Style 117 là lựa chọn cân bằng hoàn hảo giữa sự phóng khoáng (Casual Look) và kết cấu kỹ thuật chỉn chu. Giải pháp tối ưu cho mùa hè: Mặc mát, không dính bết và bền bỉ. THÔNG TIN NHANH Chất liệu: AirDry™ Rayon Plus Slub 155gsm , 49% Rayon, 34% Polyester, 17% Nylon. Chi tiết sản phẩm: Loose Fit, Vai trễ , Rập cúp dọc 3D. Lưu ý giặt ủi: Giặt nước lạnh (&lt;40°C), khuyến khích dùng túi giặt. Ủi nhiệt độ thấp (&lt;150°C). Không dùng thuốc tẩy.', 'YAME', 263150, 277000, true, 5.0, 3557, 103, 4.1, 59, 'active', false, true, true, 'Áo Sơ Mi Tay Ngắn Mát Như Vải Đũi AirDry™ Thoát Mồ Hôi Nhanh The No Style 117 Màu Xanh Lá Đậm Dáng Rộng Rãi F4', 'Áo Sơ Mi Tay Ngắn The No Style 117 1. Chất Liệu AirDry™ Rayon Plus Slub (155gsm) Kết cấu lai (Hybrid): Tỷ lệ 49% Rayon tạo độ rủ mềm tự nhiên, kết hợp 51% Polyester &amp; Nylon đóng vai trò "cốt thép" giúp vải bền, chịu lực kéo tốt và hạn chế co rút tối đa. Non-sticky (Không bết dính): Bề mặt dệt xư', '110426-sale-5, F4 - Loose Fit (Dáng Rộng), màu xanh lá, Quần áo, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_e7d868418be04326', 'cat_shirt_short', 'Áo Sơ Mi Tay Ngắn Mát Như Vải Đũi AirDry™ Thoát Mồ Hôi Nhanh The No Style 117 Màu Nâu Nhạt Dáng Rộng Rãi F4', 'ao-so-mi-tay-ngan-mat-nhu-vai-dui-airdry-thoat-mo-hoi-nhanh-the-no-style-117-mau-nau-nhat-dang-rong-rai-f4', '0025006', 'Áo Sơ Mi Tay Ngắn The No Style 117 1. Chất Liệu AirDry™ Rayon Plus Slub (155gsm) Kết cấu lai (Hybrid): Tỷ lệ 49% Rayon tạo độ rủ mềm tự nhiên, kết hợp 51% Polyester &amp; Nylon đóng vai trò "cốt thép" giúp vải bền, chịu lực kéo tốt và hạn chế co rút tối đa. Non-sticky (Không bết dính): Bề mặt dệt xư', 'Áo Sơ Mi Tay Ngắn The No Style 117 1. Chất Liệu AirDry™ Rayon Plus Slub (155gsm) Kết cấu lai (Hybrid): Tỷ lệ 49% Rayon tạo độ rủ mềm tự nhiên, kết hợp 51% Polyester &amp; Nylon đóng vai trò "cốt thép" giúp vải bền, chịu lực kéo tốt và hạn chế co rút tối đa. Non-sticky (Không bết dính): Bề mặt dệt xước (Slub 3D) tạo độ lồi lõm, giảm diện tích tiếp xúc với da. Kết hợp các khe hở vi mô giúp lưu thông khí, đảm bảo áo không dính bết vào lưng ngay cả khi đổ mồ hôi. Hiệu ứng nhăn tự nhiên (Casual Look): Vải có độ nhăn nhẹ đặc trưng (ít nhăn hơn Linen). Hiệu ứng này giúp bạn không cần phải ủi phẳng lì, mặc lên vẫn đẹp theo phong cách tự nhiên. 2. Kỹ Thuật Rập Vertical Curved &amp; Phom Loose Fit Cúp dọc định hình: Hai đường rã cúp thân trước (Vertical Curved Panels) tạo khối 3D, giúp kiểm soát độ bay của vải Rayon, giữ phom áo đứng và không bị "lùng bùng". Tối ưu vận động: Phom dáng Loose Fit với vai trễ (+11cm) và dung sai ngực/lai nới rộng (+4cm) tạo không gian thoáng khí, mang lại sự thoải mái tuyệt đối. 3. Độ Bền &amp; Hoàn Thiện Chi Tiết Chống nhăn đường may (Anti-puckering): Sử dụng keo tan chạy kèm trong đường sườn và nách giúp "chết" đường may, ngăn chặn tuyệt đối tình trạng nhăn nhúm sau khi giặt. May cuốn &amp; Móc xích: Sử dụng máy 2 kim móc xích (Chainstitch) giúp đường may đàn hồi tốt theo cử động cơ thể, mặt trong êm ái không gây ngứa. TỔNG KẾT No Style 117 là lựa chọn cân bằng hoàn hảo giữa sự phóng khoáng (Casual Look) và kết cấu kỹ thuật chỉn chu. Giải pháp tối ưu cho mùa hè: Mặc mát, không dính bết và bền bỉ. THÔNG TIN NHANH Chất liệu: AirDry™ Rayon Plus Slub 155gsm , 49% Rayon, 34% Polyester, 17% Nylon. Chi tiết sản phẩm: Loose Fit, Vai trễ , Rập cúp dọc 3D. Lưu ý giặt ủi: Giặt nước lạnh (&lt;40°C), khuyến khích dùng túi giặt. Ủi nhiệt độ thấp (&lt;150°C). Không dùng thuốc tẩy.', 'YAME', 263150, 277000, true, 5.0, 3966, 437, 4.9, 101, 'active', false, true, false, 'Áo Sơ Mi Tay Ngắn Mát Như Vải Đũi AirDry™ Thoát Mồ Hôi Nhanh The No Style 117 Màu Nâu Nhạt Dáng Rộng Rãi F4', 'Áo Sơ Mi Tay Ngắn The No Style 117 1. Chất Liệu AirDry™ Rayon Plus Slub (155gsm) Kết cấu lai (Hybrid): Tỷ lệ 49% Rayon tạo độ rủ mềm tự nhiên, kết hợp 51% Polyester &amp; Nylon đóng vai trò "cốt thép" giúp vải bền, chịu lực kéo tốt và hạn chế co rút tối đa. Non-sticky (Không bết dính): Bề mặt dệt xư', '110426-sale-5, F4 - Loose Fit (Dáng Rộng), màu nâu, Quần áo, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_050547e1321b4507', 'cat_shirt_short', 'Áo Sơ Mi Tay Ngắn AirDry™ Vải Nhẹ Thoát Mồ Hôi Nhanh The No Style 217 Màu Xanh Lá Đậm Dáng Vừa Vặn F3', 'ao-so-mi-tay-ngan-airdry-vai-nhe-thoat-mo-hoi-nhanh-the-no-style-217-mau-xanh-la-dam-dang-vua-van-f3', '0024844', 'Áo Sơ Mi Tay Ngắn The No Style 217 1. VẢI AIRDRY™ &amp; HIỆU SUẤT BỀ MẶT Chất liệu: Sử dụng vải AirDry™ Polyester Basic Jacquard 200gsm (độ dày trung bình). Cấu trúc dệt: Ứng dụng kỹ thuật dệt kim "Lưới Mắt Chim Cấu Trúc" (Structural Bird’s Eye Mesh) 2 mặt. Mặt ngoài: Hàng ngàn lỗ lưới nổi giúp thôn', 'Áo Sơ Mi Tay Ngắn The No Style 217 1. VẢI AIRDRY™ &amp; HIỆU SUẤT BỀ MẶT Chất liệu: Sử dụng vải AirDry™ Polyester Basic Jacquard 200gsm (độ dày trung bình). Cấu trúc dệt: Ứng dụng kỹ thuật dệt kim "Lưới Mắt Chim Cấu Trúc" (Structural Bird’s Eye Mesh) 2 mặt. Mặt ngoài: Hàng ngàn lỗ lưới nổi giúp thông gió và thoát nhiệt trực tiếp. Mặt trong: Dệt phẳng và lì, mang lại cảm giác êm ái, không gây ma sát với da. Hiệu năng: Tính năng kỵ nước của 100% Polyester giúp mồ hôi bay hơi nhanh, giữ cơ thể khô ráo và không bị bết dính. 2. CẤU TRÚC RẬP &amp; TỐI ƯU PHOM DÁNG Phom Regular cải tiến: Phát triển từ phom suông thẳng cơ bản nhưng cộng thêm 1cm chiều dài, giúp tôn dáng lưng và tạo hiệu ứng gọn gàng hơn. Cổ Cuban linh hoạt: Thiết kế lá cổ danton có thể chuyển đổi 2 kiểu: mở nút phóng khoáng hoặc cài kín lịch sự. Vận động: Giữ nguyên thông số vai và nách tiêu chuẩn để đảm bảo cử động tay thoải mái nhất. 3. ĐỘ BỀN KẾT CẤU &amp; CHI TIẾT TINH TẾ Đường may tiêu chuẩn: Mật độ chỉ 4.5 mũi/cm, sử dụng chỉ Cotton 40/2 bền bỉ, hạn chế bung rách. Gia cố chắc chắn: Sườn áo may bằng máy Vắt sổ 5 chỉ (Safety Stitch) chịu lực căng tốt; tà áo có đánh bọ (bar tack) chống xé. Chi tiết tinh tế: Cổ áo ép keo lụa giúp đứng form, không bị rộp. Vai may lộn kín (Clean Finish) giấu mép vải, không gây ngứa. Dây treo (Hanger Loop) tiện lợi ở chân cổ. TỔNG KẾT The No Style 217 giải quyết bài toán cân bằng giữa độ thoáng mát và sự chỉn chu. Sản phẩm thay thế vải mỏng bằng cấu trúc lưới thông minh, đảm bảo sự khô ráo, bền bỉ và giữ phom tốt trong mọi điều kiện sử dụng. THÔNG TIN NHANH Chất liệu: AirDry™ Polyester Basic Jacquard 200gsm, 100% Polyester Chi tiết sản phẩm: Regular Fit, Cổ Cuban, Xẻ lai, Dây treo chân cổ. Lưu ý giặt ủi: Bắt buộc lộn trái áo và cài kín nút/khóa kéo khi giặt máy để tránh vướng móc vào mặt lưới. Giặt nước lạnh/ấm (&lt; 40°C), không dùng tẩy Clo. Ủi nhiệt độ thấp (&lt; 120°C), nên ủi mặt trái hoặc dùng khăn lót.', 'YAME', 282150, 297000, true, 5.0, 1543, 387, 4.3, 154, 'active', false, true, false, 'Áo Sơ Mi Tay Ngắn AirDry™ Vải Nhẹ Thoát Mồ Hôi Nhanh The No Style 217 Màu Xanh Lá Đậm Dáng Vừa Vặn F3', 'Áo Sơ Mi Tay Ngắn The No Style 217 1. VẢI AIRDRY™ &amp; HIỆU SUẤT BỀ MẶT Chất liệu: Sử dụng vải AirDry™ Polyester Basic Jacquard 200gsm (độ dày trung bình). Cấu trúc dệt: Ứng dụng kỹ thuật dệt kim "Lưới Mắt Chim Cấu Trúc" (Structural Bird’s Eye Mesh) 2 mặt. Mặt ngoài: Hàng ngàn lỗ lưới nổi giúp thôn', '110426-sale-5, F3 - Regular Fit (Dáng Tiêu Chuẩn), màu xanh lá, Quần áo, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
