INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_e46466b0c1624963', 'cat_shirt_short', 'Áo Sơ Mi Tay Ngắn RainShield™ Vải Mềm Nhẹ Không Bám Nước Dễ Dàng Lau Sạch The Weekend 031 Màu Nâu Dáng Vừa Vặn F3', 'ao-so-mi-tay-ngan-rainshield-vai-mem-nhe-khong-bam-nuoc-de-dang-lau-sach-the-weekend-031-mau-nau-dang-vua-van-f3', '0024584', 'Áo Sơ Mi Tay Ngắn RainShield™ The Weekend 031 1. Chất liệu RainShield™ (130gsm) Vải chuyên dụng có khả năng trượt nước (hiệu ứng lá sen), giúp bạn khô ráo trước những cơn mưa nhẹ bất chợt và hạn chế bám bẩn. 2. Khô nhanh &amp; Ít nhăn Cấu trúc sợi Polyester kị nước giúp thoát ẩm nhanh chóng, không g', 'Áo Sơ Mi Tay Ngắn RainShield™ The Weekend 031 1. Chất liệu RainShield™ (130gsm) Vải chuyên dụng có khả năng trượt nước (hiệu ứng lá sen), giúp bạn khô ráo trước những cơn mưa nhẹ bất chợt và hạn chế bám bẩn. 2. Khô nhanh &amp; Ít nhăn Cấu trúc sợi Polyester kị nước giúp thoát ẩm nhanh chóng, không gây bết dính mồ hôi và giữ mặt vải phẳng phiu mà không cần là ủi nhiều. 3. Phom dáng Regular Fit thông thoáng Thiết kế cổ Cuban mở và đô sau 2 lớp giúp định hình khung vai vuông vức nhưng vẫn đảm bảo lưu thông không khí, giảm cảm giác bí bách. 4. Kỹ thuật may gia cố bền bỉ Cổ áo ép keo chuyên dụng chống rộp vải sau khi giặt. Các điểm chịu lực (nách, tà) được gia cố chắc chắn, ngăn chặn tình trạng sứt chỉ khi vận động mạnh. TỔNG KẾT The Weekend 031 là giải pháp sơ mi thực dụng với khả năng kháng nước, khô nhanh và giữ phom dáng bền bỉ, phù hợp cho mọi hoạt động từ văn phòng đến di chuyển ngoài trời. THÔNG TIN NHANH Chất liệu: RainShield™ Polyester Basic Plain 130gsm, 100% Polyester Chi tiết sản phẩm: F3 - Regular Fit (Dáng Tiêu Chuẩn), cổ Cuban, đô sau 2 lớp. Lưu ý giặt/ủi: Lộn trái khi giặt, ưu tiên ủi hơi nước mặt trái, tránh tì đè bàn ủi nóng quá lâu tại một vị trí.', 'YAME', 244150, 257000, true, 5.0, 4401, 370, 4.2, 146, 'active', false, true, false, 'Áo Sơ Mi Tay Ngắn RainShield™ Vải Mềm Nhẹ Không Bám Nước Dễ Dàng Lau Sạch The Weekend 031 Màu Nâu Dáng Vừa Vặn F3', 'Áo Sơ Mi Tay Ngắn RainShield™ The Weekend 031 1. Chất liệu RainShield™ (130gsm) Vải chuyên dụng có khả năng trượt nước (hiệu ứng lá sen), giúp bạn khô ráo trước những cơn mưa nhẹ bất chợt và hạn chế bám bẩn. 2. Khô nhanh &amp; Ít nhăn Cấu trúc sợi Polyester kị nước giúp thoát ẩm nhanh chóng, không g', '110426-sale-5, F3 - Regular Fit (Dáng Tiêu Chuẩn), Gu thiết kế, màu nâu, Quần áo, signature0226, signature0426, Thời Trang Không Đơn Giản, Áo, Áo sơ mi', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
