INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_7908be1e59444178', 'cat_shirt_short', 'Áo Sơ Mi Tay Ngắn DurableTex™ Vải Bền Bỉ Thoát Ẩm Tốt The Weekend 036 Màu Đen Dáng Rộng Rãi F4', 'ao-so-mi-tay-ngan-durabletex-vai-ben-bi-thoat-am-tot-the-weekend-036-mau-den-dang-rong-rai-f4', '0024595', 'Áo Sơ Mi Tay Ngắn DurableTex™ The Weekend 036 1. Phom Loose Fit Giải phóng hình thể, cân bằng tỉ lệ Giải phóng cử động: Vai nới rộng và nách hạ sâu giúp triệt tiêu cảm giác gò bó khi lái xe hay nâng cánh tay. Cân bằng tỉ lệ: Thân áo vuông vức giúp che khuyết điểm bụng, chiều dài áo được thu ngắn tin', 'Áo Sơ Mi Tay Ngắn DurableTex™ The Weekend 036 1. Phom Loose Fit Giải phóng hình thể, cân bằng tỉ lệ Giải phóng cử động: Vai nới rộng và nách hạ sâu giúp triệt tiêu cảm giác gò bó khi lái xe hay nâng cánh tay. Cân bằng tỉ lệ: Thân áo vuông vức giúp che khuyết điểm bụng, chiều dài áo được thu ngắn tinh tế để mặc thả ngoài quần vẫn lịch sự, tôn dáng chân dài. 2. Vải DurableTex™ Twill: Đứng phom tự nhiên, là ủi tối giản Đứng phom: Kiểu dệt vân chéo (Twill) tạo độ dày dặn, giúp áo không dán sát vào da khi đổ mồ hôi. Easy Care: Khả năng tự hồi phục nếp gấp vượt trội, hạn chế tối đa việc nhăn nhàu, giúp bạn tiết kiệm thời gian là ủi mỗi ngày. 3. Hoàn thiện: Tỉ mỉ từng mũi kim, vững chãi theo thời gian Đường may cuốn kín: Toàn bộ sườn và nách áo được gói kín mép vải, tăng gấp đôi độ bền kéo và không gây ngứa da. Gia cố Piping: Các đường gân nổi ở vai và túi đóng vai trò "khung xương" giữ áo không bị biến dạng sau nhiều lần giặt máy. Chi tiết tinh tế: Nút quấn chân chỉ giúp cài khuy bằng một tay dễ dàng và chống đứt chỉ khuy nút khi vận động mạnh. TỔNG KẾT The Weekend 036 là giải pháp sơ mi bền bỉ, chống nhăn và giải phóng hình thể tối đa. Sản phẩm dành cho nam giới hiện đại cần sự chỉn chu nhưng vẫn đòi hỏi sự thoải mái tuyệt đối cả ngày dài. THÔNG TIN NHANH Chất liệu: DurableTex™ Polyester Ultra Twill 145gsm, 100% Polyester Chi tiết: F4 - Loose Fit (Dáng Rộng), viền vai gân, túi đắp trước ngực, dây treo áo (phía sau cổ) Lưu ý giặt ủi: Giặt máy chế độ bình thường, lộn trái sản phẩm, tránh phơi trực tiếp dưới nắng gắt để giữ màu bền lâu.', 'YAME', 263150, 277000, true, 5.0, 3480, 389, 4.3, 121, 'active', false, true, false, 'Áo Sơ Mi Tay Ngắn DurableTex™ Vải Bền Bỉ Thoát Ẩm Tốt The Weekend 036 Màu Đen Dáng Rộng Rãi F4', 'Áo Sơ Mi Tay Ngắn DurableTex™ The Weekend 036 1. Phom Loose Fit Giải phóng hình thể, cân bằng tỉ lệ Giải phóng cử động: Vai nới rộng và nách hạ sâu giúp triệt tiêu cảm giác gò bó khi lái xe hay nâng cánh tay. Cân bằng tỉ lệ: Thân áo vuông vức giúp che khuyết điểm bụng, chiều dài áo được thu ngắn tin', '110426-sale-5, F4 - Loose Fit (Dáng Rộng), Gu thiết kế, màu đen, Quần áo, signature, signature0226, signature0426, Thời Trang Không Đơn Giản, Áo', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
