INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_8e8f11c6a5c4431f', 'cat_shirt_short', 'Áo Sơ Mi Tay Ngắn Vải 3D AirDry™ Co Giãn Mềm Mịn Họa The No Style 082 Màu Be Dáng Vừa Vặn F3', 'ao-so-mi-tay-ngan-vai-3d-airdry-co-gian-mem-min-hoa-the-no-style-082-mau-be-dang-vua-van-f3', '0023522', 'ID sản phẩm: The No Style 082 Áo sơ mi cuban dáng rộng bền bỉ có dộ co giãn , hiệu ứng lạ mắt. 1. Kiểu sản phẩm: Áo Sơ Mi Tay Ngắn 2. Ưu điểm: -Hiệu ứng vải 3D, độc đáo: Kiểu dệt lạ mắt tạo hiệu ứng ô vuông nổi chìm, mang đến sự khác biệt. -Co giãn nhẹ, thoải mái vận động: Chất liệu Polyester pha Sp', 'ID sản phẩm: The No Style 082 Áo sơ mi cuban dáng rộng bền bỉ có dộ co giãn , hiệu ứng lạ mắt. 1. Kiểu sản phẩm: Áo Sơ Mi Tay Ngắn 2. Ưu điểm: -Hiệu ứng vải 3D, độc đáo: Kiểu dệt lạ mắt tạo hiệu ứng ô vuông nổi chìm, mang đến sự khác biệt. -Co giãn nhẹ, thoải mái vận động: Chất liệu Polyester pha Spandex co giãn nhẹ, bền màu, thoải mái trong mọi cử động. -Thiết kế tiện dụng, phong cách: Hai túi đắp có nắp che bảo vệ đồ vật, đồng thời tạo điểm nhấn thời trang. 3. Chất liệu: Polyester Fabric 95% Polyester, 5% Spandex. 4. Kỹ thuật: Hiệu ứng vải ô vuông nổi chìm tạo sự khác biệt; thân trước có 2 túi đắp có nắp che bảo vệ đồ vật bên trong và tạo điểm nhấn. 5. Phù hợp với ai: Phong cách đa dạng, từ người yêu thích sự tối giản đến người ưa chuộng phá cách. 6. Thuộc Bộ Sưu Tập nào: No Style , mặc đẹp, mặc độc, mặc đúng mốt không giới hạn phong cách. 7. Các tên thường gọi hoặc tìm kiếm về sản phẩm này: Áo sơ mi cổ mở tay ngắn, Áo sơ nam vải họa tiết, Áo sơ mi dáng rộng, Áo sơ mi nam màu đen, Áo sơ mi basic, Áo sơ mi đi biển', 'YAME', 235450, 277000, true, 15.0, 2778, 360, 3.9, 115, 'active', false, true, false, 'Áo Sơ Mi Tay Ngắn Vải 3D AirDry™ Co Giãn Mềm Mịn Họa The No Style 082 Màu Be Dáng Vừa Vặn F3', 'ID sản phẩm: The No Style 082 Áo sơ mi cuban dáng rộng bền bỉ có dộ co giãn , hiệu ứng lạ mắt. 1. Kiểu sản phẩm: Áo Sơ Mi Tay Ngắn 2. Ưu điểm: -Hiệu ứng vải 3D, độc đáo: Kiểu dệt lạ mắt tạo hiệu ứng ô vuông nổi chìm, mang đến sự khác biệt. -Co giãn nhẹ, thoải mái vận động: Chất liệu Polyester pha Sp', '010426-sale, 010426-sale-quanao15, Cá Nhân Hóa, F3 - Regular Fit (Dáng Tiêu Chuẩn), Gu thiết kế, Quần áo, Thời Trang Không Đơn Giản, Áo, Áo sơ mi', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
