INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_5e120b0f301049c2', 'cat_shirt_short', 'Áo Sơ Mi Tay Ngắn AirDry™ Họa Tiết In Chuyển Nhiệt The No Style 079 Đen Màu Đen Dáng Vừa Vặn F3', 'ao-so-mi-tay-ngan-airdry-hoa-tiet-in-chuyen-nhiet-the-no-style-079-den-mau-den-dang-vua-van-f3', '0023772', 'ID sản phẩm: The No Style 079 Áo Sơ Mi Cuban dáng rộng bền bỉ, co giãn, trẻ trung cá tính. 1. Kiểu sản phẩm: Áo Sơ Mi Tay Ngắn 2. Ưu điểm: -Họa tiết monogram, cực chất: Họa tiết monogram phủ kín áo, tạo điểm nhấn cá tính, đậm chất streetwear. -Vải co giãn, thoải mái vận động: Chất liệu Polyester pha', 'ID sản phẩm: The No Style 079 Áo Sơ Mi Cuban dáng rộng bền bỉ, co giãn, trẻ trung cá tính. 1. Kiểu sản phẩm: Áo Sơ Mi Tay Ngắn 2. Ưu điểm: -Họa tiết monogram, cực chất: Họa tiết monogram phủ kín áo, tạo điểm nhấn cá tính, đậm chất streetwear. -Vải co giãn, thoải mái vận động: Chất liệu Polyester pha Spandex co giãn nhẹ, form rộng, mang lại sự thoải mái trong mọi hoạt động. -In chuyển nhiệt, bền màu vượt trội: Công nghệ in chuyển nhiệt sắc nét, bền màu, không lo bong tróc sau nhiều lần giặt. 3. Chất liệu: Polyester Fabric (95% Polyester 5% Spandex) 4. Kỹ thuật: In chuyển nhiệt hình in sắc nét, bền màu, không bị bong tróc, nhãn hiệu được ép lên tay áo, tạo sự tinh tế và sang trọng. 5. Phù hợp với ai: Trang phục này phù hợp với giới trẻ, tín đồ streetwear và những người muốn thể hiện cá tính riêng. 6. Thuộc Bộ Sưu Tập nào: No Style, Một bộ sưu tập thời trang đa dạng, đáp ứng nhiều phong cách khác nhau, từ tối giản đến phá cách. 7. Các tên thường gọi hoặc tìm kiếm về sản phẩm này: Sơ mi nam màu đen, Sơ mi họa tiết, Sơ mi nam overside, Sơ mi đi biển, Sơ mi trẻ trung', 'YAME', 235450, 277000, true, 15.0, 2972, 99, 4.1, 167, 'active', false, true, true, 'Áo Sơ Mi Tay Ngắn AirDry™ Họa Tiết In Chuyển Nhiệt The No Style 079 Đen Màu Đen Dáng Vừa Vặn F3', 'ID sản phẩm: The No Style 079 Áo Sơ Mi Cuban dáng rộng bền bỉ, co giãn, trẻ trung cá tính. 1. Kiểu sản phẩm: Áo Sơ Mi Tay Ngắn 2. Ưu điểm: -Họa tiết monogram, cực chất: Họa tiết monogram phủ kín áo, tạo điểm nhấn cá tính, đậm chất streetwear. -Vải co giãn, thoải mái vận động: Chất liệu Polyester pha', '010426-sale, 010426-sale-quanao15, Cá Nhân Hóa, F3 - Regular Fit (Dáng Tiêu Chuẩn), Gu thiết kế, màu đen, Quần áo, Thời Trang Không Đơn Giản, Áo, Áo sơ mi', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_58ccd71ede604fad', 'cat_shirt_short', 'Áo Sơ Mi Tay Ngắn Vải Dệt Họa Tiết Nổi 3DFlexFit™ Mặc Siêu Thoáng The No Style 184 Màu Trắng Dáng Vừa Vặn F3', 'ao-so-mi-tay-ngan-vai-det-hoa-tiet-noi-3dflexfit-mac-sieu-thoang-the-no-style-184-mau-trang-dang-vua-van-f3', '0023837', 'Áo Sơ Mi Tay Ngắn FlexFit™ The No Style 184 1. Chất liệu FlexFit™: Cấu trúc Jacquard 3D thoát nhiệt Vấn đề: Sợi tổng hợp truyền thống thường gây bí bách và bết dính khi đổ mồ hôi. Giải pháp: Sử dụng vải FlexFit™ Polyester Ultra Jacquard (định lượng 220gsm) với kiểu dệt cấu trúc nổi 3D. Hiệu quả: Các', 'Áo Sơ Mi Tay Ngắn FlexFit™ The No Style 184 1. Chất liệu FlexFit™: Cấu trúc Jacquard 3D thoát nhiệt Vấn đề: Sợi tổng hợp truyền thống thường gây bí bách và bết dính khi đổ mồ hôi. Giải pháp: Sử dụng vải FlexFit™ Polyester Ultra Jacquard (định lượng 220gsm) với kiểu dệt cấu trúc nổi 3D. Hiệu quả: Các "bông xốp nổi" tạo ra rãnh dẫn khí giữa bề mặt vải và da, tối ưu hóa khả năng lưu thông không khí. Thành phần 5% Spandex hỗ trợ co giãn đa chiều, giúp vận động linh hoạt. 2. Kỹ thuật dựng rập: Phom Oversize tối ưu tỉ lệ Vấn đề: Áo phom rộng dễ gây cảm giác luộm thuộm hoặc làm mất cân đối vóc dáng. Giải pháp: Thiết kế với lượng cử động dương lớn (Positive Ease) kết hợp cấu trúc Vai trễ &amp; Nách hạ sâu (Drop Shoulder &amp; Deep Scye). Hiệu quả: Giải phóng áp lực vùng nách khi cử động tay. Thông số dài áo và dài tay được giữ theo tỉ lệ chuẩn để đảm bảo sự gọn gàng, không bị "nuốt" dáng người mặc. 3. Tiêu chuẩn hoàn thiện: Gia cố phom dáng bền bỉ Vấn đề: Vải Jacquard xốp mềm dễ bị biến dạng hoặc đổ phom sau khi giặt. Giải pháp: Ép keo lụa: Định hình lá cổ và nẹp thân giúp giữ form đứng, sắc nét. Đô áo 2 lớp (Double Yoke): Gia cố độ bền vùng vai và che kín đường may bên trong. Mật độ chỉ: Sử dụng chỉ Cotton 40/2 với mật độ 4.5 mũi/cm đảm bảo liên kết chắc chắn. Hiệu quả: Tăng tuổi thọ sản phẩm và mang lại cảm giác êm ái khi tiếp xúc trực tiếp với da. TỔNG KẾT The No Style 184 là sự kết hợp giữa vật liệu Jacquard có hiệu ứng thị giác 3D độc đáo và kỹ thuật may công nghiệp chuẩn xác. Đây là lựa chọn tối ưu cho những ai tìm kiếm phong cách phóng khoáng nhưng yêu cầu cao về sự thoáng khí và tính tiện lợi (không cần ủi) trong sử dụng hằng ngày. THÔNG TIN NHANH Chất liệu: FlexFit™ Polyester Ultra Jacquard 220gsm, 95% Polyester, 5% Spandex Chi tiết sản phẩm: Cổ mở Cuban, phom Oversize vai trễ, đô sau 2 lớp Lưu ý giặt ủi: Bắt buộc lộn trái và sử dụng túi giặt để tránh móc sợi (snagging). Giặt máy chế độ nhẹ, không sấy nóng để bảo vệ sợi Spandex. Sản phẩm chống nhăn tuyệt đối, không', 'YAME', 263150, 277000, true, 5.0, 695, 257, 4.8, 32, 'active', false, true, false, 'Áo Sơ Mi Tay Ngắn Vải Dệt Họa Tiết Nổi 3DFlexFit™ Mặc Siêu Thoáng The No Style 184 Màu Trắng Dáng Vừa Vặn F3', 'Áo Sơ Mi Tay Ngắn FlexFit™ The No Style 184 1. Chất liệu FlexFit™: Cấu trúc Jacquard 3D thoát nhiệt Vấn đề: Sợi tổng hợp truyền thống thường gây bí bách và bết dính khi đổ mồ hôi. Giải pháp: Sử dụng vải FlexFit™ Polyester Ultra Jacquard (định lượng 220gsm) với kiểu dệt cấu trúc nổi 3D. Hiệu quả: Các', 'Cá Nhân Hóa, F3 - Regular Fit (Dáng Tiêu Chuẩn), Gu thiết kế, màu trắng, Quần áo, signature0426, Thời Trang Không Đơn Giản, Áo, Áo sơ mi', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
