INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_c8db66c242794c22', 'cat_shirt_long', 'Áo Sơ Mi Tay Dài Công Sở AirDry™ Vải Sọc Siêu Nhẹ Thoáng The Minimalist 017 Màu Xanh Dương Nhạt Dáng Vừa Vặn F3', 'ao-so-mi-tay-dai-cong-so-airdry-vai-soc-sieu-nhe-thoang-the-minimalist-017-mau-xanh-duong-nhat-dang-vua-van-f3', '0025030', 'Áo Sơ Mi Thanh Lịch AirDry™ The Minimalist 017 1. Chất liệu AirDry™ Jacquard: Mặc nhẹ như không, tự tin vận động Mát lạnh cả ngày: Thay vì cảm giác bí bách, cấu trúc dệt với hàng ngàn "lỗ thở" li ti giúp áo luôn thoáng khí. Dù bạn phải di chuyển ngoài trời nắng nóng, mồ hôi cũng sẽ bay hơi cực nhanh', 'Áo Sơ Mi Thanh Lịch AirDry™ The Minimalist 017 1. Chất liệu AirDry™ Jacquard: Mặc nhẹ như không, tự tin vận động Mát lạnh cả ngày: Thay vì cảm giác bí bách, cấu trúc dệt với hàng ngàn "lỗ thở" li ti giúp áo luôn thoáng khí. Dù bạn phải di chuyển ngoài trời nắng nóng, mồ hôi cũng sẽ bay hơi cực nhanh, không gây bết dính. Tôn dáng nhờ sọc chìm: Những đường kẻ sọc tinh tế được dệt trực tiếp vào vải tạo hiệu ứng thị giác giúp bạn trông cao và thon gọn hơn mà vẫn giữ được sự lịch lãm. Không lo biến dạng ống tay: Với độ đàn hồi cao, vải sẽ tự "co" về trạng thái cũ sau mỗi cử động. Bạn sẽ không còn thấy phần khuỷu tay áo bị phồng hay nhăn nhúm mất thẩm mỹ. 2. Phom dáng Regular Fit: Chỉn chu từ vai xuống bụng Vai áo vuông vức: Thiết kế cầu vai hai lớp giúp áo đứng dáng ngay cả với người có khung vai gầy. Bạn có thể thoải mái vươn tay, lái xe mà không cảm thấy bị kích hay căng xé mặt vải. Gọn gàng vùng bụng: Phom áo được tinh chỉnh để vừa vặn, che khuyết điểm bụng tốt nhưng không quá rộng thùng thình. Đặc biệt, vùng nách áo được xử lý kỹ để khi hạ tay xuống, vải luôn phẳng phiu, không bị đùn vải thừa. 3. Hoàn thiện tỉ mỉ: Mặc êm ái, bền bỉ qua năm tháng Chắc chắn từng đường kim: Với mật độ chỉ dày đặc, chiếc áo chịu được áp lực giặt máy thường xuyên mà không lo bung chỉ hay sờn mép. Mặt trong sạch mịn: Mọi đường may sườn được cuốn kín vào trong. Bạn sẽ cảm thấy sự êm ái tuyệt đối, không còn những đường vắt sổ thô ráp gây ngứa hay kích ứng da. Cổ áo "chuẩn chỉnh" như mới: Nhờ công nghệ ép keo nhiệt hiện đại, cổ áo luôn giữ được độ đứng, phẳng phiu, không bị nổi bong bóng hay dợn sóng kể cả sau hàng chục lần giặt. TỔNG KẾT Người bạn đồng hành lý tưởng cho quý ông công sở: áo nhẹ tênh, cực kỳ thoáng mát và giữ được phom dáng chỉn chu từ sáng sớm đến tối muộn. THÔNG TIN NHANH Chất liệu: AirDry™ Polyester Ultra Jacquard 130gsm, 100% Polyester. Chi tiết: F3 - Regular Fit (Dáng Tiêu Chuẩn), túi áo trước ngực, lai nhỏ. Lưu ý giặt ủi: Lộn trái khi giặt, sử dụng túi giặt để bảo vệ sợi', 'YAME', 377150, 397000, true, 5.0, 1081, 401, 4.1, 191, 'active', false, true, false, 'Áo Sơ Mi Tay Dài Công Sở AirDry™ Vải Sọc Siêu Nhẹ Thoáng The Minimalist 017 Màu Xanh Dương Nhạt Dáng Vừa Vặn F3', 'Áo Sơ Mi Thanh Lịch AirDry™ The Minimalist 017 1. Chất liệu AirDry™ Jacquard: Mặc nhẹ như không, tự tin vận động Mát lạnh cả ngày: Thay vì cảm giác bí bách, cấu trúc dệt với hàng ngàn "lỗ thở" li ti giúp áo luôn thoáng khí. Dù bạn phải di chuyển ngoài trời nắng nóng, mồ hôi cũng sẽ bay hơi cực nhanh', '080426-sale-5, màu xanh dương, Quần áo, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
