INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_570b863bf1294fe9', 'cat_shirt_long', 'Áo Sơ Mi Tay Dài RainShield™ Vải Trượt Nước Mặc Nhẹ Bền Bỉ The Minimalist 024 Màu Xám Nhạt Dáng Vừa Vặn F3', 'ao-so-mi-tay-dai-rainshield-vai-truot-nuoc-mac-nhe-ben-bi-the-minimalist-024-mau-xam-nhat-dang-vua-van-f3', '0024667', 'Áo Sơ Mi Tay Dài RainShield™ The Minimalist 024 1. Chất liệu RainShield™ Modal Plus Công nghệ bảo vệ: Tích hợp lớp phủ Coating 3-Proof tạo hiệu ứng trượt nước vượt trội. Các chất lỏng và vết bẩn dạng lỏng sẽ trượt đi, cho phép lau sạch ngay lập tức. Cấu trúc dệt Plain Weave: Sử dụng kiểu dệt trơn 1/', 'Áo Sơ Mi Tay Dài RainShield™ The Minimalist 024 1. Chất liệu RainShield™ Modal Plus Công nghệ bảo vệ: Tích hợp lớp phủ Coating 3-Proof tạo hiệu ứng trượt nước vượt trội. Các chất lỏng và vết bẩn dạng lỏng sẽ trượt đi, cho phép lau sạch ngay lập tức. Cấu trúc dệt Plain Weave: Sử dụng kiểu dệt trơn 1/1 với mật độ cao (110*88) giúp bề mặt vải phẳng, đanh chắc và ổn định phom dáng. Sợi lai ưu việt: Thành phần 88% Polyester kết hợp 12% Modal giúp áo khô nhanh (QuickDry), bền bỉ, hạn chế xô sợi và nấm mốc. 2. Kỹ thuật rập &amp; Kết cấu phom (Regular Fit cải tiến) Tối ưu sơ-vin (đóng thùng): Chiều dài áo được tăng thêm 1cm so với tiêu chuẩn giúp vạt áo không bị tuột khỏi quần khi đứng ngồi hoặc vận động mạnh. Đô sau rã đôi (Split Yoke): Kết cấu 2 lớp lộn sạch giúp vai áo ôm sát hơn và tăng cường khả năng chịu lực. 3. Tiêu chuẩn may hàng kỹ Đường may siêu nhuyễn: Áp dụng mật độ chỉ cao 4.5 mũi/cm, đảm bảo đường may mịn, chắc, không bị đứt hay giãn khi vận động. Kỹ thuật may cuốn (Felled Seams): Toàn bộ sườn áo và vòng nách được may cuốn sạch thay vì vắt sổ, giúp tăng độ bền kết cấu gấp đôi và không gây cộm ngứa. Công nghệ ép keo (Fusing Technology): Sử dụng keo vải cao cấp cho cổ áo và măng-sét, giúp giữ phom sắc nét, chống rộp sau nhiều lần giặt. TỔNG KẾT The Minimalist 024 là giải pháp sơ mi công sở chuyên dụng, ưu tiên sự chỉn chu tuyệt đối với khả năng kháng bẩn linh hoạt, giữ phom ổn định và độ bền kết cấu cao cho người dùng bận rộn. THÔNG TIN NHANH Chất liệu: RainShield™ Modal Plus Plain 125gsm, 88% Polyester 12% Modal Chi tiết sản phẩm: Phom Regular Fit, Cổ Button Down, đô sau 2 lớp. Lưu ý giặt ủi: Lộn trái khi giặt, sử dụng nước lạnh hoặc ấm (&lt; 40°C). Ưu tiên túi giặt để bảo vệ lớp coating. Ủi ở nhiệt độ trung bình (110–150°C), khuyến khích ủi mặt trái.', 'YAME', 339150, 357000, true, 5.0, 1028, 342, 5.0, 64, 'active', true, true, false, 'Áo Sơ Mi Tay Dài RainShield™ Vải Trượt Nước Mặc Nhẹ Bền Bỉ The Minimalist 024 Màu Xám Nhạt Dáng Vừa Vặn F3', 'Áo Sơ Mi Tay Dài RainShield™ The Minimalist 024 1. Chất liệu RainShield™ Modal Plus Công nghệ bảo vệ: Tích hợp lớp phủ Coating 3-Proof tạo hiệu ứng trượt nước vượt trội. Các chất lỏng và vết bẩn dạng lỏng sẽ trượt đi, cho phép lau sạch ngay lập tức. Cấu trúc dệt Plain Weave: Sử dụng kiểu dệt trơn 1/', '110426-sale-5, màu xám, Quần áo, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_ed0f4fb09cd2493c', 'cat_shirt_long', 'Áo Sơ Mi Tay Dài RainShield™ Vải Trượt Nước Mặc Nhẹ Bền Bỉ The Minimalist 024 Màu Hồng Dáng Vừa Vặn F3', 'ao-so-mi-tay-dai-rainshield-vai-truot-nuoc-mac-nhe-ben-bi-the-minimalist-024-mau-hong-dang-vua-van-f3', '0024666', 'Áo Sơ Mi Tay Dài RainShield™ The Minimalist 024 1. Chất liệu RainShield™ Modal Plus Công nghệ bảo vệ: Tích hợp lớp phủ Coating 3-Proof tạo hiệu ứng trượt nước vượt trội. Các chất lỏng và vết bẩn dạng lỏng sẽ trượt đi, cho phép lau sạch ngay lập tức. Cấu trúc dệt Plain Weave: Sử dụng kiểu dệt trơn 1/', 'Áo Sơ Mi Tay Dài RainShield™ The Minimalist 024 1. Chất liệu RainShield™ Modal Plus Công nghệ bảo vệ: Tích hợp lớp phủ Coating 3-Proof tạo hiệu ứng trượt nước vượt trội. Các chất lỏng và vết bẩn dạng lỏng sẽ trượt đi, cho phép lau sạch ngay lập tức. Cấu trúc dệt Plain Weave: Sử dụng kiểu dệt trơn 1/1 với mật độ cao (110*88) giúp bề mặt vải phẳng, đanh chắc và ổn định phom dáng. Sợi lai ưu việt: Thành phần 88% Polyester kết hợp 12% Modal giúp áo khô nhanh (QuickDry), bền bỉ, hạn chế xô sợi và nấm mốc. 2. Kỹ thuật rập &amp; Kết cấu phom (Regular Fit cải tiến) Tối ưu sơ-vin (đóng thùng): Chiều dài áo được tăng thêm 1cm so với tiêu chuẩn giúp vạt áo không bị tuột khỏi quần khi đứng ngồi hoặc vận động mạnh. Đô sau rã đôi (Split Yoke): Kết cấu 2 lớp lộn sạch giúp vai áo ôm sát hơn và tăng cường khả năng chịu lực. 3. Tiêu chuẩn may hàng kỹ Đường may siêu nhuyễn: Áp dụng mật độ chỉ cao 4.5 mũi/cm, đảm bảo đường may mịn, chắc, không bị đứt hay giãn khi vận động. Kỹ thuật may cuốn (Felled Seams): Toàn bộ sườn áo và vòng nách được may cuốn sạch thay vì vắt sổ, giúp tăng độ bền kết cấu gấp đôi và không gây cộm ngứa. Công nghệ ép keo (Fusing Technology): Sử dụng keo vải cao cấp cho cổ áo và măng-sét, giúp giữ phom sắc nét, chống rộp sau nhiều lần giặt. TỔNG KẾT The Minimalist 024 là giải pháp sơ mi công sở chuyên dụng, ưu tiên sự chỉn chu tuyệt đối với khả năng kháng bẩn linh hoạt, giữ phom ổn định và độ bền kết cấu cao cho người dùng bận rộn. THÔNG TIN NHANH Chất liệu: RainShield™ Modal Plus Plain 125gsm, 88% Polyester 12% Modal Chi tiết sản phẩm: Phom Regular Fit, Cổ Button Down, đô sau 2 lớp. Lưu ý giặt ủi: Lộn trái khi giặt, sử dụng nước lạnh hoặc ấm (&lt; 40°C). Ưu tiên túi giặt để bảo vệ lớp coating. Ủi ở nhiệt độ trung bình (110–150°C), khuyến khích ủi mặt trái.', 'YAME', 339150, 357000, true, 5.0, 602, 333, 3.9, 107, 'active', false, true, false, 'Áo Sơ Mi Tay Dài RainShield™ Vải Trượt Nước Mặc Nhẹ Bền Bỉ The Minimalist 024 Màu Hồng Dáng Vừa Vặn F3', 'Áo Sơ Mi Tay Dài RainShield™ The Minimalist 024 1. Chất liệu RainShield™ Modal Plus Công nghệ bảo vệ: Tích hợp lớp phủ Coating 3-Proof tạo hiệu ứng trượt nước vượt trội. Các chất lỏng và vết bẩn dạng lỏng sẽ trượt đi, cho phép lau sạch ngay lập tức. Cấu trúc dệt Plain Weave: Sử dụng kiểu dệt trơn 1/', '110426-sale-5, màu hồng, Quần áo, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
