INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_ad61d14e90f74e9b', 'cat_shirt_long', 'Áo Sơ Mi Tay Dài AirDry™ Vải Nhẹ Thoát Nhiệt Nhanh The Worker 008 Màu Xanh Dương Nhạt Dáng Vừa Vặn F3', 'ao-so-mi-tay-dai-airdry-vai-nhe-thoat-nhiet-nhanh-the-worker-008-mau-xanh-duong-nhat-dang-vua-van-f3', '0024705', 'Áo Sơ Mi Tay Dài The Worker 008 1. CẤU TRÚC VẬT LIỆU: AirDry™ 120GSM &amp; DỆT 3D Định lượng siêu nhẹ: Trọng lượng vải 120gsm (Lightweight) giảm áp lực lên cơ thể, mang lại cảm giác nhẹ nhàng và linh hoạt suốt ngày dài. Vải AirDry™ với tỷ lệ lai tạo 60/40: Kết hợp 60% Polyester giúp thoát ẩm và khô ', 'Áo Sơ Mi Tay Dài The Worker 008 1. CẤU TRÚC VẬT LIỆU: AirDry™ 120GSM &amp; DỆT 3D Định lượng siêu nhẹ: Trọng lượng vải 120gsm (Lightweight) giảm áp lực lên cơ thể, mang lại cảm giác nhẹ nhàng và linh hoạt suốt ngày dài. Vải AirDry™ với tỷ lệ lai tạo 60/40: Kết hợp 60% Polyester giúp thoát ẩm và khô nhanh, cùng 40% Cotton giữ bề mặt bông xốp tự nhiên (Natural SoftTouch), êm ái và không vón cục. Họa tiết Diamond Jacquard: Kỹ thuật dệt tạo khối hình thoi nổi 3D trực tiếp trên cấu trúc sợi 100D x 40S, mang lại độ bền cao và vẻ ngoài tinh tế hơn so với công nghệ in. 2. CÔNG NGHỆ MAY &amp; CHỐNG NHĂN (ANTI-PUCKERING) Chống nhăn đường may: Sử dụng keo tan (fusible tape) 8mm chạy dọc đường sườn và nách để khóa nếp, ngăn chặn hiện tượng nhăn nhúm (puckering) sau khi giặt. Kết cấu bền bỉ: May cuốn sườn bằng máy 2 kim móc xích (Chainstitch) tạo độ bền kéo đứt cao và mặt trong sạch sẽ, không gây cộm ngứa. Mật độ chỉ cao: Sử dụng chỉ Cotton 40/2 với mật độ 4.5 mũi/cm giúp đường may sắc sảo và hạn chế đứt chỉ. 3. KỸ THUẬT RẬP &amp; CHI TIẾT HOÀN THIỆN Rập thông minh: Phom Regular Fit được tăng chiều dài 1cm để tạo độ dư, giữ áo không bị tuột khỏi quần khi sơ-vin và vận động. Nẹp giấu nút (Hidden Placket): Thiết kế nẹp liền che nút với bản rộng 2.8cm được may dằn chắc chắn, tạo bề mặt phẳng phiu và tối giản. Gia cố giữ form: Các chi tiết cổ và nẹp tay được ép keo lụa giúp luôn phẳng, không bị rộp. Viền cổ kỹ thuật (Inner Piping): May dây viền bọc mép chân cổ trong, giúp vùng tiếp xúc gáy cổ êm ái và tăng thẩm mỹ. TỔNG KẾT The Worker 008 là giải pháp may mặc cân bằng giữa công năng và thẩm mỹ: Vải AirDry™ 120gsm thoáng nhẹ, kết cấu Anti-puckering chống nhăn sườn áo, và thiết kế nẹp ẩn tinh tế. THÔNG TIN NHANH Chất liệu: AirDry™ Polyester Basic Jacquard 120gsm, 60% Polyester 40% Cotton Chi tiết sản phẩm: Regular Fit, Nẹp giấu nút, Cổ vạt góc, Viền bọc cổ trong. Lưu ý giặt / ủi: Giặt máy chế độ nhẹ (&lt;40°C); Không dùng thuốc tẩy; Ủi nhiệt thấp (110°C – 150°C); Nên lộn trái khi giặt', 'YAME', 329650, 347000, true, 5.0, 3948, 385, 4.6, 32, 'active', false, true, false, 'Áo Sơ Mi Tay Dài AirDry™ Vải Nhẹ Thoát Nhiệt Nhanh The Worker 008 Màu Xanh Dương Nhạt Dáng Vừa Vặn F3', 'Áo Sơ Mi Tay Dài The Worker 008 1. CẤU TRÚC VẬT LIỆU: AirDry™ 120GSM &amp; DỆT 3D Định lượng siêu nhẹ: Trọng lượng vải 120gsm (Lightweight) giảm áp lực lên cơ thể, mang lại cảm giác nhẹ nhàng và linh hoạt suốt ngày dài. Vải AirDry™ với tỷ lệ lai tạo 60/40: Kết hợp 60% Polyester giúp thoát ẩm và khô ', '110426-sale-5, F3 - Regular Fit (Dáng Tiêu Chuẩn), màu xanh dương, Quần áo, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_492022dfd68940a3', 'cat_shirt_long', 'Áo Sơ Mi Tay Dài AirDry™ Vải Nhẹ Thoát Nhiệt Nhanh The Worker 008 Màu Trắng Dáng Vừa Vặn F3', 'ao-so-mi-tay-dai-airdry-vai-nhe-thoat-nhiet-nhanh-the-worker-008-mau-trang-dang-vua-van-f3', '0024704', 'Áo Sơ Mi Tay Dài The Worker 008 1. CẤU TRÚC VẬT LIỆU: AirDry™ 120GSM &amp; DỆT 3D Định lượng siêu nhẹ: Trọng lượng vải 120gsm (Lightweight) giảm áp lực lên cơ thể, mang lại cảm giác nhẹ nhàng và linh hoạt suốt ngày dài. Vải AirDry™ với tỷ lệ lai tạo 60/40: Kết hợp 60% Polyester giúp thoát ẩm và khô ', 'Áo Sơ Mi Tay Dài The Worker 008 1. CẤU TRÚC VẬT LIỆU: AirDry™ 120GSM &amp; DỆT 3D Định lượng siêu nhẹ: Trọng lượng vải 120gsm (Lightweight) giảm áp lực lên cơ thể, mang lại cảm giác nhẹ nhàng và linh hoạt suốt ngày dài. Vải AirDry™ với tỷ lệ lai tạo 60/40: Kết hợp 60% Polyester giúp thoát ẩm và khô nhanh, cùng 40% Cotton giữ bề mặt bông xốp tự nhiên (Natural SoftTouch), êm ái và không vón cục. Họa tiết Diamond Jacquard: Kỹ thuật dệt tạo khối hình thoi nổi 3D trực tiếp trên cấu trúc sợi 100D x 40S, mang lại độ bền cao và vẻ ngoài tinh tế hơn so với công nghệ in. 2. CÔNG NGHỆ MAY &amp; CHỐNG NHĂN (ANTI-PUCKERING) Chống nhăn đường may: Sử dụng keo tan (fusible tape) 8mm chạy dọc đường sườn và nách để khóa nếp, ngăn chặn hiện tượng nhăn nhúm (puckering) sau khi giặt. Kết cấu bền bỉ: May cuốn sườn bằng máy 2 kim móc xích (Chainstitch) tạo độ bền kéo đứt cao và mặt trong sạch sẽ, không gây cộm ngứa. Mật độ chỉ cao: Sử dụng chỉ Cotton 40/2 với mật độ 4.5 mũi/cm giúp đường may sắc sảo và hạn chế đứt chỉ. 3. KỸ THUẬT RẬP &amp; CHI TIẾT HOÀN THIỆN Rập thông minh: Phom Regular Fit được tăng chiều dài 1cm để tạo độ dư, giữ áo không bị tuột khỏi quần khi sơ-vin và vận động. Nẹp giấu nút (Hidden Placket): Thiết kế nẹp liền che nút với bản rộng 2.8cm được may dằn chắc chắn, tạo bề mặt phẳng phiu và tối giản. Gia cố giữ form: Các chi tiết cổ và nẹp tay được ép keo lụa giúp luôn phẳng, không bị rộp. Viền cổ kỹ thuật (Inner Piping): May dây viền bọc mép chân cổ trong, giúp vùng tiếp xúc gáy cổ êm ái và tăng thẩm mỹ. TỔNG KẾT The Worker 008 là giải pháp may mặc cân bằng giữa công năng và thẩm mỹ: Vải AirDry™ 120gsm thoáng nhẹ, kết cấu Anti-puckering chống nhăn sườn áo, và thiết kế nẹp ẩn tinh tế. THÔNG TIN NHANH Chất liệu: AirDry™ Polyester Basic Jacquard 120gsm, 60% Polyester 40% Cotton Chi tiết sản phẩm: Regular Fit, Nẹp giấu nút, Cổ vạt góc, Viền bọc cổ trong. Lưu ý giặt / ủi: Giặt máy chế độ nhẹ (&lt;40°C); Không dùng thuốc tẩy; Ủi nhiệt thấp (110°C – 150°C); Nên lộn trái khi giặt', 'YAME', 329650, 347000, true, 5.0, 3702, 242, 3.8, 137, 'active', false, true, false, 'Áo Sơ Mi Tay Dài AirDry™ Vải Nhẹ Thoát Nhiệt Nhanh The Worker 008 Màu Trắng Dáng Vừa Vặn F3', 'Áo Sơ Mi Tay Dài The Worker 008 1. CẤU TRÚC VẬT LIỆU: AirDry™ 120GSM &amp; DỆT 3D Định lượng siêu nhẹ: Trọng lượng vải 120gsm (Lightweight) giảm áp lực lên cơ thể, mang lại cảm giác nhẹ nhàng và linh hoạt suốt ngày dài. Vải AirDry™ với tỷ lệ lai tạo 60/40: Kết hợp 60% Polyester giúp thoát ẩm và khô ', '110426-sale-5, F3 - Regular Fit (Dáng Tiêu Chuẩn), màu trắng, Quần áo, signature, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_04ecd4324086400e', 'cat_shirt_long', 'Áo Sơ Mi Tay Dài Hoạ Tiết AirDry™ Nhẹ Mịn Nét Seventy Seven 064 Màu Hồng Dáng Vừa Vặn F3', 'ao-so-mi-tay-dai-hoa-tiet-airdry-nhe-min-net-seventy-seven-064-mau-hong-dang-vua-van-f3', '0024682', 'Áo Sơ Mi Tay Dài Seventy Seven 064 1. Công Nghệ Vật Liệu Siêu Nhẹ &amp; Mềm Mượt Định lượng 105gsm: Sử dụng chất liệu AirDry™ Polyester Plus siêu nhẹ, giảm tải áp lực lên cơ thể, mang lại cảm giác "mặc như không mặc". Cấu trúc Microfiber: Sợi siêu vi (48s x 150D) tạo bề mặt phẳng mịn, êm ái với da v', 'Áo Sơ Mi Tay Dài Seventy Seven 064 1. Công Nghệ Vật Liệu Siêu Nhẹ &amp; Mềm Mượt Định lượng 105gsm: Sử dụng chất liệu AirDry™ Polyester Plus siêu nhẹ, giảm tải áp lực lên cơ thể, mang lại cảm giác "mặc như không mặc". Cấu trúc Microfiber: Sợi siêu vi (48s x 150D) tạo bề mặt phẳng mịn, êm ái với da và không gây cảm giác thô ráp. Hiệu năng cao: Tính năng thoát ẩm nhanh (Quick Dry) giúp áo luôn khô thoáng. Công nghệ in Pigment trên nền vải mịn giúp họa tiết sắc nét và bền màu. 2. Tiêu Chuẩn May "Clean Finish" May cuốn (Felled Seam): Loại bỏ hoàn toàn đường vắt sổ ở sườn và nách, thay thế bằng đường may cuốn móc xích 2 kim. Không cọ xát: Mép vải được cuộn kín vào trong với cữ chuẩn 8mm, tạo mặt trái sạch sẽ và êm ái tuyệt đối cho làn da. Đường may tinh tế: Mật độ chỉ cao 4.5 mũi/cm giúp đường may chắc chắn, hạn chế nhăn (puckering) trên nền vải mỏng. 3. Chỉn Chu &amp; Thông Minh Đứng form (Structure): Cổ áo và nẹp tay được ép keo vải KV110 và gia cố keo lụa UD9975, đảm bảo độ đứng dáng và không bị rộp sau khi giặt. Rập Sa vạt (Drop Tail): Lai sau dài hơn và lượn cong giúp áo không bị tuột khỏi thắt lưng khi vận động (vươn vai, gập người). Túi đa năng: Tích hợp khe cắm bút (pen slot) với dây viền ẩn bên trong túi ngực. TỔNG KẾT Seventy Seven 064 là sự cân bằng hoàn hảo giữa trọng lượng siêu nhẹ (105gsm) và kỹ thuật may đo cao cấp. Sản phẩm mang lại giải pháp thoải mái, loại bỏ cọ xát nhờ đường may cuốn sạch (Clean Finish) mà vẫn giữ được vẻ ngoài lịch lãm, đứng dáng. THÔNG TIN NHANH Chất liệu: AirDry™ Polyester Plus Plain 105gsm, 100% Polyester (Microfiber) Chi tiết: Phom Regular Fit, Túi ngực có khe bút, Lai Baby hem 5mm. Lưu ý giặt ủi: Giặt máy chế độ nhẹ, lộn trái sản phẩm. Ủi nhiệt độ thấp (110°C - 120°C), ủi mặt trái hoặc dùng khăn lót, không ủi trực tiếp lên hình in. Tránh phơi dưới nắng gắt.', 'YAME', 193050, 297000, true, 35.0, 2173, 440, 3.9, 54, 'active', false, true, false, 'Áo Sơ Mi Tay Dài Hoạ Tiết AirDry™ Nhẹ Mịn Nét Seventy Seven 064 Màu Hồng Dáng Vừa Vặn F3', 'Áo Sơ Mi Tay Dài Seventy Seven 064 1. Công Nghệ Vật Liệu Siêu Nhẹ &amp; Mềm Mượt Định lượng 105gsm: Sử dụng chất liệu AirDry™ Polyester Plus siêu nhẹ, giảm tải áp lực lên cơ thể, mang lại cảm giác "mặc như không mặc". Cấu trúc Microfiber: Sợi siêu vi (48s x 150D) tạo bề mặt phẳng mịn, êm ái với da v', '010426-sale, 010426-sale-quanao35, F3 - Regular Fit (Dáng Tiêu Chuẩn), màu hồng, Quần áo', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
