INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_9d35de29c7c248af', 'cat_shirt_long', 'Áo Sơ Mi Tay Dài AirDry™ Cổ Phối Màu Siêu Mềm Mượt Seventy Seven 061 Màu Tím Nhạt Dáng Vừa Vặn F3', 'ao-so-mi-tay-dai-airdry-co-phoi-mau-sieu-mem-muot-seventy-seven-061-mau-tim-nhat-dang-vua-van-f3', '0024581', 'ID sản phẩm: Seventy Seven 061 Áo sơ mi tay dài họa tiết, mềm mịn, ít nhăn, siêu nhẹ. 1. Kiểu sản phẩm: Áo sơ mi dài tay họa tiết 2. Ưu điểm: Chiếc sơ mi này dệt từ sợi Microfiber siêu mịn, cho bề mặt vải mềm mại, mượt mà đầy bất ngờ, vượt trội so với Polyester thông thường. Áo ít nhăn, không co rút', 'ID sản phẩm: Seventy Seven 061 Áo sơ mi tay dài họa tiết, mềm mịn, ít nhăn, siêu nhẹ. 1. Kiểu sản phẩm: Áo sơ mi dài tay họa tiết 2. Ưu điểm: Chiếc sơ mi này dệt từ sợi Microfiber siêu mịn, cho bề mặt vải mềm mại, mượt mà đầy bất ngờ, vượt trội so với Polyester thông thường. Áo ít nhăn, không co rút, lại nhẹ và nhanh khô, giúp bạn luôn phẳng phiu, lịch lãm và bền đẹp theo thời gian. Đặc biệt, túi có chi tiết cài bút tinh tế là điểm nhấn thông minh, hỗ trợ bạn linh hoạt và tiện lợi trong mọi công việc. 3. Chất liệu: Printed woven fabric, 100% Polyester 4. Kỹ thuật: Kéo sợi Microfiber tạo bề mặt vải siêu mịn, mang lại cảm giác dễ chịu như Cotton. Công nghệ Pigment Printing: cho họa tiết tươi sáng, sắc nét, bám đều bề mặt, không lo lem nhòe hay phai bạc sau nhiều lần giặt . 5. Phù hợp với: Dân văn phòng: Lý tưởng cho môi trường làm việc trong nhà, mát mẻ, giúp người mặc luôn lịch sự và thoải mái. Người bận rộn: Đặc tính ít nhăn, nhanh khô, dễ chăm sóc giúp tiết kiệm thời gian chuẩn bị. 6. Phong cách: Smart-Casual linh hoạt gọn gàng, lịch sự, hiện đại, và tinh tế. Phù hợp cho cả trang phục công sở và các buổi gặp mặt thân mật. 7. Tìm kiếm sản phẩm: Áo sơ mi nam Polyester, Áo sơ mi Microfiber, Áo sơ mi công sở nam, Áo sơ mi ít nhăn, Áo sơ mi họa tiết nam, Áo sơ mi in Pigment, Áo sơ mi tay dài.', 'YAME', 193050, 297000, true, 35.0, 775, 187, 4.9, 93, 'active', false, true, false, 'Áo Sơ Mi Tay Dài AirDry™ Cổ Phối Màu Siêu Mềm Mượt Seventy Seven 061 Màu Tím Nhạt Dáng Vừa Vặn F3', 'ID sản phẩm: Seventy Seven 061 Áo sơ mi tay dài họa tiết, mềm mịn, ít nhăn, siêu nhẹ. 1. Kiểu sản phẩm: Áo sơ mi dài tay họa tiết 2. Ưu điểm: Chiếc sơ mi này dệt từ sợi Microfiber siêu mịn, cho bề mặt vải mềm mại, mượt mà đầy bất ngờ, vượt trội so với Polyester thông thường. Áo ít nhăn, không co rút', '010426-sale, 010426-sale-quanao35, F3 - Regular Fit (Dáng Tiêu Chuẩn), GIÁ THẬT TỐT, Gu đơn giản, màu tím, Quần áo, Thời Trang Đơn Giản, Áo, Áo sơ mi', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
