INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_37e8f6ea0e104289', 'cat_shirt_long', 'Áo Sơ Mi Tay Dài Vải Ngải Cứu StayFresh™ Chạm Mát Lạnh, Ngăn Mùi Hôi The CEO 002 Màu Nâu Dáng Ôm Vừa F2', 'ao-so-mi-tay-dai-vai-ngai-cuu-stayfresh-cham-mat-lanh-ngan-mui-hoi-the-ceo-002-mau-nau-dang-om-vua-f2', '0022995', 'Áo Sơ Mi Tay Dài The CEO 002 1. Công nghệ vải StayFresh™: Kháng khuẩn &amp; Làm dịu da Sản phẩm tiên phong ứng dụng dòng vải StayFresh™ Mugwort Ultra Twill (163gsm). Sợi Rayon Ngải Cứu (Mugwort): Tích hợp chiết xuất ngải cứu vào lõi sợi giúp kháng khuẩn, khử mùi tự nhiên và hỗ trợ xua đuổi côn trùng', 'Áo Sơ Mi Tay Dài The CEO 002 1. Công nghệ vải StayFresh™: Kháng khuẩn &amp; Làm dịu da Sản phẩm tiên phong ứng dụng dòng vải StayFresh™ Mugwort Ultra Twill (163gsm). Sợi Rayon Ngải Cứu (Mugwort): Tích hợp chiết xuất ngải cứu vào lõi sợi giúp kháng khuẩn, khử mùi tự nhiên và hỗ trợ xua đuổi côn trùng. Trải nghiệm xúc giác: Bề mặt vải mềm mát, có tính năng "Soothing" giúp làm dịu da, giảm kích ứng khi mặc lâu. Cấu trúc dệt Twill: Kiểu dệt vân chéo tạo độ đầm, ít nhăn và giữ form ổn định suốt ngày dài. 2. Kỹ thuật may đo &amp; Kết cấu bền bỉ Phom dáng: Regular Fit với kết cấu Suông thẳng (Straight Cut), che khuyết điểm nhưng không thùng thình. Độ bền vượt trội: Mật độ chỉ may dày đặc 4.5 mũi/cm (High TPI) giúp đường may kín khít. Gia cố vận động: Sườn áo may móc xích (Chainstitch) co giãn theo cử động cơ thể; Cầu vai may đúp (Double Yoke) tăng khả năng chịu lực. 3. Chi tiết hoàn thiện tinh tế Non-Iron khu trú: Cổ và nẹp tay được ép keo định hình, đảm bảo phẳng lỳ và không bị rộp. Tiện ích ẩn: Tích hợp dây treo áo ẩn sau gáy và măng sét xếp ly tạo cử động thoải mái cho cổ tay. Thẩm mỹ: Lai áo may cuốn nhỏ 5mm, tạo vẻ ngoài hiện đại và gọn gàng. TỔNG KẾT The CEO 002 là khoản đầu tư xứng đáng cho sức khỏe làn da nhờ công nghệ sợi Ngải cứu kháng khuẩn, kết hợp cùng kỹ thuật may đo chuẩn xác. Sản phẩm cân bằng hoàn hảo giữa công năng bảo vệ và diện mạo chỉn chu cho môi trường công sở. THÔNG TIN NHANH Chất liệu: StayFresh™ Mugwort Ultra Twill 163gsm, 58% Polyester 39% Rayon (Mugwort) 3% Spandex Chi tiết sản phẩm: Regular Fit Lưu ý giặt/ủi: Giặt nước lạnh hoặc ấm nhẹ (&lt; 40°C). Không dùng chất tẩy chứa Clo. Ủi nhiệt độ thấp (110–120°C), nên ủi mặt trái. Tránh phơi dưới nắng gắt trực tiếp.', 'YAME', 405650, 427000, true, 5.0, 1086, 181, 4.1, 28, 'active', false, true, true, 'Áo Sơ Mi Tay Dài Vải Ngải Cứu StayFresh™ Chạm Mát Lạnh, Ngăn Mùi Hôi The CEO 002 Màu Nâu Dáng Ôm Vừa F2', 'Áo Sơ Mi Tay Dài The CEO 002 1. Công nghệ vải StayFresh™: Kháng khuẩn &amp; Làm dịu da Sản phẩm tiên phong ứng dụng dòng vải StayFresh™ Mugwort Ultra Twill (163gsm). Sợi Rayon Ngải Cứu (Mugwort): Tích hợp chiết xuất ngải cứu vào lõi sợi giúp kháng khuẩn, khử mùi tự nhiên và hỗ trợ xua đuổi côn trùng', '130426-sale-5, Công Nghệ, F2 - Slim Fit (Dáng Ôm Vừa), Gu đơn giản, màu nâu, Quần áo, signature0226, signature0426, Thời Trang Công Nghệ, Áo', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
