INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_a9eedc0bac104858', 'cat_shirt_long', 'Áo Sơ Mi Tay Dài StayFresh™ Kháng Khuẩn Vải Bamboo The CEO 005 Màu Đen Dáng Ôm Vừa F2', 'ao-so-mi-tay-dai-stayfresh-khang-khuan-vai-bamboo-the-ceo-005-mau-den-dang-om-vua-f2', '0022473', 'ID sản phẩm: The CEO 005 Áo sơ mi vừa vừa vải thân thiện môi trường, co giãn, kháng khuẩn, ít nhăn dễ keo. 1. Kiểu sản phẩm: Áo sơ mi nam tay dài cổ bẻ 2. Ưu điểm: -Chất vải Bamboo: Vải Bamboo thân thiện với môi trường, có độ giãn tốt, kháng khuẩn. -Thách thức bàn là: Công nghệ Wrinkle Free giúp áo ', 'ID sản phẩm: The CEO 005 Áo sơ mi vừa vừa vải thân thiện môi trường, co giãn, kháng khuẩn, ít nhăn dễ keo. 1. Kiểu sản phẩm: Áo sơ mi nam tay dài cổ bẻ 2. Ưu điểm: -Chất vải Bamboo: Vải Bamboo thân thiện với môi trường, có độ giãn tốt, kháng khuẩn. -Thách thức bàn là: Công nghệ Wrinkle Free giúp áo ít nhăn, dễ tiết kiệm, tiết kiệm thời gian chăm sóc. -Tinh tế trong từng chi tiết: Đường may đột chỉ tinh tế, kết hợp với nút kim loại chắc chắn, mang lại vẻ ngoài sang trọng. 3. Chất liệu: Vải sợi có nguồn gốc từ tre Tre (48,5% Tre 48,5% Polyester 3% Spandex) 4. Kỹ thuật: Tinh tế giúp tạo nên những đường bóng tinh tế, tăng tính thẩm mỹ cho sản phẩm. Loại nút áo kim: Thay vì nút nhựa thông thường, việc sử dụng nút kim loại giúp tăng thêm độ sang trọng và bền bỉ cho chiếc áo. 5. Phù hợp với ai: Nam giới văn phòng nhấn mạnh chuyên nghiệp, phòng trưng bày. Những người quan tâm đến sức khỏe và môi trường. Doanh nhân hoặc những người bận rộn không muốn đắt quá nhiều thời gian cho việc chăm sóc quần áo. 6. Thuộc Bộ Kỹ thuật Tập nào: WRINKLE FREE thuộc phân nhánh NON chất liệu vải ít nhăn mang đến sự thoải mái và tiện lợi 7. Các tên thường gọi hoặc tìm kiếm về sản phẩm này: Áo sơ mi nam vải sợi Tre, Sơ mi nam công sở ,Áo sơ mi nam chống nhăn, Áo sơ mi trắng basic,Áo sơ mi nam thân thiện môi trường,Áo sơ mi nam tay dài Áo sơ mi nam công sở , sơ mi tay dài đi làm Áo sơ mi trơn,Áo sơ mi đi học, Áo sơ mi đi tiệc, Áo sơ mi dự sự kiện.', 'YAME', 362950, 427000, true, 15.0, 3779, 145, 4.7, 181, 'active', false, true, false, 'Áo Sơ Mi Tay Dài StayFresh™ Kháng Khuẩn Vải Bamboo The CEO 005 Màu Đen Dáng Ôm Vừa F2', 'ID sản phẩm: The CEO 005 Áo sơ mi vừa vừa vải thân thiện môi trường, co giãn, kháng khuẩn, ít nhăn dễ keo. 1. Kiểu sản phẩm: Áo sơ mi nam tay dài cổ bẻ 2. Ưu điểm: -Chất vải Bamboo: Vải Bamboo thân thiện với môi trường, có độ giãn tốt, kháng khuẩn. -Thách thức bàn là: Công nghệ Wrinkle Free giúp áo ', '010426-sale, 010426-sale-quanao15, Công Nghệ, F2 - Slim Fit (Dáng Ôm Vừa), Gu đơn giản, màu đen, Quần áo, Thời Trang Công Nghệ, Áo, Áo sơ mi', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
