INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_7a8b421844ee4a0c', 'cat_shirt_long', 'Áo Sơ Mi Tay Dài Vải Hoa Hồng CloudTouch™ Mềm Mịn Điều Hòa Nhiệt The CEO 004 Màu Trắng Dáng Ôm Vừa F2', 'ao-so-mi-tay-dai-vai-hoa-hong-cloudtouch-mem-min-dieu-hoa-nhiet-the-ceo-004-mau-trang-dang-om-vua-f2', '0022554', 'Áo Sơ Mi Tay Dài CloudTouch™ The CEO 004 1. Chất liệu vải Sợi Hoa Hồng CloudTouch™ Thành phần sinh học: Chiết xuất từ bột cánh hoa hồng tự nhiên, mang lại bề mặt vải mướt mịn như lụa, an toàn tuyệt đối cho làn da nhạy cảm. Điều hòa thân nhiệt: Khả năng thoát nhiệt nhanh, tạo cảm giác "mát lạnh" tức ', 'Áo Sơ Mi Tay Dài CloudTouch™ The CEO 004 1. Chất liệu vải Sợi Hoa Hồng CloudTouch™ Thành phần sinh học: Chiết xuất từ bột cánh hoa hồng tự nhiên, mang lại bề mặt vải mướt mịn như lụa, an toàn tuyệt đối cho làn da nhạy cảm. Điều hòa thân nhiệt: Khả năng thoát nhiệt nhanh, tạo cảm giác "mát lạnh" tức thì khi tiếp xúc, giúp cơ thể luôn thông thoáng suốt ngày dài. Độ bền phom dáng: Cấu trúc dệt Twill dày dặn kết hợp sợi Polyester cao cấp giúp áo đanh chắc, hạn chế co rút và giữ phom thẳng sau nhiều lần giặt. 2. Phom Slim Fit &amp; Cấu trúc chữ V Triệt tiêu vải thừa: Rập được tinh chỉnh giảm thông số tại ngực, vai và nách, loại bỏ hoàn toàn tình trạng lùng bùng vùng bụng khi sơ vin. Cử động linh hoạt: Bổ sung 3% sợi Spandex co giãn nhẹ, giúp bạn thoải mái vận động, lái xe hay làm việc cường độ cao mà không bị gò bó. Định hình vai phẳng: Thiết kế đô sau hai lớp (Double Yoke) đóng vai trò như bộ khung cố định, giữ vùng vai luôn phẳng phiu và sắc nét. 3. Công nghệ may &amp; Hoàn thiện cao cấp Đường may "cuộn sạch": Toàn bộ biên vải thừa được giấu kín vào bên trong, triệt tiêu cảm giác châm chích, ngứa ngáy do ma sát. Cổ áo sắc sảo: Sử dụng keo vải chuyên dụng ép định hình, giúp lá cổ và măng sét luôn đứng dáng chuyên nghiệp, không bị rũ hay vặn vẹo. Chống nhăn tự nhiên: Công nghệ xử lý bề mặt giúp sợi vải có khả năng tự phục hồi nếp phẳng, tiết kiệm tối đa thời gian là ủi cho quý ông bận rộn. Mũi chỉ cổ áo cao cấp: Những mũi chỉ mô phỏng khâu tay giúp cổ áo trông cứng cáp, sang trọng và khẳng định gu thẩm mỹ tinh tế của người mặc. TỔNG KẾT The CEO 004 là sự giao thoa hoàn hảo giữa vải hoa hồng sinh học mát lạnh và phom dáng Slim Fit sắc sảo, mang lại diện mạo chỉn chu tuyệt đối cho quý ông công sở. THÔNG TIN NHANH Chất liệu: CloudTouch™ Rose Blend Plus Twill 150gsm, 55% Viscose (From Rose) 42% Polyester 3% Spandex. Chi tiết: F2 - Slim Fit (Dáng Ôm Vừa), cổ mô phỏng khâu tay, nẹp ½ nút Lưu ý giặt ủi: Giặt máy chế độ nhẹ, nước lạnh; không sấy nóng; giũ phẳng trước khi phơi để', 'YAME', 422450, 497000, true, 15.0, 1391, 94, 3.8, 97, 'active', true, true, false, 'Áo Sơ Mi Tay Dài Vải Hoa Hồng CloudTouch™ Mềm Mịn Điều Hòa Nhiệt The CEO 004 Màu Trắng Dáng Ôm Vừa F2', 'Áo Sơ Mi Tay Dài CloudTouch™ The CEO 004 1. Chất liệu vải Sợi Hoa Hồng CloudTouch™ Thành phần sinh học: Chiết xuất từ bột cánh hoa hồng tự nhiên, mang lại bề mặt vải mướt mịn như lụa, an toàn tuyệt đối cho làn da nhạy cảm. Điều hòa thân nhiệt: Khả năng thoát nhiệt nhanh, tạo cảm giác "mát lạnh" tức ', '010426-sale, 010426-sale-quanao15, Công Nghệ, F2 - Slim Fit (Dáng Ôm Vừa), Gu đơn giản, màu trắng, Quần áo, signature, Thời Trang Công Nghệ, Áo', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_0da63086d17042aa', 'cat_shirt_long', 'Áo Sơ Mi Tay Dài Vải Hoa Hồng CloudTouch™ Mềm Thoáng Mịn The CEO 003 Màu Trắng Dáng Vừa Vặn F3', 'ao-so-mi-tay-dai-vai-hoa-hong-cloudtouch-mem-thoang-min-the-ceo-003-mau-trang-dang-vua-van-f3', '0022555', 'Áo Sơ Mi Tay Dài CloudTouch™ The CEO 003 1. CloudTouch™ Rose: Sợi vải điều hòa thân nhiệt Sử dụng công nghệ CloudTouch™ với 55% sợi Viscose chiết xuất từ cánh hoa hồng. Vải có khả năng điều hòa thân nhiệt tự nhiên, mang lại cảm giác mát lạnh và mướt mịn ngay khi chạm da. 2. Khung vai đúp đôi: Giữ áo', 'Áo Sơ Mi Tay Dài CloudTouch™ The CEO 003 1. CloudTouch™ Rose: Sợi vải điều hòa thân nhiệt Sử dụng công nghệ CloudTouch™ với 55% sợi Viscose chiết xuất từ cánh hoa hồng. Vải có khả năng điều hòa thân nhiệt tự nhiên, mang lại cảm giác mát lạnh và mướt mịn ngay khi chạm da. 2. Khung vai đúp đôi: Giữ áo luôn thẳng phẳng như mới Cấu trúc đô sau đúp đôi giúp tăng cường khả năng chịu lực, giữ sống lưng áo luôn thẳng phẳng và triệt tiêu tình trạng xệ vai hay mất phom sau nhiều lần giặt. 3. Phom dáng Regular Fit: Gọn gàng &amp; Linh hoạt Bản rập được tính toán độ cử động cân bằng (Balanced Ease), giúp loại bỏ hoàn toàn hiện tượng vải lùng bùng dư thừa ở nách nhưng vẫn đảm bảo sự linh hoạt tuyệt đối khi bạn lái xe hay cử động mạnh. 4. Hoàn thiện êm ái: Mặt trong phẳng mịn, nâng niu làn da Ứng dụng kỹ thuật may cuốn sườn triệt tiêu mép vải thừa: giúp mặt trong phẳng nhẵn như mặt ngoài, loại bỏ tình trạng ngứa ngáy hay kích ứng da. Chi tiết Sartorial cao cấp: Nẹp giấu nút tạo vẻ tối giản chuyên nghiệp, lai bầu giúp sơ vin gọn gàng, không cộm vải. TỔNG KẾT Sự kết hợp đột phá giữa sợi hoa hồng tự nhiên và kỹ thuật may đo bền vững, mang lại diện mạo phẳng phiu và cảm giác mặc nhẹ nhõm suốt ngày dài. THÔNG TIN NHANH Chất liệu: CloudTouch™ Rose Blend Plus Plain 130gsm, 55% Viscose (From Rose) 42% Polyester 3% Spandex. Chi tiết sản phẩm: F3 - Regular Fit (Dáng Tiêu Chuẩn), đô sau may đôi chịu lực, nẹp giấu nút, lai bầu. Lưu ý: Giặt máy chế độ nhẹ, không sấy nóng để bảo vệ sợi co giãn, nên phơi bóng râm.', 'YAME', 323050, 497000, true, 35.0, 3214, 114, 4.4, 86, 'active', false, true, true, 'Áo Sơ Mi Tay Dài Vải Hoa Hồng CloudTouch™ Mềm Thoáng Mịn The CEO 003 Màu Trắng Dáng Vừa Vặn F3', 'Áo Sơ Mi Tay Dài CloudTouch™ The CEO 003 1. CloudTouch™ Rose: Sợi vải điều hòa thân nhiệt Sử dụng công nghệ CloudTouch™ với 55% sợi Viscose chiết xuất từ cánh hoa hồng. Vải có khả năng điều hòa thân nhiệt tự nhiên, mang lại cảm giác mát lạnh và mướt mịn ngay khi chạm da. 2. Khung vai đúp đôi: Giữ áo', '010426-sale, 010426-sale-quanao35, Công Nghệ, F3 - Regular Fit (Dáng Tiêu Chuẩn), Gu đơn giản, màu trắng, Quần áo, Thời Trang Công Nghệ, Áo, Áo sơ mi', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_4e0972c8ca3b4aa3', 'cat_shirt_long', 'Áo Sơ Mi Tay Dài Vải Ngải Cứu StayFresh™ Chạm Mát Lạnh, Ngăn Mùi Hôi The CEO 002 Màu Xanh Dương Đậm Dáng Ôm Vừa F2', 'ao-so-mi-tay-dai-vai-ngai-cuu-stayfresh-cham-mat-lanh-ngan-mui-hoi-the-ceo-002-mau-xanh-duong-dam-dang-om-vua-f2', '0022997', 'Áo Sơ Mi Tay Dài The CEO 002 1. Công nghệ vải StayFresh™: Kháng khuẩn &amp; Làm dịu da Sản phẩm tiên phong ứng dụng dòng vải StayFresh™ Mugwort Ultra Twill (163gsm). Sợi Rayon Ngải Cứu (Mugwort): Tích hợp chiết xuất ngải cứu vào lõi sợi giúp kháng khuẩn, khử mùi tự nhiên và hỗ trợ xua đuổi côn trùng', 'Áo Sơ Mi Tay Dài The CEO 002 1. Công nghệ vải StayFresh™: Kháng khuẩn &amp; Làm dịu da Sản phẩm tiên phong ứng dụng dòng vải StayFresh™ Mugwort Ultra Twill (163gsm). Sợi Rayon Ngải Cứu (Mugwort): Tích hợp chiết xuất ngải cứu vào lõi sợi giúp kháng khuẩn, khử mùi tự nhiên và hỗ trợ xua đuổi côn trùng. Trải nghiệm xúc giác: Bề mặt vải mềm mát, có tính năng "Soothing" giúp làm dịu da, giảm kích ứng khi mặc lâu. Cấu trúc dệt Twill: Kiểu dệt vân chéo tạo độ đầm, ít nhăn và giữ form ổn định suốt ngày dài. 2. Kỹ thuật may đo &amp; Kết cấu bền bỉ Phom dáng: Regular Fit với kết cấu Suông thẳng (Straight Cut), che khuyết điểm nhưng không thùng thình. Độ bền vượt trội: Mật độ chỉ may dày đặc 4.5 mũi/cm (High TPI) giúp đường may kín khít. Gia cố vận động: Sườn áo may móc xích (Chainstitch) co giãn theo cử động cơ thể; Cầu vai may đúp (Double Yoke) tăng khả năng chịu lực. 3. Chi tiết hoàn thiện tinh tế Non-Iron khu trú: Cổ và nẹp tay được ép keo định hình, đảm bảo phẳng lỳ và không bị rộp. Tiện ích ẩn: Tích hợp dây treo áo ẩn sau gáy và măng sét xếp ly tạo cử động thoải mái cho cổ tay. Thẩm mỹ: Lai áo may cuốn nhỏ 5mm, tạo vẻ ngoài hiện đại và gọn gàng. TỔNG KẾT The CEO 002 là khoản đầu tư xứng đáng cho sức khỏe làn da nhờ công nghệ sợi Ngải cứu kháng khuẩn, kết hợp cùng kỹ thuật may đo chuẩn xác. Sản phẩm cân bằng hoàn hảo giữa công năng bảo vệ và diện mạo chỉn chu cho môi trường công sở. THÔNG TIN NHANH Chất liệu: StayFresh™ Mugwort Ultra Twill 163gsm, 58% Polyester 39% Rayon (Mugwort) 3% Spandex Chi tiết sản phẩm: Regular Fit Lưu ý giặt/ủi: Giặt nước lạnh hoặc ấm nhẹ (&lt; 40°C). Không dùng chất tẩy chứa Clo. Ủi nhiệt độ thấp (110–120°C), nên ủi mặt trái. Tránh phơi dưới nắng gắt trực tiếp.', 'YAME', 405650, 427000, true, 5.0, 4572, 187, 4.6, 37, 'active', false, true, false, 'Áo Sơ Mi Tay Dài Vải Ngải Cứu StayFresh™ Chạm Mát Lạnh, Ngăn Mùi Hôi The CEO 002 Màu Xanh Dương Đậm Dáng Ôm Vừa F2', 'Áo Sơ Mi Tay Dài The CEO 002 1. Công nghệ vải StayFresh™: Kháng khuẩn &amp; Làm dịu da Sản phẩm tiên phong ứng dụng dòng vải StayFresh™ Mugwort Ultra Twill (163gsm). Sợi Rayon Ngải Cứu (Mugwort): Tích hợp chiết xuất ngải cứu vào lõi sợi giúp kháng khuẩn, khử mùi tự nhiên và hỗ trợ xua đuổi côn trùng', '130426-sale-5, Công Nghệ, F2 - Slim Fit (Dáng Ôm Vừa), Gu đơn giản, màu xanh dương, Quần áo, signature, signature0226, signature0426, Thời Trang Công Nghệ', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
