INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_c1ec4d9a0a834949', 'cat_shirt_long', 'Áo Sơ Mi Tay Dài AirDry™ Siêu Nhẹ Non Branded 019 Màu Xám Nhạt Dáng Ôm Vừa F2', 'ao-so-mi-tay-dai-airdry-sieu-nhe-non-branded-019-mau-xam-nhat-dang-om-vua-f2', '0024014', 'Áo Sơ Mi Tay Dài AirDry™ Non Branded 019 1. Sự cân bằng từ chất liệu AirDry™ 120gsm Định lượng siêu nhẹ: Với trọng lượng chỉ 120gsm (Lightweight), áo giảm thiểu áp lực lên cơ thể, tối ưu cho thời tiết nóng ẩm. Cấu trúc ổn định: Sử dụng kiểu dệt Plain Weave (dệt trơn 1/1) giúp khóa chặt sợi vải, giữ ', 'Áo Sơ Mi Tay Dài AirDry™ Non Branded 019 1. Sự cân bằng từ chất liệu AirDry™ 120gsm Định lượng siêu nhẹ: Với trọng lượng chỉ 120gsm (Lightweight), áo giảm thiểu áp lực lên cơ thể, tối ưu cho thời tiết nóng ẩm. Cấu trúc ổn định: Sử dụng kiểu dệt Plain Weave (dệt trơn 1/1) giúp khóa chặt sợi vải, giữ bề mặt phẳng phiu và hạn chế xô lệch dù vải mỏng. Thoáng mát &amp; Mềm mịn: Kết hợp 88% Polyester (kỵ nước, đẩy hơi ẩm ra ngoài nhanh) và 12% Modal (mềm mướt, giảm độ thô ráp), giúp áo khô nhanh và không dính vào người khi vận động. 2. Kỹ thuật rập "Standard Fit" tinh chỉnh Gọn gàng: Thu gọn 2cm vòng ngực và lai áo, loại bỏ phần vải dư thừa (excess fabric) hai bên sườn, giúp áo vừa vặn khi sơ vin. Linh hoạt: Giảm 1cm vai và nâng nách nông hơn, giúp định hình khung vai vuông vức và tay áo cử động dễ dàng mà không kéo lệch thân áo. Cân đối: Chiều dài áo giảm 2cm, đảm bảo tỷ lệ đẹp dù mặc thả ngoài hay sơ vin. 3. Độ hoàn thiện: Tiêu chuẩn may kỹ thuật cao Đường may sắc sảo: Mật độ chỉ dày 4.5 mũi/cm (chỉ Cotton 40/2) giúp đường may mướt, chống hiện tượng nhăn đường may (puckering). Cấu trúc bền bỉ: Cổ áo và nẹp sử dụng keo vải KV110 ép nhiệt, giúp chi tiết đứng phom, sắc nét và không bị rộp (bubbling) sau khi giặt. Sạch sẽ: Đường sườn may cuốn 2 kim có lót keo tan 8mm, đảm bảo thẳng tắp và giấu kín mép vải mặt trong. Chi tiết tinh tế: Nẹp áo thiết kế bất đối xứng (3cm/2.5cm) tăng độ cứng cáp khi cài nút; cửa tay xếp ly tạo độ phồng tự nhiên. TỔNG KẾT Với Non Branded 019, khái niệm "Thoáng Nhẹ" được định nghĩa lại bằng chất liệu vải AirDry™. Sự kết hợp giữa khả năng thoát ẩm của 88% Polyester và độ mềm của 12% Modal giúp người mặc kiểm soát tốt nhiệt độ cơ thể. Đây không chỉ là một chiếc áo sơ mi, mà là một lớp "điều hòa" thụ động, đủ mỏng để thoáng nhưng đủ kỹ thuật để giữ phom dáng, phù hợp tuyệt đối cho môi trường nhiệt đới nóng ẩm. THÔNG TIN NHANH Chất liệu: AirDry™ Modal Plus Plain 120gsm, 88% Polyester 12% Modal. Chi tiết sản phẩm: Dáng Vừa, Tay dài, Nẹp liền. Lưu ý giặ', 'YAME', 167450, 197000, true, 15.0, 2205, 117, 4.5, 182, 'active', false, true, true, 'Áo Sơ Mi Tay Dài AirDry™ Siêu Nhẹ Non Branded 019 Màu Xám Nhạt Dáng Ôm Vừa F2', 'Áo Sơ Mi Tay Dài AirDry™ Non Branded 019 1. Sự cân bằng từ chất liệu AirDry™ 120gsm Định lượng siêu nhẹ: Với trọng lượng chỉ 120gsm (Lightweight), áo giảm thiểu áp lực lên cơ thể, tối ưu cho thời tiết nóng ẩm. Cấu trúc ổn định: Sử dụng kiểu dệt Plain Weave (dệt trơn 1/1) giúp khóa chặt sợi vải, giữ ', '010426-sale, 010426-sale-quanao15, F2 - Slim Fit (Dáng Ôm Vừa), GIÁ THẬT TỐT, Gu đơn giản, màu xám, Quần áo, Thời Trang Đơn Giản, Áo, Áo sơ mi', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
