INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_24b3d13d64b04d1a', 'cat_jacket', 'Áo Khoác Jean ColorLock™ Khóa Màu Đen Siêu Bền Tek Black Jean 003 Màu Đen Dáng Vừa Vặn F3', 'ao-khoac-jean-colorlock-khoa-mau-den-sieu-ben-tek-black-jean-003-mau-den-dang-vua-van-f3', '0024969', 'Áo Khoác Trucker ColorLock™ Tek Black Jean 003 1. Công nghệ vải ColorLock™ - Đen sâu bền bỉ Khóa màu từ lõi: Ứng dụng công nghệ nhuộm xơ Dope Dye, giúp sắc đen bám chặt từ trong sợi vải, không còn nỗi lo bạc màu hay trắng sờn ở các đường gân sau nhiều lần giặt. Mềm mịn vượt trội: Sự kết hợp giữa sợi', 'Áo Khoác Trucker ColorLock™ Tek Black Jean 003 1. Công nghệ vải ColorLock™ - Đen sâu bền bỉ Khóa màu từ lõi: Ứng dụng công nghệ nhuộm xơ Dope Dye, giúp sắc đen bám chặt từ trong sợi vải, không còn nỗi lo bạc màu hay trắng sờn ở các đường gân sau nhiều lần giặt. Mềm mịn vượt trội: Sự kết hợp giữa sợi Modal và Spandex tạo bề mặt êm ái, loại bỏ hoàn toàn sự thô cứng của Denim truyền thống. 2. Form dáng Boxy Cropped - Tôn dáng &amp; Linh hoạt Hiệu ứng kéo dài chân: Thiết kế dáng ngắn (Cropped) giúp tỉ lệ cơ thể trông cao ráo và năng động hơn. Mặc lớp (Layering) thoải mái: Phần nách hạ sâu và thân vuông giúp bạn dễ dàng kết hợp cùng áo thun dày hoặc Hoodie mà không gây cộm hay gò bó. Tùy chỉnh linh hoạt: Hai nấc cài bên sườn hỗ trợ thu gọn vạt áo theo sở thích cá nhân. 3. Độ bền công nghiệp - Tỉ mỉ từng đường kim Đường may móc xích: Tăng độ co giãn tự nhiên cho các mối nối ở sườn và nách, giúp bạn thoải mái vận động mạnh mà không lo bục chỉ. Bền bỉ từng chi tiết: Miệng túi và nẹp áo được gia cố thêm đường may, đảm bảo áo luôn bền đẹp, không hỏng form dù giặt máy hay sử dụng thường xuyên. TỔNG KẾT Tek Black Jean 003 là sự giao thoa hoàn hảo giữa kỹ thuật khóa màu và form dáng hiện đại, mang lại trải nghiệm mặc Denim mềm mại, bền bỉ và cực kỳ tôn dáng. THÔNG TIN NHANH Chất liệu: ColorLock™ Modal Blend Ultra Twill, 49% Modal 49% Polyester 2% Spandex Chi tiết: F3 - Regular Fit (Dáng Tiêu Chuẩn), đường may móc xích, khóa bọ gia cố, nấc cài cá lai điều chỉnh. Lưu ý giặt ủi Lộn trái khi giặt máy ở chế độ nhẹ, tránh chất tẩy mạnh và không sấy ở nhiệt độ cao để bảo vệ sợi vải sinh học.', 'YAME', 757150, 797000, true, 5.0, 3776, 307, 5.0, 163, 'active', false, true, false, 'Áo Khoác Jean ColorLock™ Khóa Màu Đen Siêu Bền Tek Black Jean 003 Màu Đen Dáng Vừa Vặn F3', 'Áo Khoác Trucker ColorLock™ Tek Black Jean 003 1. Công nghệ vải ColorLock™ - Đen sâu bền bỉ Khóa màu từ lõi: Ứng dụng công nghệ nhuộm xơ Dope Dye, giúp sắc đen bám chặt từ trong sợi vải, không còn nỗi lo bạc màu hay trắng sờn ở các đường gân sau nhiều lần giặt. Mềm mịn vượt trội: Sự kết hợp giữa sợi', '110426-sale-5, màu đen, Quần áo, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_5d350cf049a94cb0', 'cat_jacket', 'Áo Khoác Kaki DurableTex™ Vải Cotton Dày Dặn Chắn Gió Cản Bụi The Worker 011 Màu Xám Nhạt Dáng Vừa Vặn F3', 'ao-khoac-kaki-durabletex-vai-cotton-day-dan-chan-gio-can-bui-the-worker-011-mau-xam-nhat-dang-vua-van-f3', '0024837', 'Áo Khoác Kaki DurableTex™ The Worker 011 Chất liệu DurableTex™ 290gsm: Đanh chắc và Thoáng da Vật liệu 100% Cotton: Loại bỏ hoàn toàn sợi tổng hợp nilon, giúp nhiệt lượng cơ thể lưu thông tự nhiên, không gây cảm giác bết dính hay hầm bí khi mặc cả ngày dài. Kỹ thuật dệt Twill (Vân chéo): Tạo bề mặt ', 'Áo Khoác Kaki DurableTex™ The Worker 011 Chất liệu DurableTex™ 290gsm: Đanh chắc và Thoáng da Vật liệu 100% Cotton: Loại bỏ hoàn toàn sợi tổng hợp nilon, giúp nhiệt lượng cơ thể lưu thông tự nhiên, không gây cảm giác bết dính hay hầm bí khi mặc cả ngày dài. Kỹ thuật dệt Twill (Vân chéo): Tạo bề mặt đanh chắc, chịu được ma sát cao và hạn chế tối đa việc bị xé rách trong quá trình vận động mạnh. Cấu trúc rập Regular Fit &amp; Kỹ thuật rã Decoup: Giải phóng cử động Kỹ thuật rã Decoup: Thay vì chiết eo thông thường, thân trước được chia khối 3D giúp áo ôm nhẹ theo đường nét cơ thể một cách tự nhiên và nam tính. Tối ưu không gian: Hạ sâu vòng nách giúp triệt tiêu tình trạng kích nách khi vươn tay. Trọng lượng vải được tính toán dồn đều lên vai, không gây ghì cổ, giữ phom áo luôn phẳng phiu. Tiêu chuẩn may Heavy-Duty: Gia cố bền bỉ Chỉ may sợi lớn: Sử dụng chỉ Cotton cơ số lớn, chịu lực kéo cực tốt, chống đứt gãy đường diễu nổi. Chốt bọ Bartack: Gia cố chắc chắn tại miệng túi và trụ tay, triệt tiêu hoàn toàn nguy cơ bung tét hay xé rách vải. Ép keo Fusing: Lá cổ và nắp túi được ép lụa bên trong, giúp bề mặt luôn phẳng phiu, chống quăn mép sau nhiều lần giặt. Hệ thống túi chịu lực &amp; Tính ổn định phom dáng Túi chống giãn: Miệng túi sườn được xử lý nẹp gia cố ẩn bên trong như một bộ khung, giúp túi luôn nằm phẳng, không bị chảy xệ hay mất phom khi đựng vật dụng nặng (điện thoại, ví tiền). Vải không co giãn: Tận dụng đặc tính tự nhiên của Cotton định lượng cao để giữ cấu trúc khối hộp (Boxy) ổn định, không bị chảy xệ hay biến dạng sau thời gian dài sử dụng. TỔNG KẾT The Worker 011 là giải pháp kỹ thuật cho dòng áo khoác vải dày nhưng vẫn đảm bảo sự linh hoạt tuyệt đối. Với sự kết hợp giữa vải Kaki 290gsm bền bỉ và cấu trúc rập F3 giải phóng cử động, đây là sản phẩm dành cho những người cần sự bền bỉ thực dụng và diện mạo chỉn chu. THÔNG TIN NHANH Chất liệu: DurableTex™ Cotton Ultra Twill 290gsm, 100% Cotton Chi tiết sản phẩm: F3 - Regular Fit (Dáng Tiêu Chuẩn), Hệ thống 4', 'YAME', 757150, 797000, true, 5.0, 94, 183, 4.4, 29, 'active', false, true, false, 'Áo Khoác Kaki DurableTex™ Vải Cotton Dày Dặn Chắn Gió Cản Bụi The Worker 011 Màu Xám Nhạt Dáng Vừa Vặn F3', 'Áo Khoác Kaki DurableTex™ The Worker 011 Chất liệu DurableTex™ 290gsm: Đanh chắc và Thoáng da Vật liệu 100% Cotton: Loại bỏ hoàn toàn sợi tổng hợp nilon, giúp nhiệt lượng cơ thể lưu thông tự nhiên, không gây cảm giác bết dính hay hầm bí khi mặc cả ngày dài. Kỹ thuật dệt Twill (Vân chéo): Tạo bề mặt ', '130426-sale-5, moban-300126, màu xám, Quần áo, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
