INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_255702e4c13147d7', 'cat_jacket', 'Áo Khoác Parka AirDry™ Tay Xỏ Ngón Chống Tia UV UPF 50+ The Minimalist 001 Màu Xám Nhạt Dáng Ôm Vừa F2', 'ao-khoac-parka-airdry-tay-xo-ngon-chong-tia-uv-upf-50-the-minimalist-001-mau-xam-nhat-dang-om-vua-f2', '0024847', 'Áo Khoác Parka AirDry™ The Minimalist 001 1. Hệ thống thoát nhiệt từ vải AirDry™ "Ngàn cửa sổ" Cấu trúc vải Pindot: Bề mặt vải gồm hàng ngàn mắt dệt siêu nhỏ tạo mạng lưới thoát khí dày đặc, giúp hơi nóng từ cơ thể thoát ra ngoài ngay lập tức. Thoáng khí 2 chiều: Không còn cảm giác dính bết hay hầm ', 'Áo Khoác Parka AirDry™ The Minimalist 001 1. Hệ thống thoát nhiệt từ vải AirDry™ "Ngàn cửa sổ" Cấu trúc vải Pindot: Bề mặt vải gồm hàng ngàn mắt dệt siêu nhỏ tạo mạng lưới thoát khí dày đặc, giúp hơi nóng từ cơ thể thoát ra ngoài ngay lập tức. Thoáng khí 2 chiều: Không còn cảm giác dính bết hay hầm hập mồ hôi, luồng không khí luôn được lưu thông liên tục qua toàn bộ thân áo. Chống nắng Anti UV™: Đạt chỉ số UPF 50+, ngăn chặn tia cực tím hiệu quả dù kết cấu vải siêu nhẹ và thoáng. 2. Thiết kế "phòng thủ" toàn diện Tay áo bao phủ 100%: Dài tay cộng thêm 16cm tích hợp lỗ xỏ ngón cái, che kín mu bàn tay khi lái xe hay chạy bộ mà không cần bao tay rời. Nón cao thay khẩu trang: Thiết kế nón 3 mảnh ôm sát kết hợp cổ áo cao (High Neck), bảo vệ toàn bộ vùng cổ và mặt khỏi tia UV. Phom Slim Fit cản gió: Đường cắt lượn theo cơ thể giúp áo không bị phồng hay "bạt gió" khi di chuyển ở tốc độ cao. 3. Độ bền chuẩn hàng xuất khẩu Đường may khít chặt: Mật độ chỉ dày dặn ngăn hiện tượng "nhe" đường may và chặn tia UV xuyên thấu qua các khe hở ở đường nối. Gia cố lực tại điểm yếu: Miệng túi và khóa kéo được đóng bọ chắc chắn, thoải mái đựng đồ nặng mà không lo rách toạc hay bai dão. Khóa kéo tàng hình: Hệ thống túi khóa kéo ẩn đảm bảo sự tinh tế và bảo vệ đồ dùng cá nhân an toàn khỏi bụi bẩn. TỔNG KẾT The Minimalist 001 là sự lựa chọn hàng đầu cho những ai cần sự gọn nhẹ, đa năng và bền bỉ. Sản phẩm mang lại hiệu suất bảo vệ tối đa trong một thiết kế tối giản, phù hợp cho cả tập luyện thể thao và di chuyển hàng ngày. THÔNG TIN NHANH Chất liệu: AirDry™ Polyester Ultra Mesh 150gsm, 100% Polyester Chi tiết sản phẩm: F2 - Slim Fit (Dáng Ôm Vừa), tay áo xỏ ngón, cổ nón cao, túi khóa kéo giấu Lưu ý giặt ủi Lộn trái khi giặt, giặt máy chế độ nhẹ, không dùng thuốc tẩy, phơi trong bóng râm.', 'YAME', 472150, 497000, true, 5.0, 2053, 397, 4.3, 151, 'active', false, true, true, 'Áo Khoác Parka AirDry™ Tay Xỏ Ngón Chống Tia UV UPF 50+ The Minimalist 001 Màu Xám Nhạt Dáng Ôm Vừa F2', 'Áo Khoác Parka AirDry™ The Minimalist 001 1. Hệ thống thoát nhiệt từ vải AirDry™ "Ngàn cửa sổ" Cấu trúc vải Pindot: Bề mặt vải gồm hàng ngàn mắt dệt siêu nhỏ tạo mạng lưới thoát khí dày đặc, giúp hơi nóng từ cơ thể thoát ra ngoài ngay lập tức. Thoáng khí 2 chiều: Không còn cảm giác dính bết hay hầm ', '100426-sale-moban, 110426-sale-5, màu xám, Quần áo, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
