INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_1b5b03c63f624399', 'cat_jacket', 'Áo Khoác Parka Anti-UV™ Xỏ Ngón Bảo Vệ Mu Bàn Tay Chống Nắng UPF 50+ Non Branded 048 Màu Xám Dáng Ôm Vừa F2', 'ao-khoac-parka-anti-uv-xo-ngon-bao-ve-mu-ban-tay-chong-nang-upf-50-non-branded-048-mau-xam-dang-om-vua-f2', '0024915', 'Áo Khoác Parka Anti-UV™ Non Branded 048 1. Tấm khiên bảo vệ 2 lớp Mặt ngoài "Lì lợm": Hỗn hợp Cotton pha được xử lý bề mặt đanh chắc, chống xù lông, đạt chuẩn UPF 50+ ngăn tia cực tím tự nhiên mà không cần hóa chất. Mặt trong "Điều hòa": Lớp sợi tổng hợp dệt chéo (Diagonal) tạo các rãnh thoát khí th', 'Áo Khoác Parka Anti-UV™ Non Branded 048 1. Tấm khiên bảo vệ 2 lớp Mặt ngoài "Lì lợm": Hỗn hợp Cotton pha được xử lý bề mặt đanh chắc, chống xù lông, đạt chuẩn UPF 50+ ngăn tia cực tím tự nhiên mà không cần hóa chất. Mặt trong "Điều hòa": Lớp sợi tổng hợp dệt chéo (Diagonal) tạo các rãnh thoát khí thông minh, giúp mồ hôi bay hơi nhanh, loại bỏ cảm giác ướt dính lưng. 2. Phom dáng lướt gió Slim Fit: Cắt giảm lượng vải dư thừa ở ngực và eo, giúp áo ôm gọn cơ thể, giảm lực cản gió và không bị bay phần phật khi chạy xe máy tốc độ cao. Tay Raglan: Thiết kế tay liền vai không đường nối, giúp người mặc vươn tay lái xe hay đeo balo nặng mà không bị cấn hay bó rít dưới nách. 3. Tiện ích thay thế phụ kiện Tay xỏ ngón: Thiết kế ôm sát cổ tay, che phủ mu bàn tay thay thế găng tay rời. Được gia cố đóng bọ chắc chắn để chống rách. Nón trùm 3 mảnh: Cấu trúc ghép cầu giúp nón đứng form, ôm tròn đầu và đảm bảo không sụp xuống che khuất tầm nhìn khi tham gia giao thông. Túi khóa kéo ẩn: Ngăn khóa kéo ẩn nằm gọn trong túi sườn trái, an toàn tuyệt đối cho ví tiền, chìa khóa, thiết kế giúp chống rơi đồ hiệu quả. 4. Kết cấu bền bỉ Chống biến dạng: Sử dụng lớp keo lụa định hình ẩn bên trong nắp túi và vành nón, giúp áo luôn phẳng phiu, không bị dộp hay mất form sau nhiều lần giặt. Đường may chịu lực: Mật độ chỉ dày đặc kết hợp với sợi Spandex co giãn 6%, đảm bảo áo chịu được cường độ vận động cao mà không bung đứt. TỔNG KẾT Non Branded 048 không chỉ là áo khoác, đây là thiết bị bảo vệ (gear) chuyên dụng cho nhu cầu di chuyển tần suất cao dưới nắng gắt. Sản phẩm ưu tiên độ bền, khả năng che chắn toàn diện và sự gọn gàng, chỉn chu. THÔNG TIN NHANH Chất liệu: Anti-UV™ Polyester Blend Ultra Terry 310gsm, 74% Tici (Polyester/Cotton) 20% Polyester 6% Spandex Chi tiết sản phẩm: Phom Slim Fit, Tay xỏ ngón, Nón 3 mảnh, Tay Raglan Lưu ý giặt ủi: Giặt máy ở chế độ nhẹ (nước thường/lạnh), lộn trái sản phẩm. Không sử dụng thuốc tẩy. Phơi trong bóng mát, tránh ánh nắng trực tiếp để bền màu. Tuyệt đối kh', 'YAME', 472150, 497000, true, 5.0, 4813, 297, 4.0, 162, 'active', false, true, false, 'Áo Khoác Parka Anti-UV™ Xỏ Ngón Bảo Vệ Mu Bàn Tay Chống Nắng UPF 50+ Non Branded 048 Màu Xám Dáng Ôm Vừa F2', 'Áo Khoác Parka Anti-UV™ Non Branded 048 1. Tấm khiên bảo vệ 2 lớp Mặt ngoài "Lì lợm": Hỗn hợp Cotton pha được xử lý bề mặt đanh chắc, chống xù lông, đạt chuẩn UPF 50+ ngăn tia cực tím tự nhiên mà không cần hóa chất. Mặt trong "Điều hòa": Lớp sợi tổng hợp dệt chéo (Diagonal) tạo các rãnh thoát khí th', '110426-sale-5, màu xám, Quần áo, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
