INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_6c9e087cfdef4d8d', 'cat_jacket', 'Áo Khoác Kaki Bụi Bặm DurableTex™ Dày Dặn Mặc Bền Phối Màu Ở Cổ The Worker 001 Màu Xanh Dương Đậm Dáng Vừa Vặn F3', 'ao-khoac-kaki-bui-bam-durabletex-day-dan-mac-ben-phoi-mau-o-co-the-worker-001-mau-xanh-duong-dam-dang-vua-van-f3', '0024714', 'Áo Khoác Kaki The Worker 001 1. Phom Dáng Regular (Straight Cut) Tôn Dáng Sản phẩm sở hữu phom dáng Straight Cut (suông ngắn) thời thượng. Chiều dài áo và lai áo được cắt ngắn giúp "hack" dáng chân dài hơn. Đặc biệt, phần vai được thu hẹp 4cm và hạ nách sâu, loại bỏ độ trễ thừa thãi, tạo nên bờ vai ', 'Áo Khoác Kaki The Worker 001 1. Phom Dáng Regular (Straight Cut) Tôn Dáng Sản phẩm sở hữu phom dáng Straight Cut (suông ngắn) thời thượng. Chiều dài áo và lai áo được cắt ngắn giúp "hack" dáng chân dài hơn. Đặc biệt, phần vai được thu hẹp 4cm và hạ nách sâu, loại bỏ độ trễ thừa thãi, tạo nên bờ vai vuông vức, nam tính và dễ dàng vận động. 2. Chất Liệu DurableTex™ Siêu Bền Áo được may từ vải DurableTex™ Cotton Basic Twill định lượng 260gsm. Cấu trúc dệt vân chéo (Twill) mật độ cao tạo nên bề mặt đanh lì như một lớp "áo giáp" chống mài mòn vượt trội. Dù dày dặn, thành phần 100% Cotton vẫn đảm bảo sự thoáng mát và dễ chịu tuyệt đối. 3. Kỹ Thuật May &amp; Chi Tiết Đắt Giá May Kansai 3 kim: Các đường ráp nối sử dụng máy móc xích 3 kim tiêu chuẩn bảo hộ với chỉ Cotton 20/3 to bản, đảm bảo độ bền tối đa. Hệ thống 4 túi: Thiết kế 4 túi ốp (Patch Pockets) tiện lợi, được gia cố bằng đinh tán/bọ tại các góc chịu lực. Điểm nhấn cổ áo: Cổ bẻ phối chất liệu nhung tăm (corduroy) tương phản, mang lại vẻ đẹp cổ điển và sang trọng. TỔNG KẾT Sự cân bằng hoàn hảo giữa tính năng bảo vệ bền bỉ và thẩm mỹ thời trang. The Worker 001 là chiếc áo khoác lý tưởng, sẵn sàng đồng hành cùng bạn từ công việc đến những chuyến đi. THÔNG TIN NHANH Chất liệu: DurableTex™ Cotton Basic Twill 260gsm, 100% Cotton Chi tiết: Phom Regular (Straight Cut), Cổ phối nhung, Nút bấm kim loại Lưu ý giặt ủi: Lộn trái và cài nút/kéo khóa trước khi giặt. Giặt nước lạnh hoặc ấm nhẹ (&lt; 40°C), không dùng thuốc tẩy Clo. Ủi ở nhiệt độ trung bình - cao (160°C – 200°C), nên ủi mặt trái. Hạn chế chà xát mạnh cục bộ để tránh bạc màu (frosting).', 'YAME', 567150, 597000, true, 5.0, 3288, 393, 4.0, 127, 'active', false, true, false, 'Áo Khoác Kaki Bụi Bặm DurableTex™ Dày Dặn Mặc Bền Phối Màu Ở Cổ The Worker 001 Màu Xanh Dương Đậm Dáng Vừa Vặn F3', 'Áo Khoác Kaki The Worker 001 1. Phom Dáng Regular (Straight Cut) Tôn Dáng Sản phẩm sở hữu phom dáng Straight Cut (suông ngắn) thời thượng. Chiều dài áo và lai áo được cắt ngắn giúp "hack" dáng chân dài hơn. Đặc biệt, phần vai được thu hẹp 4cm và hạ nách sâu, loại bỏ độ trễ thừa thãi, tạo nên bờ vai ', '110426-sale-5, F3 - Regular Fit (Dáng Tiêu Chuẩn), màu nâu, Quần áo, signature, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
