INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_4d29cb4027264ef3', 'cat_jacket', 'Áo Khoác Kaki Nhung Dày Dặn Giữ Ấm Chống Nắng The No Style 190 Màu Nâu Đậm Dáng Rộng Rãi F4', 'ao-khoac-kaki-nhung-day-dan-giu-am-chong-nang-the-no-style-190-mau-nau-dam-dang-rong-rai-f4', '0023611', 'ID sản phẩm: The No Style 190 Áo Mùa Hè Harrington chống nắng ít nhăn, màu bền, thoáng mát. 1. Kiểu sản phẩm: Áo khoác không nón. 2. Ưu điểm: Ít nhăn, bền màu, giữ ấm và chống nắng tốt. Vải đứng form, bên trong có lớp lót polyester thoáng khí. 3. Chất liệu: 100% Polyester, (Corduroy). 4. Kỹ thuật: B', 'ID sản phẩm: The No Style 190 Áo Mùa Hè Harrington chống nắng ít nhăn, màu bền, thoáng mát. 1. Kiểu sản phẩm: Áo khoác không nón. 2. Ưu điểm: Ít nhăn, bền màu, giữ ấm và chống nắng tốt. Vải đứng form, bên trong có lớp lót polyester thoáng khí. 3. Chất liệu: 100% Polyester, (Corduroy). 4. Kỹ thuật: Bo lai và bo tay cotton dày dặn co giãn, dây kéo kim loại mạnh mẽ và bền chắc, họa tiết trên áo thêu 2D. 5. Phù hợp với: Mọi phong cách từ tối giản đến phá cách. 6. Thuộc Bộ Sưu Tập: No Style - gu nào cũng có, mặc đẹp, mặc độc, mặc đúng mốt. 7. Các tên thường gọi:Áo khoác bomber dáng rộng, áo khoác không nón, áo khoác thời trang nam.', 'YAME', 447750, 597000, true, 25.0, 3610, 367, 4.4, 54, 'active', false, true, false, 'Áo Khoác Kaki Nhung Dày Dặn Giữ Ấm Chống Nắng The No Style 190 Màu Nâu Đậm Dáng Rộng Rãi F4', 'ID sản phẩm: The No Style 190 Áo Mùa Hè Harrington chống nắng ít nhăn, màu bền, thoáng mát. 1. Kiểu sản phẩm: Áo khoác không nón. 2. Ưu điểm: Ít nhăn, bền màu, giữ ấm và chống nắng tốt. Vải đứng form, bên trong có lớp lót polyester thoáng khí. 3. Chất liệu: 100% Polyester, (Corduroy). 4. Kỹ thuật: B', '010426-sale, 010426-sale-quanao25, F4 - Loose Fit (Dáng Rộng), Gu thiết kế, màu xanh dương, Quần áo, signature, signature0226, Thời Trang Dịch Chuyển, Áo', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_f4ca45f12d284eec', 'cat_jacket', 'Áo Khoác Gile Vải Thoáng Khí Seventy Seven 006 Màu Nâu Nhạt Dáng Rộng Rãi F4', 'ao-khoac-gile-vai-thoang-khi-seventy-seven-006-mau-nau-nhat-dang-rong-rai-f4', '0023200', 'ID sản phẩm: Seventy Seven 006 Áo khoác Gile Waffe Basic rộng bền bỉ, thoáng khí, ít nhăn, màu sắc trung tính. 1. Kiểu sản phẩm: Áo khoác không nón. 2. Ưu điểm: Ít nhăn, bền màu. Dễ dàng phối hợp với nhiều loại trang phục khác nhau như áo thun, áo sơ mi,... Đây là một chất liệu vải khá đặc biệt so v', 'ID sản phẩm: Seventy Seven 006 Áo khoác Gile Waffe Basic rộng bền bỉ, thoáng khí, ít nhăn, màu sắc trung tính. 1. Kiểu sản phẩm: Áo khoác không nón. 2. Ưu điểm: Ít nhăn, bền màu. Dễ dàng phối hợp với nhiều loại trang phục khác nhau như áo thun, áo sơ mi,... Đây là một chất liệu vải khá đặc biệt so với những chất liệu khác vì cấu trúc gồ ghề và mô hình bề mặt giống như chiếc bánh waffle. Được dệt kim với sự sắp xếp theo trật tự của sợi, tạo ra những ô vuông hoặc ô vanh nhỏ trên bề mặt. Cấu trúc này tạo ra các khe hở nhẹ và không đồng đều, giúp vải có khả năng thoáng khí tốt. 3. Chất liệu: Vải Waffle 100% Polyester 4. Kỹ thuật: Họa tiết thêu 2D. 5. Phù hợp với ai: Áo gile thun trồng cổ thường có thiết kế không tay và cổ tròn hoặc cổ tim, mang lại vẻ ngoài năng động và trẻ trung. 6. Thuộc Bộ Sưu Tập: Seventy Seven, thời trang trung tính, dễ phối dễ lựa chọn. 7. Các tên thường gọi hoặc tìm kiếm về sản phẩm này: Áo khoác không nón, áo khoác nam, áo khoác nhẹ, áo khoác gile, áo khoác không tay.', 'YAME', 170250, 227000, true, 25.0, 2449, 166, 3.8, 168, 'active', false, true, false, 'Áo Khoác Gile Vải Thoáng Khí Seventy Seven 006 Màu Nâu Nhạt Dáng Rộng Rãi F4', 'ID sản phẩm: Seventy Seven 006 Áo khoác Gile Waffe Basic rộng bền bỉ, thoáng khí, ít nhăn, màu sắc trung tính. 1. Kiểu sản phẩm: Áo khoác không nón. 2. Ưu điểm: Ít nhăn, bền màu. Dễ dàng phối hợp với nhiều loại trang phục khác nhau như áo thun, áo sơ mi,... Đây là một chất liệu vải khá đặc biệt so v', '010426-sale, 010426-sale-quanao25, F4 - Loose Fit (Dáng Rộng), Gu đơn giản, màu nâu, Quần áo, Thời Trang Dịch Chuyển, Áo, Áo khoác, Áo khoác Seventy Seven', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
