INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_052c9747b4404009', 'cat_jacket', 'Áo Khoác Parka RainShield™ Trượt Nước Siêu Nhẹ Gấp Gọn 2 Kiểu Non Branded 046 Màu Đen Dáng Rộng Rãi F4', 'ao-khoac-parka-rainshield-truot-nuoc-sieu-nhe-gap-gon-2-kieu-non-branded-046-mau-den-dang-rong-rai-f4', '0024312', 'ID sản phẩm: Non Branded 046 Áo Sơ Mi Parka Siêu Cấp Gấp Gọn Thông Minh Non Branded 046 1. Kiểu sản phẩm: Áo Khoác Gió Parka 2. Ưu điểm nổi bật: Với chất liệu vải dù siêu nhẹ và khả năng trượt nước ưu việt, chiếc áo này mang đến sự thoải mái tối đa và bảo vệ bạn khỏi mưa nhỏ, sương mù. Đặc biệt, thi', 'ID sản phẩm: Non Branded 046 Áo Sơ Mi Parka Siêu Cấp Gấp Gọn Thông Minh Non Branded 046 1. Kiểu sản phẩm: Áo Khoác Gió Parka 2. Ưu điểm nổi bật: Với chất liệu vải dù siêu nhẹ và khả năng trượt nước ưu việt, chiếc áo này mang đến sự thoải mái tối đa và bảo vệ bạn khỏi mưa nhỏ, sương mù. Đặc biệt, thiết kế thông minh cho phép gấp gọn áo theo hai cách khác nhau, giúp bạn dễ dàng mang theo trong mọi hành trình. Thêm vào đó, màu sắc bền đẹp sẽ giữ cho chiếc áo luôn tươi mới và phong cách. 3. Chất liệu cao cấp: Vải Dù Ripstop, 100% Polyester 4. Kỹ thuật: May rã phối tạo form dáng không chỉ mang đến vẻ ngoài hiện đại năng động mà còn tăng cường độ bền cho áo. Nón áo được trang bị dây thun rút tiện lợi, cho phép bạn dễ dàng điều chỉnh độ ôm sát theo sở thích và điều kiện thời tiết. Thiết kế tay áo luồn thun giúp cố định tay áo, tạo sự gọn gàng và ngăn cản tác động của gió. Dây kéo "ton-sur-ton" chắc chắn, bền bỉ . 5. Phù hợp với: Các hoạt động ngoài trời (đi bộ, chạy bộ, đạp xe), di chuyển hàng ngày, du lịch, và sử dụng trong thời tiết se lạnh hoặc mưa nhẹ. 6. Phong cách: Tối giản hiện đại, Thể thao 7. Từ khóa tìm kiếm: Áo khoác gió mỏng nhẹ, áo khoác chống nước nhẹ, áo khoác thể thao, áo khoác du lịch, áo khoác nam nữ, áo khoác thời trang, áo khoác gấp gọn.', 'YAME', 212550, 327000, true, 35.0, 4300, 69, 4.7, 14, 'active', false, true, false, 'Áo Khoác Parka RainShield™ Trượt Nước Siêu Nhẹ Gấp Gọn 2 Kiểu Non Branded 046 Màu Đen Dáng Rộng Rãi F4', 'ID sản phẩm: Non Branded 046 Áo Sơ Mi Parka Siêu Cấp Gấp Gọn Thông Minh Non Branded 046 1. Kiểu sản phẩm: Áo Khoác Gió Parka 2. Ưu điểm nổi bật: Với chất liệu vải dù siêu nhẹ và khả năng trượt nước ưu việt, chiếc áo này mang đến sự thoải mái tối đa và bảo vệ bạn khỏi mưa nhỏ, sương mù. Đặc biệt, thi', '010426-sale, 010426-sale-quanao35, Công Nghệ, F4 - Loose Fit (Dáng Rộng), Gu thiết kế, màu đen, Non Branded, Quần áo, Thời Trang Dịch Chuyển, xuhuong220426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
