INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_b882bd15fe984066', 'cat_jeans', 'Quần Jeans CloudTouch™ Mịn Mượt Chiều Da Che Khuyết Điểm Chân The Original 058 Màu Xanh Dương Đậm Dáng Vừa Vặn F3', 'quan-jeans-cloudtouch-min-muot-chieu-da-che-khuyet-diem-chan-the-original-058-mau-xanh-duong-dam-dang-vua-van-f3', '0025064', 'Quần Jeans Regular Fit CloudTouch™ The Original 058 1. Chất liệu CloudTouch™ - Bước tiến của Denim hiện đại Công thức 4 loại sợi: Kết hợp Cotton, Polyester, Rayon và Spandex tạo nên bề mặt vải Mềm - Mịn - Mát vượt trội so với Jeans truyền thống. Xử lý Fine Twill: Kiểu dệt vân chéo siêu nhỏ giúp bề m', 'Quần Jeans Regular Fit CloudTouch™ The Original 058 1. Chất liệu CloudTouch™ - Bước tiến của Denim hiện đại Công thức 4 loại sợi: Kết hợp Cotton, Polyester, Rayon và Spandex tạo nên bề mặt vải Mềm - Mịn - Mát vượt trội so với Jeans truyền thống. Xử lý Fine Twill: Kiểu dệt vân chéo siêu nhỏ giúp bề mặt phẳng mịn, loại bỏ hoàn toàn cảm giác thô ráp hay ngứa ngáy khi ma sát với da. Định lượng 10oz: Độ dày tiêu chuẩn để quần đứng phom nhưng vẫn nhẹ nhàng, thoáng khí, phù hợp cho mọi hoạt động hàng ngày. 2. Phom dáng Regular Fit tôn dáng Ống đứng (Straight Leg): Thiết kế suông thẳng giúp che khuyết điểm chân, tạo hiệu ứng đôi chân thẳng và cân đối. Đáy vừa (Mid Rise): Vị trí cạp quần nằm tại hông, mang lại sự kín đáo và thoải mái, không gây tức bụng khi ngồi làm việc lâu. Độ chùng lai (Stacking): Chiều dài quần được tính toán để tạo độ nhăn tự nhiên trên giày, mang lại vẻ ngoài phóng khoáng, nam tính. 3. Kết cấu Heavy Duty - Bền bỉ theo thời gian Kỹ thuật móc xích kép: Đường may đáy và dọc sườn được gia cố chắc chắn, chịu lực căng cực tốt, ngăn chặn tình trạng bục chỉ khi vận động mạnh. Lưng quần ép Mex: Sử dụng lớp lót chuyên dụng giúp lưng quần luôn phẳng, không bị vặn xoắn hay dão sau nhiều lần giặt máy. TỔNG KẾT The Original 058 là sự kết hợp giữa diện mạo Denim cổ điển và cảm giác mặc êm ái của quần vải. Lựa chọn tối ưu cho nam giới cần sự chỉn chu văn phòng nhưng vẫn thoải mái vận động cả ngày. THÔNG TIN NHANH Chất liệu: CloudTouch™ Rayon Blend Plus Twill 10oz, 68% Cotton 21% Polyester 9% Rayon 2% Spandex Chi tiết sản phẩm: F3 - Regular Fit (Dáng Tiêu Chuẩn) Lưu ý giặt ủi: Lộn trái khi giặt và phơi, tránh ánh nắng gắt, giặt nước lạnh (&lt; 40°C) để bảo vệ sợi co giãn.', 'YAME', 472150, 497000, true, 5.0, 4434, 355, 4.1, 80, 'active', false, true, false, 'Quần Jeans CloudTouch™ Mịn Mượt Chiều Da Che Khuyết Điểm Chân The Original 058 Màu Xanh Dương Đậm Dáng Vừa Vặn F3', 'Quần Jeans Regular Fit CloudTouch™ The Original 058 1. Chất liệu CloudTouch™ - Bước tiến của Denim hiện đại Công thức 4 loại sợi: Kết hợp Cotton, Polyester, Rayon và Spandex tạo nên bề mặt vải Mềm - Mịn - Mát vượt trội so với Jeans truyền thống. Xử lý Fine Twill: Kiểu dệt vân chéo siêu nhỏ giúp bề m', '080426-sale-5, màu xanh dương, Quần áo, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_7936e6000dc84587', 'cat_jeans', 'Quần Đùi Jean FlexFit™ Đắp Hai Lớp Gối Dày Dặn Giữ Form Tốt The Original 042 Màu Xanh Dương Nhạt Dáng Rộng Rãi F4', 'quan-dui-jean-flexfit-dap-hai-lop-goi-day-dan-giu-form-tot-the-original-042-mau-xanh-duong-nhat-dang-rong-rai-f4', '0024678', 'Quần Jeans Short FlexFit™ The Original 042 1. Kỹ thuật Rập &amp; Phom dáng (Loose Fit 9 Inch/ Baggy) Giải phóng vận động: Thiết kế Long Rise với đáy trước nới +3cm, đáy sau +1cm tạo khoảng không lớn tại vùng hông đùi, loại bỏ tình trạng cấn đáy khi ngồi hoặc vận động mạnh. Tỉ lệ Boxy: Lai quần và ch', 'Quần Jeans Short FlexFit™ The Original 042 1. Kỹ thuật Rập &amp; Phom dáng (Loose Fit 9 Inch/ Baggy) Giải phóng vận động: Thiết kế Long Rise với đáy trước nới +3cm, đáy sau +1cm tạo khoảng không lớn tại vùng hông đùi, loại bỏ tình trạng cấn đáy khi ngồi hoặc vận động mạnh. Tỉ lệ Boxy: Lai quần và chiều dài đều tăng thêm +3cm, tạo hình khối vững chãi giúp che khuyết điểm chân cong hoặc đùi to hiệu quả. Kỹ thuật Waist Anchoring: Giữ nguyên thông số lưng giúp quần bám chắc vào eo hông, không bị xệ dù ống quần được mở rộng tối đa. 2. Chất liệu FlexFit™ 12oz (Denim thế hệ mới) Độ linh hoạt: Tích hợp 1% Spandex giúp vải có độ co giãn nhẹ theo nhịp bước, phá vỡ sự thô cứng của Denim truyền thống mà không làm bùng gối. Cấu trúc Hybrid Blend: Sự kết hợp giữa 73% Cotton và 26% Polyester tạo bộ khung vải bền bỉ, giữ màu tốt và hạn chế mài mòn tại các vùng ma sát cao. Hiệu ứng bề mặt: Kiểu dệt Twill (Vân chéo) tạo các đường gân nổi đặc trưng, giúp quần có độ đầm tay và đứng dáng. 3. Tiêu chuẩn may &amp; Độ bền Workwear Gia cố Double Knee: Thiết kế gối đôi diễu 2 kim giúp tăng gấp đôi độ bền tại vị trí tiếp xúc nhiều nhất. Chi tiết Utility: Hệ thống túi Carpenter và dây Hammer loop được kẹp chắc chắn vào sườn. Toàn bộ các điểm chịu lực được chốt chặn bằng máy đóng bọ (Bartack). Hoàn thiện cao cấp: Đường may 2 kim móc xích (6.4mm) tạo gân nổi mạnh mẽ. Khuy mắt phụng (Keyhole) giúp cài nút kim loại dễ dàng mà không làm biến dạng lỗ khuy. TỔNG KẾT The Original 042 là giải pháp hoàn hảo cho phom dáng Baggy hiện đại. Bằng việc kết hợp cấu trúc hạ đáy sâu giải phóng vận động và kỹ thuật may Workwear siêu bền, sản phẩm mang lại trải nghiệm mặc thoải mái tuyệt đối nhưng vẫn giữ được diện mạo cứng cáp, bền bỉ theo thời gian. THÔNG TIN NHANH Chất liệu: FlexFit™ Cotton Plus Twill 12oz (73% Cotton, 26% Polyester, 1% Spandex). Chi tiết sản phẩm: Phom Loose Fit 9 Inch, túi Carpenter, gối đôi (Double Knee), đóng bọ gia cố, khuy mắt phụng. Lưu ý giặt / ủi: Không sấy nóng để bảo vệ sợi Spandex; ', 'YAME', 377150, 397000, true, 5.0, 181, 233, 4.3, 109, 'active', false, true, false, 'Quần Đùi Jean FlexFit™ Đắp Hai Lớp Gối Dày Dặn Giữ Form Tốt The Original 042 Màu Xanh Dương Nhạt Dáng Rộng Rãi F4', 'Quần Jeans Short FlexFit™ The Original 042 1. Kỹ thuật Rập &amp; Phom dáng (Loose Fit 9 Inch/ Baggy) Giải phóng vận động: Thiết kế Long Rise với đáy trước nới +3cm, đáy sau +1cm tạo khoảng không lớn tại vùng hông đùi, loại bỏ tình trạng cấn đáy khi ngồi hoặc vận động mạnh. Tỉ lệ Boxy: Lai quần và ch', '110426-sale-5, màu xanh dương, Quần áo, signature, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
