INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_452c2365ab004f06', 'cat_jeans', 'Quần Jean FlexFit™ Đáy Quần May Chịu Lực Chắc Chắn Multi Color Jean 001 Màu Trắng Dáng Vừa Vặn F3', 'quan-jean-flexfit-day-quan-may-chiu-luc-chac-chan-multi-color-jean-001-mau-trang-dang-vua-van-f3', '0024878', 'Quần Jeans Regular Fit Multi Color Jean 001 1. Công Nghệ Chất Liệu: FlexFit™ 310gsm Trọng lượng 310gsm (Heavyweight): Tạo nền tảng vải dày dặn, đanh chắc, giúp quần lên form nam tính và mạnh mẽ. Bề mặt Smooth Touch: Kỹ thuật dệt Twill mật độ cao giúp các sợi xếp khít tuyệt đối, mang lại bề mặt phẳng', 'Quần Jeans Regular Fit Multi Color Jean 001 1. Công Nghệ Chất Liệu: FlexFit™ 310gsm Trọng lượng 310gsm (Heavyweight): Tạo nền tảng vải dày dặn, đanh chắc, giúp quần lên form nam tính và mạnh mẽ. Bề mặt Smooth Touch: Kỹ thuật dệt Twill mật độ cao giúp các sợi xếp khít tuyệt đối, mang lại bề mặt phẳng phiu, mịn màng, loại bỏ hoàn toàn cảm giác thô ráp thường thấy ở vải Kaki dày. Cơ chế Hồi form (Recovery): Tỉ lệ 3% Spandex hoạt động như "lò xo" ngầm, giúp vải co lại ngay sau khi bị kéo căng, ngăn chặn hiệu quả tình trạng bùng gối (baggy knees) và bai dão sau thời gian dài sử dụng. 2. Phom Dáng: Regular Straight (Ống Đứng) Che khuyết điểm vật lý: Cấu trúc ống suông thẳng từ đùi xuống lai đóng vai trò như một "khung xương" độc lập, không bám dính vào da, giúp che phủ hoàn hảo nhược điểm chân cong hoặc bắp chân to. Vận động tự do: Đáy quần (crotch) được cân chỉnh tiêu chuẩn, kết hợp với độ co giãn của FlexFit™ giúp người mặc thoải mái ngồi xổm hoặc di chuyển mà không bị gò bó. 3. Kết Cấu May: Tiêu Chuẩn Workwear Chỉ may ngoại cỡ: Sử dụng chỉ Cotton cơ số 20/3 (sợi to, thô) với mật độ 4 mũi/cm, vừa gia tăng độ bền liên kết, vừa tạo nét phóng khoáng, bụi bặm. Gia cố vùng đáy: Sử dụng máy Kansai móc xích 2 kim (Double Chainstitch) tại khu vực chịu lực cao nhất. Đường may này có độ đàn hồi theo chuyển động cơ thể, chống nứt đáy tuyệt đối. TỔNG KẾT: Multi Color Jean 001 khắc phục điểm yếu lớn nhất của quần vải dày là sự thô cứng và mất dáng. Nhờ cơ chế hồi form (recovery) của sợi Spandex trên nền tảng 310gsm, sản phẩm giữ được dáng quần thẳng đứng, chỉn chu suốt cả ngày nhưng vẫn đảm bảo sự linh hoạt tối đa cho người mặc. THÔNG TIN NHANH Chất liệu: FlexFit™ Cotton Plus Twill 310gsm, 97% Cotton 3% Spandex Chi tiết sản phẩm: Regular Fit Lưu ý giặt ủi: Giặt nước lạnh/ấm (&lt; 40°C), lộn trái khi giặt và phơi. Tuyệt đối không sấy nóng để tránh co rút sợi Spandex và hỏng form. Ủi ở nhiệt độ thấp - trung bình (110°C – 150°C), tốt nhất khi vải còn ẩm.', 'YAME', 453150, 477000, true, 5.0, 3579, 160, 4.0, 9, 'active', false, true, false, 'Quần Jean FlexFit™ Đáy Quần May Chịu Lực Chắc Chắn Multi Color Jean 001 Màu Trắng Dáng Vừa Vặn F3', 'Quần Jeans Regular Fit Multi Color Jean 001 1. Công Nghệ Chất Liệu: FlexFit™ 310gsm Trọng lượng 310gsm (Heavyweight): Tạo nền tảng vải dày dặn, đanh chắc, giúp quần lên form nam tính và mạnh mẽ. Bề mặt Smooth Touch: Kỹ thuật dệt Twill mật độ cao giúp các sợi xếp khít tuyệt đối, mang lại bề mặt phẳng', '110426-sale-5, F3 - Regular Fit (Dáng Tiêu Chuẩn), màu trắng, Quần áo, signature, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_83871352fb5c4e5f', 'cat_jeans', 'Quần Jean FlexFit™ Đáy Quần May Chịu Lực Chắc Chắn Multi Color Jean 001 Màu Xám Nhạt Dáng Vừa Vặn F3', 'quan-jean-flexfit-day-quan-may-chiu-luc-chac-chan-multi-color-jean-001-mau-xam-nhat-dang-vua-van-f3', '0024877', 'Quần Jeans Regular Fit Multi Color Jean 001 1. Công Nghệ Chất Liệu: FlexFit™ 310gsm Trọng lượng 310gsm (Heavyweight): Tạo nền tảng vải dày dặn, đanh chắc, giúp quần lên form nam tính và mạnh mẽ. Bề mặt Smooth Touch: Kỹ thuật dệt Twill mật độ cao giúp các sợi xếp khít tuyệt đối, mang lại bề mặt phẳng', 'Quần Jeans Regular Fit Multi Color Jean 001 1. Công Nghệ Chất Liệu: FlexFit™ 310gsm Trọng lượng 310gsm (Heavyweight): Tạo nền tảng vải dày dặn, đanh chắc, giúp quần lên form nam tính và mạnh mẽ. Bề mặt Smooth Touch: Kỹ thuật dệt Twill mật độ cao giúp các sợi xếp khít tuyệt đối, mang lại bề mặt phẳng phiu, mịn màng, loại bỏ hoàn toàn cảm giác thô ráp thường thấy ở vải Kaki dày. Cơ chế Hồi form (Recovery): Tỉ lệ 3% Spandex hoạt động như "lò xo" ngầm, giúp vải co lại ngay sau khi bị kéo căng, ngăn chặn hiệu quả tình trạng bùng gối (baggy knees) và bai dão sau thời gian dài sử dụng. 2. Phom Dáng: Regular Straight (Ống Đứng) Che khuyết điểm vật lý: Cấu trúc ống suông thẳng từ đùi xuống lai đóng vai trò như một "khung xương" độc lập, không bám dính vào da, giúp che phủ hoàn hảo nhược điểm chân cong hoặc bắp chân to. Vận động tự do: Đáy quần (crotch) được cân chỉnh tiêu chuẩn, kết hợp với độ co giãn của FlexFit™ giúp người mặc thoải mái ngồi xổm hoặc di chuyển mà không bị gò bó. 3. Kết Cấu May: Tiêu Chuẩn Workwear Chỉ may ngoại cỡ: Sử dụng chỉ Cotton cơ số 20/3 (sợi to, thô) với mật độ 4 mũi/cm, vừa gia tăng độ bền liên kết, vừa tạo nét phóng khoáng, bụi bặm. Gia cố vùng đáy: Sử dụng máy Kansai móc xích 2 kim (Double Chainstitch) tại khu vực chịu lực cao nhất. Đường may này có độ đàn hồi theo chuyển động cơ thể, chống nứt đáy tuyệt đối. TỔNG KẾT: Multi Color Jean 001 khắc phục điểm yếu lớn nhất của quần vải dày là sự thô cứng và mất dáng. Nhờ cơ chế hồi form (recovery) của sợi Spandex trên nền tảng 310gsm, sản phẩm giữ được dáng quần thẳng đứng, chỉn chu suốt cả ngày nhưng vẫn đảm bảo sự linh hoạt tối đa cho người mặc. THÔNG TIN NHANH Chất liệu: FlexFit™ Cotton Plus Twill 310gsm, 97% Cotton 3% Spandex Chi tiết sản phẩm: Regular Fit Lưu ý giặt ủi: Giặt nước lạnh/ấm (&lt; 40°C), lộn trái khi giặt và phơi. Tuyệt đối không sấy nóng để tránh co rút sợi Spandex và hỏng form. Ủi ở nhiệt độ thấp - trung bình (110°C – 150°C), tốt nhất khi vải còn ẩm.', 'YAME', 453150, 477000, true, 5.0, 543, 53, 4.4, 42, 'active', false, true, false, 'Quần Jean FlexFit™ Đáy Quần May Chịu Lực Chắc Chắn Multi Color Jean 001 Màu Xám Nhạt Dáng Vừa Vặn F3', 'Quần Jeans Regular Fit Multi Color Jean 001 1. Công Nghệ Chất Liệu: FlexFit™ 310gsm Trọng lượng 310gsm (Heavyweight): Tạo nền tảng vải dày dặn, đanh chắc, giúp quần lên form nam tính và mạnh mẽ. Bề mặt Smooth Touch: Kỹ thuật dệt Twill mật độ cao giúp các sợi xếp khít tuyệt đối, mang lại bề mặt phẳng', '110426-sale-5, F3 - Regular Fit (Dáng Tiêu Chuẩn), màu xám, Quần áo, signature, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
