INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_19e326f79c1b4999', 'cat_jeans', 'Quần Jeans Bo Ống FlexFit™ Lưng Thun Co Giãn Thoải Mái The Original 037 Màu Xanh Dương Nhạt Dáng Vừa Vặn F3', 'quan-jeans-bo-ong-flexfit-lung-thun-co-gian-thoai-mai-the-original-037-mau-xanh-duong-nhat-dang-vua-van-f3', '0024726', 'ID sản phẩm: The Original 037 Quần Jeans Jogger, co giãn, mềm, hiệu ứng sờn nhẹ. 1. Kiểu sản phẩm: Quần Jeans Jogger 2. Ưu điểm: -Thoải mái tối ưu: Vải mềm mại, co giãn, lưng thun cực fit, cho bạn tự do thể hiện chất riêng mà không hề gò bó. - Năng động và hiện đại : Quần có độ ôm vừa phải, tôn dáng', 'ID sản phẩm: The Original 037 Quần Jeans Jogger, co giãn, mềm, hiệu ứng sờn nhẹ. 1. Kiểu sản phẩm: Quần Jeans Jogger 2. Ưu điểm: -Thoải mái tối ưu: Vải mềm mại, co giãn, lưng thun cực fit, cho bạn tự do thể hiện chất riêng mà không hề gò bó. - Năng động và hiện đại : Quần có độ ôm vừa phải, tôn dáng người mặc, tạo vẻ ngoài gọn gàng, năng động. - Đứng form, thách thức giặt máy : Với 14% Polyester giúp quần bền màu hơn, ít nhăn và giữ được phom dáng chuẩn sau nhiều lần giặt. 3. Chất liệu: Jean, 85% Cotton 14% Polyester 1% Spandex 4. Kỹ thuật: Wash enzyme giúp cho quần jean mềm hơn, màu sắc nhạt hơn và tạo hiệu ứng sờn tự nhiên. 5. Phù hợp với ai: Nam giới dễ dàng kết hợp với nhiều loại trang phục khác nhau, phù hợp cho mọi hoàn cảnh, từ đi học, đi làm cho đến đi chơi. 6. Thuộc bộ sưu tập : BST The Original Jean - Phong cách jean đa dạng, cá tính mạnh mẽ. 7. Tìm kiếm sản phẩm: Quần jogger jean nam, Quần jean lưng thun, Quần jean co giãn, Quần Jean mềm.', 'YAME', 277550, 427000, true, 35.0, 356, 411, 4.3, 81, 'active', false, true, false, 'Quần Jeans Bo Ống FlexFit™ Lưng Thun Co Giãn Thoải Mái The Original 037 Màu Xanh Dương Nhạt Dáng Vừa Vặn F3', 'ID sản phẩm: The Original 037 Quần Jeans Jogger, co giãn, mềm, hiệu ứng sờn nhẹ. 1. Kiểu sản phẩm: Quần Jeans Jogger 2. Ưu điểm: -Thoải mái tối ưu: Vải mềm mại, co giãn, lưng thun cực fit, cho bạn tự do thể hiện chất riêng mà không hề gò bó. - Năng động và hiện đại : Quần có độ ôm vừa phải, tôn dáng', '010426-sale, 010426-sale-quanao35, F3 - Regular Fit (Dáng Tiêu Chuẩn), Gu đơn giản, màu xanh dương, Quần, Quần Jeans, Quần áo, signature0226, Thời Trang Jean', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
