INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_077d5f2ef79f4859', 'cat_jeans', 'Quần Jean Suông Rộng DurableTex™ Đắp 2 Lớp Chống Rách Gối Siêu Bền Multi Color Jean 012 Màu Nâu Nhạt Dáng Rộng Rãi F4', 'quan-jean-suong-rong-durabletex-dap-2-lop-chong-rach-goi-sieu-ben-multi-color-jean-012-mau-nau-nhat-dang-rong-rai-f4', '0024647', 'Quần Jeans Loose Fit Multi Color Jean 012 1. Vật Liệu DurableTex™ 310gsm: Bền &amp; Thoáng Sản phẩm sử dụng dòng vải DurableTex™ Cotton Ultra Twill định lượng 310gsm (trung bình-nặng). Kết cấu: Kỹ thuật dệt vân chéo (Twill Weave) mật độ cao giúp phân tán lực, tăng khả năng kháng xé rách và giữ phom ', 'Quần Jeans Loose Fit Multi Color Jean 012 1. Vật Liệu DurableTex™ 310gsm: Bền &amp; Thoáng Sản phẩm sử dụng dòng vải DurableTex™ Cotton Ultra Twill định lượng 310gsm (trung bình-nặng). Kết cấu: Kỹ thuật dệt vân chéo (Twill Weave) mật độ cao giúp phân tán lực, tăng khả năng kháng xé rách và giữ phom đứng tự nhiên. Trải nghiệm: Thành phần 97% Cotton đảm bảo cơ chế thoát hơi ẩm thụ động (thoáng khí). Tỷ lệ 3% Spandex trong hệ sợi ngang giúp vải có độ đàn hồi, loại bỏ cảm giác cứng nhắc của vải Kaki truyền thống. 2. Cấu Trúc Rập Loose Fit &amp; Gia Cố Double Knee Phom dáng: Thiết kế Wide Leg (ống rộng) với thông số gối được nới rộng (+4cm) tạo không gian lưu thông khí và biên độ cử động lớn. Gia cố chịu lực: Cấu trúc Double Knee với lớp vải đắp chồng từ đùi xuống gối giúp tăng độ dày tại vùng ma sát cao. Các điểm yếu được gia cố bằng đinh tán và công nghệ ép keo lụa chống biến dạng. 3. Tiêu Chuẩn May Công Nghiệp Chỉ may: Sử dụng chỉ Cotton sợi to cho các đường diễu nổi, gia tăng độ bền kéo đứt. Liên kết: Sườn quần được may bằng máy vắt sổ 2 kim 5 chỉ kèm đường móc xích gia cố, đảm bảo không bung đứt khi vận động cường độ cao. TỔNG KẾT Multi Color Jean 012 là giải pháp Workwear cân bằng giữa độ bền cơ học và sự thoải mái xúc giác. Nền tảng vật liệu DurableTex™ 310gsm được tính toán kỹ lưỡng để vừa bảo vệ cơ thể, vừa duy trì độ linh hoạt suốt ngày dài. THÔNG TIN NHANH Chất liệu: DurableTex™ Cotton Ultra Twill 310gsm, 97% Cotton 3% Spandex Chi tiết sản phẩm: Loose Fit (Ống rộng), Đáy cao (High Rise), Gối đôi (Double Knee), Túi tiện ích đa năng. Lưu ý giặt / ủi: Giặt: Lộn trái, cài kín nút/khóa, giặt riêng đồ màu. Ủi: Nhiệt độ thấp (110–120°C), không ủi trực tiếp lên hình in. Mô Tả Ngắn Quần DurableTex™ 310gsm bền thoáng. Phom Loose Fit ống rộng, gối Double Knee gia cố cùng kỹ thuật may công nghiệp chịu lực vượt trội.', 'YAME', 529150, 557000, true, 5.0, 3967, 251, 4.2, 104, 'active', false, true, false, 'Quần Jean Suông Rộng DurableTex™ Đắp 2 Lớp Chống Rách Gối Siêu Bền Multi Color Jean 012 Màu Nâu Nhạt Dáng Rộng Rãi F4', 'Quần Jeans Loose Fit Multi Color Jean 012 1. Vật Liệu DurableTex™ 310gsm: Bền &amp; Thoáng Sản phẩm sử dụng dòng vải DurableTex™ Cotton Ultra Twill định lượng 310gsm (trung bình-nặng). Kết cấu: Kỹ thuật dệt vân chéo (Twill Weave) mật độ cao giúp phân tán lực, tăng khả năng kháng xé rách và giữ phom ', '130426-sale-5, F4 - Loose Fit (Dáng Rộng), Gu đơn giản, màu nâu, Quần, Quần Jeans, Quần áo, signature0226, signature0426, Thời Trang Jean', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
