INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_c0ae42f8d6e8499a', 'cat_jeans', 'Quần Đùi Jean DurableTex™ Đắp 2 Lớp Chống Rách Gối Siêu Bền Multi Color Jean 013 Màu Nâu Nhạt Dáng Rộng Rãi F4', 'quan-dui-jean-durabletex-dap-2-lop-chong-rach-goi-sieu-ben-multi-color-jean-013-mau-nau-nhat-dang-rong-rai-f4', '0024642', 'Quần Jeans Short DurableTex™ Multi Color Jean 013 1. Kỹ Thuật Rập Loose Fit - Tối Ưu Trục Dọc Kết cấu Long Rise (Đáy dài): Hạ đáy trước thêm 4cm, đáy sau 3cm và tăng chiều dài quần 7cm. Giải phóng vùng đáy: Tạo không gian đệm giúp người mặc ngồi xuống hoặc vận động mạnh mà không bị kích, cấn hay co ', 'Quần Jeans Short DurableTex™ Multi Color Jean 013 1. Kỹ Thuật Rập Loose Fit - Tối Ưu Trục Dọc Kết cấu Long Rise (Đáy dài): Hạ đáy trước thêm 4cm, đáy sau 3cm và tăng chiều dài quần 7cm. Giải phóng vùng đáy: Tạo không gian đệm giúp người mặc ngồi xuống hoặc vận động mạnh mà không bị kích, cấn hay co kéo vùng đũng. Độ phủ tốt: Lai quần nới rộng 2cm, độ dài ngang gối tạo sự thoải mái và che phủ tốt. 2. Vật Liệu DurableTex™ 310gsm - Bền Nhưng Êm Định lượng 310gsm: Mức trọng lượng trung bình-nặng giúp quần đứng form, dày dặn, không bị chảy nhão sau thời gian dài sử dụng. Co giãn cơ học: Thành phần 3% Spandex trong hệ sợi ngang giúp vải có độ đàn hồi linh hoạt, loại bỏ cảm giác cứng nhắc của vải Kaki thô. Kháng xé rách: Kiểu dệt Ultra Twill (vân chéo) giúp phân tán lực tác động và hạn chế bám bụi tốt hơn dệt vân điểm. 3. Kết Cấu "Double Knee" &amp; Tiêu Chuẩn Gia Cố Double Knee 3D: Mảng đắp gia cố lớn từ đùi xuống gấu quần tạo khối 3D, tăng độ dày và chịu ma sát tại vị trí đầu gối. Chỉ may chuyên dụng: Sử dụng chỉ Cotton to cho đường diễu nổi, gia tăng độ bền liên kết. Chống bung rách: Đóng nút đinh tán tại góc túi và đánh bọ (Bartack) mật độ cao tại miệng túi, đỉa quần. TỔNG KẾT Multi Color Jean 013 không đơn thuần là một sản phẩm may mặc, mà là lời giải kỹ thuật cho hai bài toán khó của người dùng: sự gò bó và độ bền kém. Bằng cách kết hợp rập Loose Fit với vải DurableTex™ 310gsm, sản phẩm đảm bảo sự cân bằng hoàn hảo giữa hiệu suất vận động và tuổi thọ sử dụng. THÔNG TIN NHANH Chất liệu: DurableTex™ Cotton Ultra Twill 310gsm, 97% Cotton 3% Spandex Chi tiết sản phẩm: Loose Fit, Double Knee (Gối đôi), Đinh tán kim loại. Lưu ý giặt / ủi: Bắt buộc lộn trái (inside out) và cài kín nút/khóa trước khi giặt. Giặt riêng đồ màu, tránh chà xát mạnh gây gợn màu (frosting). Ủi ở nhiệt độ thấp (110–120°C), không ủi trực tiếp lên hình in/logo.', 'YAME', 377150, 397000, true, 5.0, 4766, 110, 4.4, 64, 'active', false, true, false, 'Quần Đùi Jean DurableTex™ Đắp 2 Lớp Chống Rách Gối Siêu Bền Multi Color Jean 013 Màu Nâu Nhạt Dáng Rộng Rãi F4', 'Quần Jeans Short DurableTex™ Multi Color Jean 013 1. Kỹ Thuật Rập Loose Fit - Tối Ưu Trục Dọc Kết cấu Long Rise (Đáy dài): Hạ đáy trước thêm 4cm, đáy sau 3cm và tăng chiều dài quần 7cm. Giải phóng vùng đáy: Tạo không gian đệm giúp người mặc ngồi xuống hoặc vận động mạnh mà không bị kích, cấn hay co ', '130426-sale-5, F4 - Loose Fit (Dáng Rộng), Gu đơn giản, màu nâu, Quần, Quần Jeans, Quần short, Quần áo, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_80d127532c47466b', 'cat_jeans', 'Quần Đùi Jean DurableTex™ Đắp 2 Lớp Chống Rách Gối Siêu Bền Multi Color Jean 013 Màu Xanh Lá Đậm Dáng Rộng Rãi F4', 'quan-dui-jean-durabletex-dap-2-lop-chong-rach-goi-sieu-ben-multi-color-jean-013-mau-xanh-la-dam-dang-rong-rai-f4', '0024641', 'Quần Jeans Short DurableTex™ Multi Color Jean 013 1. Kỹ Thuật Rập Loose Fit - Tối Ưu Trục Dọc Kết cấu Long Rise (Đáy dài): Hạ đáy trước thêm 4cm, đáy sau 3cm và tăng chiều dài quần 7cm. Giải phóng vùng đáy: Tạo không gian đệm giúp người mặc ngồi xuống hoặc vận động mạnh mà không bị kích, cấn hay co ', 'Quần Jeans Short DurableTex™ Multi Color Jean 013 1. Kỹ Thuật Rập Loose Fit - Tối Ưu Trục Dọc Kết cấu Long Rise (Đáy dài): Hạ đáy trước thêm 4cm, đáy sau 3cm và tăng chiều dài quần 7cm. Giải phóng vùng đáy: Tạo không gian đệm giúp người mặc ngồi xuống hoặc vận động mạnh mà không bị kích, cấn hay co kéo vùng đũng. Độ phủ tốt: Lai quần nới rộng 2cm, độ dài ngang gối tạo sự thoải mái và che phủ tốt. 2. Vật Liệu DurableTex™ 310gsm - Bền Nhưng Êm Định lượng 310gsm: Mức trọng lượng trung bình-nặng giúp quần đứng form, dày dặn, không bị chảy nhão sau thời gian dài sử dụng. Co giãn cơ học: Thành phần 3% Spandex trong hệ sợi ngang giúp vải có độ đàn hồi linh hoạt, loại bỏ cảm giác cứng nhắc của vải Kaki thô. Kháng xé rách: Kiểu dệt Ultra Twill (vân chéo) giúp phân tán lực tác động và hạn chế bám bụi tốt hơn dệt vân điểm. 3. Kết Cấu "Double Knee" &amp; Tiêu Chuẩn Gia Cố Double Knee 3D: Mảng đắp gia cố lớn từ đùi xuống gấu quần tạo khối 3D, tăng độ dày và chịu ma sát tại vị trí đầu gối. Chỉ may chuyên dụng: Sử dụng chỉ Cotton to cho đường diễu nổi, gia tăng độ bền liên kết. Chống bung rách: Đóng nút đinh tán tại góc túi và đánh bọ (Bartack) mật độ cao tại miệng túi, đỉa quần. TỔNG KẾT Multi Color Jean 013 không đơn thuần là một sản phẩm may mặc, mà là lời giải kỹ thuật cho hai bài toán khó của người dùng: sự gò bó và độ bền kém. Bằng cách kết hợp rập Loose Fit với vải DurableTex™ 310gsm, sản phẩm đảm bảo sự cân bằng hoàn hảo giữa hiệu suất vận động và tuổi thọ sử dụng. THÔNG TIN NHANH Chất liệu: DurableTex™ Cotton Ultra Twill 310gsm, 97% Cotton 3% Spandex Chi tiết sản phẩm: Loose Fit, Double Knee (Gối đôi), Đinh tán kim loại. Lưu ý giặt / ủi: Bắt buộc lộn trái (inside out) và cài kín nút/khóa trước khi giặt. Giặt riêng đồ màu, tránh chà xát mạnh gây gợn màu (frosting). Ủi ở nhiệt độ thấp (110–120°C), không ủi trực tiếp lên hình in/logo.', 'YAME', 377150, 397000, true, 5.0, 208, 151, 4.0, 114, 'active', false, true, false, 'Quần Đùi Jean DurableTex™ Đắp 2 Lớp Chống Rách Gối Siêu Bền Multi Color Jean 013 Màu Xanh Lá Đậm Dáng Rộng Rãi F4', 'Quần Jeans Short DurableTex™ Multi Color Jean 013 1. Kỹ Thuật Rập Loose Fit - Tối Ưu Trục Dọc Kết cấu Long Rise (Đáy dài): Hạ đáy trước thêm 4cm, đáy sau 3cm và tăng chiều dài quần 7cm. Giải phóng vùng đáy: Tạo không gian đệm giúp người mặc ngồi xuống hoặc vận động mạnh mà không bị kích, cấn hay co ', '110426-sale-5, F4 - Loose Fit (Dáng Rộng), Gu đơn giản, màu xanh lá, Quần, Quần Jeans, Quần short, Quần áo, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
