INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_27380e05bc534977', 'cat_jeans', 'Quần Jean Sợi Cà Phê S.Café® StayFresh™ Thoát Ẩm Nhanh Khử Mùi The Original 040 Màu Xanh Dương Nhạt Dáng Ôm Vừa F2', 'quan-jean-soi-ca-phe-scafe-stayfresh-thoat-am-nhanh-khu-mui-the-original-040-mau-xanh-duong-nhat-dang-om-vua-f2', '0024730', 'Quần Jeans Slim Fit StayFresh™ The Original 040 1. Chất liệu vải StayFresh™: Khử mùi từ bã cà phê Kiểm soát mùi cơ thể: Các hạt cà phê siêu nhỏ trong sợi vải hấp thụ mùi khó chịu, giúp quần luôn sạch thoáng. Tính năng này tồn tại vĩnh viễn, không bị mất đi sau khi giặt. Thoáng mát &amp; Nhanh khô: C', 'Quần Jeans Slim Fit StayFresh™ The Original 040 1. Chất liệu vải StayFresh™: Khử mùi từ bã cà phê Kiểm soát mùi cơ thể: Các hạt cà phê siêu nhỏ trong sợi vải hấp thụ mùi khó chịu, giúp quần luôn sạch thoáng. Tính năng này tồn tại vĩnh viễn, không bị mất đi sau khi giặt. Thoáng mát &amp; Nhanh khô: Cấu trúc sợi đặc biệt giúp mồ hôi thoát đi nhanh chóng, không gây cảm giác bết dính dù mặc suốt ngày dài. Bảo vệ da: Khả năng tán xạ tia UV tự nhiên giúp bảo vệ đôi chân dưới tác động của ánh nắng mặt trời. Co giãn linh hoạt: Trọng lượng vải 9.8oz (mức trung bình nhẹ) kết hợp 2% sợi Lycra giúp bạn thoải mái khi vận động, đứng ngồi hay lái xe. 2. Thiết kế Slim Fit: Tôn dáng, gọn chân Ống quần thon dài: Phần ống được thu gọn dần từ gối xuống mắt cá, tạo hiệu ứng thị giác giúp đôi chân trông thẳng và dài hơn. Vòng bụng phẳng, mông gọn: Thiết kế hạ thấp đáy trước giúp vùng bụng luôn phẳng phiu, không bị đùn vải, trong khi đáy sau giữ cao giúp ôm trọn vòng mông một cách chỉn chu. Loại bỏ nếp nhăn vải thừa: Vùng đùi và hông được cắt gọn gàng, giúp triệt tiêu các nếp gấp vải không cần thiết, tạo nên vẻ ngoài tinh tế nhưng không hề bó sát khó chịu. 3. Kỹ thuật may chuyên dụng: Bền bỉ từng chi tiết Đường may móc xích: Áp dụng tại lưng và đáy quần để đường chỉ có độ đàn hồi, co giãn theo chuyển động của cơ thể, hạn chế tối đa tình trạng đứt chỉ. Gia cố lực: Các điểm dễ rách như miệng túi, đỉa quần và đáy đều được đóng bọ chắc chắn. Hoàn thiện phẳng phiu: Khuy quần thùa mắt phụng giữ nút kim loại cố định, dây kéo được xử lý kỹ thuật để luôn phẳng và êm. TỔNG KẾT Jean Slim Fit S-Cafe The Original 040 là sự kết hợp hoàn hảo giữa công nghệ vải khử mùi StayFresh™ và kỹ thuật cắt may tôn dáng. Sản phẩm mang lại sự khô thoáng, thoải mái tuyệt đối và vẻ ngoài chỉn chu cho quý ông hiện đại. THÔNG TIN NHANH Chất liệu: StayFresh™ S-Cafe Blend Ultra Twill 9,8oz, 76% Cotton 22% S-Cafe 2% Lycra. Chi tiết sản phẩm: Dáng Slim Fit, ống côn, 5 túi cổ điển. Lưu ý giặt ủi KHÔNG DÙNG NƯỚC XẢ VẢI (để trá', 'YAME', 472150, 497000, true, 5.0, 765, 161, 4.1, 151, 'active', false, true, true, 'Quần Jean Sợi Cà Phê S.Café® StayFresh™ Thoát Ẩm Nhanh Khử Mùi The Original 040 Màu Xanh Dương Nhạt Dáng Ôm Vừa F2', 'Quần Jeans Slim Fit StayFresh™ The Original 040 1. Chất liệu vải StayFresh™: Khử mùi từ bã cà phê Kiểm soát mùi cơ thể: Các hạt cà phê siêu nhỏ trong sợi vải hấp thụ mùi khó chịu, giúp quần luôn sạch thoáng. Tính năng này tồn tại vĩnh viễn, không bị mất đi sau khi giặt. Thoáng mát &amp; Nhanh khô: C', 'F2 - Slim Fit (Dáng Ôm Vừa), Gu đơn giản, màu xanh dương, Quần, Quần Jeans, Quần áo, signature, signature0226, signature0426, Thời Trang Jean', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
