INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_9dfd014d81ad4cc2', 'cat_jeans', 'Quần Đùi Jean Vải DurableTex™ Đứng Dáng, Mài Nhẹ Tự Nhiên The Original 084 Màu Xanh Dương Nhạt Dáng Rộng Rãi F4', 'quan-dui-jean-vai-durabletex-dung-dang-mai-nhe-tu-nhien-the-original-084-mau-xanh-duong-nhat-dang-rong-rai-f4', '0023563', 'ID sản phẩm: The Original 084 Quần Short 7 Inch Wash nhẹ nhàng, bền bỉ, co dãn, đứng phom. 1. Kiểu sản phẩm: Quần Short Jean 2. Ưu điểm: -Mặc bền, co giãn nhẹ: Chất liệu Cotton Blend giúp sản phẩm có độ bền cao, co giãn nhẹ để tạo sự thoải mái. -Đứng form, thoải mái: Quần duy trì form dáng, dáng rộn', 'ID sản phẩm: The Original 084 Quần Short 7 Inch Wash nhẹ nhàng, bền bỉ, co dãn, đứng phom. 1. Kiểu sản phẩm: Quần Short Jean 2. Ưu điểm: -Mặc bền, co giãn nhẹ: Chất liệu Cotton Blend giúp sản phẩm có độ bền cao, co giãn nhẹ để tạo sự thoải mái. -Đứng form, thoải mái: Quần duy trì form dáng, dáng rộng và chất liệu thoải mái, phù hợp cho nhiều người. -Wash nhẹ tinh tế: Quần được wash nhẹ, mang lại vẻ ngoài đơn giản nhưng trẻ trung, năng động. 3. Chất liệu: Vải Jean với thành phần chính gồm 93% Cotton, 5% Polyester và 2% Spandex. 4. Kỹ thuật: Trơn, wash nhẹ, độ bền cao, co giãn nhẹ, giữ form dáng tốt. 5. Phù hợp với ai: Với dáng rộng và chất liệu thoải mái, quần short này phù hợp cho nhiều người, từ hàng ngày đến các dịp đặc biệt. 6. Thuộc Bộ Sưu Tập nào: The Original, thời trang jean phong cách của bạn 7. Các tên thường gọi hoặc tìm kiếm về sản phẩm này: Quần short jean, Quần Short, Quần short Denim, Quần jean wash', 'YAME', 272650, 287000, true, 5.0, 4813, 295, 4.8, 127, 'active', false, true, false, 'Quần Đùi Jean Vải DurableTex™ Đứng Dáng, Mài Nhẹ Tự Nhiên The Original 084 Màu Xanh Dương Nhạt Dáng Rộng Rãi F4', 'ID sản phẩm: The Original 084 Quần Short 7 Inch Wash nhẹ nhàng, bền bỉ, co dãn, đứng phom. 1. Kiểu sản phẩm: Quần Short Jean 2. Ưu điểm: -Mặc bền, co giãn nhẹ: Chất liệu Cotton Blend giúp sản phẩm có độ bền cao, co giãn nhẹ để tạo sự thoải mái. -Đứng form, thoải mái: Quần duy trì form dáng, dáng rộn', 'F4 - Loose Fit (Dáng Rộng), Gu đơn giản, màu xanh dương, Quần, Quần Jeans, Quần short, Quần áo, signature, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
