INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_43611ba36c3443b6', 'cat_jeans', 'Quần Đùi Jean Vải DurableTex™ Đứng Dáng, Hình Thêu Sắc Nét Bền Màu The Original 008 Màu Xanh Dương Nhạt Dáng Ôm Vừa F2', 'quan-dui-jean-vai-durabletex-dung-dang-hinh-theu-sac-net-ben-mau-the-original-008-mau-xanh-duong-nhat-dang-om-vua-f2', '0023382', 'Quần Jeans Short DurableTex™ The Original 008 1. Chất liệu DurableTex™ 11.5oz (Heavyweight) Định lượng: 11.5oz – Thuộc nhóm vải dày (Heavyweight), mang lại cảm giác bảo vệ chắc chắn. Thành phần: 100% Cotton tự nhiên, không pha sợi thun (Spandex). Loại bỏ hoàn toàn tình trạng "bai dão" hay "bùng gối"', 'Quần Jeans Short DurableTex™ The Original 008 1. Chất liệu DurableTex™ 11.5oz (Heavyweight) Định lượng: 11.5oz – Thuộc nhóm vải dày (Heavyweight), mang lại cảm giác bảo vệ chắc chắn. Thành phần: 100% Cotton tự nhiên, không pha sợi thun (Spandex). Loại bỏ hoàn toàn tình trạng "bai dão" hay "bùng gối" sau thời gian dài sử dụng. Kết cấu bề mặt: Chất liệu DurableTex™ dệt vân chéo (Twill Weave) giúp vải chịu ma sát vật lý cao, đứng phom nhưng vẫn đảm bảo độ thoáng khí tự nhiên. 2. Cấu trúc Rập &amp; Phom dáng (Pattern Engineering) Chuyển đổi Slim Fit: Phom dáng được tinh chỉnh từ nền tảng Regular sang Slim Fit để gọn gàng hơn. Comfort Top (Thân trên): Tăng thông số [Lưng/Mông +2cm] và hạ sâu đáy [J-stitch +1cm]. Kỹ thuật này giải phóng vùng hông, giúp người mặc ngồi hoặc vận động mà không bị cấn kích. Tapered Leg (Ống quần): Thu gọn [Lai/Ống -3cm]. Ống quần ôm dần từ gối xuống lai, khắc phục nhược điểm "ống loe" của các dòng quần cũ. 3. Tiêu chuẩn May &amp; Gia cố (Construction) Mật độ chỉ: 4 mũi/cm (tiêu chuẩn xuất khẩu), giúp đường may liên kết chặt chẽ. Gia cố đáy (Chainstitch): Đáy sau và giàng trong được may cuốn 2 kim móc xích. Kết cấu này có độ đàn hồi cơ học, cho phép đường may co giãn nhẹ theo cử động để chống rách đáy. Chống xé rách (Bartacks): Các điểm chịu lực (miệng túi, con đỉa, góc moi) được đóng bọ chuyên dụng để khóa cứng bề mặt vải. Họa tiết thêu (Embroidery Details): Logo sử dụng kỹ thuật thêu vi tính 2D đảm bảo độ bền màu và không bị bong tróc như các phương pháp in ấn thông thường. TỔNG KẾT The Original 008 là lựa chọn tối ưu cho nhu cầu sử dụng cường độ cao. Sản phẩm ưu tiên độ bền vật lý với vải 100% Cotton 11.5oz và kết cấu may gia cố nhiều lớp, phù hợp cho người yêu thích sự cứng cáp và phom dáng chuẩn mực của Denim nguyên bản. THÔNG TIN NHANH Chất liệu: DurableTex™ Cotton Ultra Twill 11,5oz, 100% Cotton Chi tiết sản phẩm: Slim Fit, Khóa kéo, Thêu 2D, Nút kim loại Lưu ý giặt / ủi: Giặt nước lạnh (&lt;40°C), lộn trái khi phơi, ủi ở nhiệt độ cao (c', 'YAME', 263150, 277000, true, 5.0, 311, 32, 4.0, 162, 'active', false, true, false, 'Quần Đùi Jean Vải DurableTex™ Đứng Dáng, Hình Thêu Sắc Nét Bền Màu The Original 008 Màu Xanh Dương Nhạt Dáng Ôm Vừa F2', 'Quần Jeans Short DurableTex™ The Original 008 1. Chất liệu DurableTex™ 11.5oz (Heavyweight) Định lượng: 11.5oz – Thuộc nhóm vải dày (Heavyweight), mang lại cảm giác bảo vệ chắc chắn. Thành phần: 100% Cotton tự nhiên, không pha sợi thun (Spandex). Loại bỏ hoàn toàn tình trạng "bai dão" hay "bùng gối"', 'F2 - Slim Fit (Dáng Ôm Vừa), Gu đơn giản, màu xanh dương, Quần, Quần Jeans, Quần short, Quần áo, signature, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
