INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_0599be42139a40f8', 'cat_jeans', 'Quần Jean Vải Mềm Co Giãn Thoải Mái FlexFit™ The Original 018 Màu Xanh Dương Tối Dáng Ôm Vừa F2', 'quan-jean-vai-mem-co-gian-thoai-mai-flexfit-the-original-018-mau-xanh-duong-toi-dang-om-vua-f2', '0022486', 'Quần Jeans Slim Fit CloudTouch™ The Original 018 1. Chất liệu CloudTouch™ đột phá Sự kết hợp giữa Cotton thoáng khí và sợi Rayon mềm mát giúp triệt tiêu cảm giác thô ráp, mang lại bề mặt vải mịn mướt ngay từ lần chạm đầu tiên. 2. Phom dáng Slim-Fit (Tapered Leg) Thiết kế ống côn hiện đại: thu gọn dầ', 'Quần Jeans Slim Fit CloudTouch™ The Original 018 1. Chất liệu CloudTouch™ đột phá Sự kết hợp giữa Cotton thoáng khí và sợi Rayon mềm mát giúp triệt tiêu cảm giác thô ráp, mang lại bề mặt vải mịn mướt ngay từ lần chạm đầu tiên. 2. Phom dáng Slim-Fit (Tapered Leg) Thiết kế ống côn hiện đại: thu gọn dần từ gối xuống lai quần giúp tôn dáng và tạo hiệu ứng đôi chân thon dài hơn mà không gây gò bó. Kết cấu Đáy lệch: Cấu trúc "Đáy trước thấp - Đáy sau cao" giúp ôm gọn vùng mông, đảm bảo sự kín đáo và thoải mái tối đa khi ngồi hoặc vận động mạnh. 3. Gia cố điểm chịu lực: Chống rách miệng túi và vặn sườn quần khi sử dụng cường độ cao Độ bền phom dáng vượt trội: Sợi Polyester tạo "bộ khung" vững chắc phối hợp cùng kỹ thuật ép keo lụa tại lưng quần, giữ sản phẩm luôn phẳng phiu, không bị vặn sườn hay biến dạng sau nhiều lần giặt. Gia cố kỹ thuật chuyên sâu: Hệ thống đóng bọ tại các điểm chịu lực và đường may móc xích Kansai giúp quần bền bỉ, chống sứt chỉ ngay cả khi sử dụng cường độ cao. TỔNG KẾT Sự kết hợp hoàn hảo giữa phom dáng Jeans chuẩn mực và cảm giác mềm mại từ công nghệ sợi CloudTouch™, mang lại trải nghiệm mặc nhẹ nhàng, linh hoạt suốt ngày dài. THÔNG TIN NHANH Chất liệu: CloudTouch™ Rayon Blend Plus Twill 10oz, 68% Cotton 21% Polyester 9% Rayon 2% Spandex Chi tiết sản phẩm: F2 - Slim Fit (Dáng Ôm Vừa), túi đồng hồ cổ điển, khuy mắt phụng cao cấp. Lưu ý giặt ủi: Lộn trái khi giặt, sử dụng nước lạnh ( &lt; 40°C ), tránh ánh nắng gắt trực tiếp để bảo vệ độ đàn hồi của sợi vải.', 'YAME', 434150, 457000, true, 5.0, 408, 272, 4.8, 28, 'active', false, true, false, 'Quần Jean Vải Mềm Co Giãn Thoải Mái FlexFit™ The Original 018 Màu Xanh Dương Tối Dáng Ôm Vừa F2', 'Quần Jeans Slim Fit CloudTouch™ The Original 018 1. Chất liệu CloudTouch™ đột phá Sự kết hợp giữa Cotton thoáng khí và sợi Rayon mềm mát giúp triệt tiêu cảm giác thô ráp, mang lại bề mặt vải mịn mướt ngay từ lần chạm đầu tiên. 2. Phom dáng Slim-Fit (Tapered Leg) Thiết kế ống côn hiện đại: thu gọn dầ', '010426-sale-5, 130426-sale-5, F2 - Slim Fit (Dáng Ôm Vừa), Gu đơn giản, màu xanh dương, Quần, Quần Jeans, Quần áo, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
