INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_3b4ca9cbf9a546ce', 'cat_jeans', 'Quần Jean Vải DurableTex™ Mặc Bền Co Giãn Tốt, Mài Nhẹ Tự Nhiên The Original 004 Màu Xanh Dương Nhạt Dáng Ôm Vừa F2', 'quan-jean-vai-durabletex-mac-ben-co-gian-tot-mai-nhe-tu-nhien-the-original-004-mau-xanh-duong-nhat-dang-om-vua-f2', '0023538', 'ID sản phẩm: The Original 004 Quần Jean Slimfit wash thư giãn co giãn, dáng đứng. 1. Kiểu sản phẩm: Quần Dài Jean 2. Ưu điểm: -Vải jean bền, co giãn nhẹ: Chất liệu vải jean cao cấp giúp quần có độ bền vượt trội, co giãn nhẹ, mang lại cảm giác thoải mái. -Đứng form, lịch lãm: Thiết kế ống đứng và chấ', 'ID sản phẩm: The Original 004 Quần Jean Slimfit wash thư giãn co giãn, dáng đứng. 1. Kiểu sản phẩm: Quần Dài Jean 2. Ưu điểm: -Vải jean bền, co giãn nhẹ: Chất liệu vải jean cao cấp giúp quần có độ bền vượt trội, co giãn nhẹ, mang lại cảm giác thoải mái. -Đứng form, lịch lãm: Thiết kế ống đứng và chất liệu vải dày giúp quần giữ form dáng chuẩn, gọn gàng. -Wash nhẹ tinh tế: Quần được wash nhẹ, mang lại vẻ ngoài đơn giản nhưng tinh tế và không kém phần thời trang. 3. Chất liệu: Vải Jean ,93% Cotton, 5% Polyester và 2% Spandex. 4. Kỹ thuật: Trơn, wash nhẹ, mang lại vẻ ngoài đơn giản nhưng tinh tế. 5. Phù hợp với ai: NoStyle - phù hợp với mọi gu thời trang, từ cổ điển đến hiện đại. 6. Thuộc Bộ Sưu Tập nào: NoStyle , nơi hội tụ những thiết kế thời trang đa dạng, từ phong cách cổ điển đến hiện đại. Với NoStyle, bạn luôn có thể tìm thấy những bộ trang phục vừa đẹp, vừa độc đáo, và luôn đúng mốt. 7. Các tên thường gọi hoặc tìm kiếm về sản phẩm này: Quần jean nam, Quần denim, Quần dài jean, Quần jean Slim fit', 'YAME', 339150, 357000, true, 5.0, 1447, 275, 5.0, 74, 'active', true, true, false, 'Quần Jean Vải DurableTex™ Mặc Bền Co Giãn Tốt, Mài Nhẹ Tự Nhiên The Original 004 Màu Xanh Dương Nhạt Dáng Ôm Vừa F2', 'ID sản phẩm: The Original 004 Quần Jean Slimfit wash thư giãn co giãn, dáng đứng. 1. Kiểu sản phẩm: Quần Dài Jean 2. Ưu điểm: -Vải jean bền, co giãn nhẹ: Chất liệu vải jean cao cấp giúp quần có độ bền vượt trội, co giãn nhẹ, mang lại cảm giác thoải mái. -Đứng form, lịch lãm: Thiết kế ống đứng và chấ', '0023538, F2 - Slim Fit (Dáng Ôm Vừa), Gu đơn giản, màu xanh dương, Quần, Quần Jeans, Quần áo, signature0226, signature0426, Thời Trang Jean', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
