INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_c469a70575054c75', 'cat_kaki', 'Quần Kaki DurableTex™ Vải Dai Chắc, Đầu Gối Xếp Ly Co Gập Thoải Mái The Worker 009 Màu Xám Đậm Dáng Vừa Vặn F3', 'quan-kaki-durabletex-vai-dai-chac-dau-goi-xep-ly-co-gap-thoai-mai-the-worker-009-mau-xam-dam-dang-vua-van-f3', '0024740', 'Quần Kaki DurableTex™ The Worker 009 1. Kỹ Thuật Rập &amp; Phom Dáng (Pattern Engineering) Cấu trúc 3D Articulated Knee: Sử dụng đường rã phối thân trước kết hợp với chi tiết xếp ly gối (Knee Dart). Hiệu quả vận động: Kỹ thuật này tạo khối dung tích dư thừa tại khớp gối, giúp người mặc thực hiện các', 'Quần Kaki DurableTex™ The Worker 009 1. Kỹ Thuật Rập &amp; Phom Dáng (Pattern Engineering) Cấu trúc 3D Articulated Knee: Sử dụng đường rã phối thân trước kết hợp với chi tiết xếp ly gối (Knee Dart). Hiệu quả vận động: Kỹ thuật này tạo khối dung tích dư thừa tại khớp gối, giúp người mặc thực hiện các động tác ngồi, gập chân mà không bị căng bề mặt vải hay co kéo ống quần. Tối ưu thị giác: Phom dáng được tinh chỉnh dựa trên nền tảng Regular, giúp che khuyết điểm và tạo cảm giác cao ráo nhờ cấu trúc lưng liền. 2. Vật Liệu &amp; Định Lượng (Material Specifications) Nền tảng vải: Sử dụng dòng vải DurableTex™ Cotton Ultra Twill dệt vân chéo, định lượng 300gsm (trung bình-nặng). Độ dày này đảm bảo quần đứng phom, nắp túi phẳng phiu và hạn chế mài mòn. Thành phần sợi: Tỷ lệ 97% Cotton thấm hút tốt kết hợp 3% Spandex trong hệ sợi ngang. Việc pha sợi đàn hồi giúp giải quyết nhược điểm cứng ráp của vải Kaki dày, mang lại độ co giãn cơ học thoải mái. 3. Kết Cấu May &amp; Độ Bền (Construction &amp; Durability) Tiêu chuẩn đường may: Các vị trí chịu lực chính (sườn, đáy, giàng) được ráp bằng máy Vắt sổ 2 kim 5 chỉ (Safety Stitch), đảm bảo liên kết chắc chắn tuyệt đối. Chỉ may chuyên dụng: Sử dụng chỉ Cotton chỉ to, 3 sợi xoắn cho các đường diễu nổi, gia tăng độ bền kéo và tạo hiệu ứng khối khỏe khoắn. Gia cố (Reinforcement): Đánh bọ Bartack kỹ lưỡng tại các điểm yếu như miệng túi, đỉa quần, góc nắp túi để chống bung rách khi chịu lực giật mạnh. 4. Hệ Thống Túi &amp; Tiện Ích (Utility System) Túi hộp xếp ly (Pleated Cargo): Thiết kế có ly giúp túi ép sát thân khi rỗng và mở rộng thể tích khi chứa đồ, đảm bảo sự gọn gàng. Định hình nắp túi: Nắp túi được ép keo vải mềm 60% diện tích giúp chống quăn góc sau khi giặt nhưng không làm cứng nắp. Phụ liệu kim loại: Sử dụng nút kim loại và nút bóp chắc chắn, hỗ trợ thao tác đóng mở nhanh và an toàn. TỔNG KẾT The Worker 009 cân bằng chính xác giữa tính công năng (Function) và thẩm mỹ tối giản (Minimalism). Với sự kết hợp của vật liệu 300gsm ', 'YAME', 548150, 577000, true, 5.0, 3217, 268, 4.2, 186, 'active', false, true, false, 'Quần Kaki DurableTex™ Vải Dai Chắc, Đầu Gối Xếp Ly Co Gập Thoải Mái The Worker 009 Màu Xám Đậm Dáng Vừa Vặn F3', 'Quần Kaki DurableTex™ The Worker 009 1. Kỹ Thuật Rập &amp; Phom Dáng (Pattern Engineering) Cấu trúc 3D Articulated Knee: Sử dụng đường rã phối thân trước kết hợp với chi tiết xếp ly gối (Knee Dart). Hiệu quả vận động: Kỹ thuật này tạo khối dung tích dư thừa tại khớp gối, giúp người mặc thực hiện các', '110426-sale-5, F3 - Regular Fit (Dáng Tiêu Chuẩn), Gu đơn giản, màu xám, Quần, Quần dài, Quần áo, signature, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_5b847278cab049be', 'cat_kaki', 'Quần Kaki DurableTex™ Vải Dai Chắc, Đầu Gối Xếp Ly Co Gập Thoải Mái The Worker 009 Màu Xanh Lá Đậm Dáng Vừa Vặn F3', 'quan-kaki-durabletex-vai-dai-chac-dau-goi-xep-ly-co-gap-thoai-mai-the-worker-009-mau-xanh-la-dam-dang-vua-van-f3', '0024739', 'Quần Kaki DurableTex™ The Worker 009 1. Kỹ Thuật Rập &amp; Phom Dáng (Pattern Engineering) Cấu trúc 3D Articulated Knee: Sử dụng đường rã phối thân trước kết hợp với chi tiết xếp ly gối (Knee Dart). Hiệu quả vận động: Kỹ thuật này tạo khối dung tích dư thừa tại khớp gối, giúp người mặc thực hiện các', 'Quần Kaki DurableTex™ The Worker 009 1. Kỹ Thuật Rập &amp; Phom Dáng (Pattern Engineering) Cấu trúc 3D Articulated Knee: Sử dụng đường rã phối thân trước kết hợp với chi tiết xếp ly gối (Knee Dart). Hiệu quả vận động: Kỹ thuật này tạo khối dung tích dư thừa tại khớp gối, giúp người mặc thực hiện các động tác ngồi, gập chân mà không bị căng bề mặt vải hay co kéo ống quần. Tối ưu thị giác: Phom dáng được tinh chỉnh dựa trên nền tảng Regular, giúp che khuyết điểm và tạo cảm giác cao ráo nhờ cấu trúc lưng liền. 2. Vật Liệu &amp; Định Lượng (Material Specifications) Nền tảng vải: Sử dụng dòng vải DurableTex™ Cotton Ultra Twill dệt vân chéo, định lượng 300gsm (trung bình-nặng). Độ dày này đảm bảo quần đứng phom, nắp túi phẳng phiu và hạn chế mài mòn. Thành phần sợi: Tỷ lệ 97% Cotton thấm hút tốt kết hợp 3% Spandex trong hệ sợi ngang. Việc pha sợi đàn hồi giúp giải quyết nhược điểm cứng ráp của vải Kaki dày, mang lại độ co giãn cơ học thoải mái. 3. Kết Cấu May &amp; Độ Bền (Construction &amp; Durability) Tiêu chuẩn đường may: Các vị trí chịu lực chính (sườn, đáy, giàng) được ráp bằng máy Vắt sổ 2 kim 5 chỉ (Safety Stitch), đảm bảo liên kết chắc chắn tuyệt đối. Chỉ may chuyên dụng: Sử dụng chỉ Cotton chỉ to, 3 sợi xoắn cho các đường diễu nổi, gia tăng độ bền kéo và tạo hiệu ứng khối khỏe khoắn. Gia cố (Reinforcement): Đánh bọ Bartack kỹ lưỡng tại các điểm yếu như miệng túi, đỉa quần, góc nắp túi để chống bung rách khi chịu lực giật mạnh. 4. Hệ Thống Túi &amp; Tiện Ích (Utility System) Túi hộp xếp ly (Pleated Cargo): Thiết kế có ly giúp túi ép sát thân khi rỗng và mở rộng thể tích khi chứa đồ, đảm bảo sự gọn gàng. Định hình nắp túi: Nắp túi được ép keo vải mềm 60% diện tích giúp chống quăn góc sau khi giặt nhưng không làm cứng nắp. Phụ liệu kim loại: Sử dụng nút kim loại và nút bóp chắc chắn, hỗ trợ thao tác đóng mở nhanh và an toàn. TỔNG KẾT The Worker 009 cân bằng chính xác giữa tính công năng (Function) và thẩm mỹ tối giản (Minimalism). Với sự kết hợp của vật liệu 300gsm ', 'YAME', 548150, 577000, true, 5.0, 3274, 243, 4.3, 113, 'active', false, true, false, 'Quần Kaki DurableTex™ Vải Dai Chắc, Đầu Gối Xếp Ly Co Gập Thoải Mái The Worker 009 Màu Xanh Lá Đậm Dáng Vừa Vặn F3', 'Quần Kaki DurableTex™ The Worker 009 1. Kỹ Thuật Rập &amp; Phom Dáng (Pattern Engineering) Cấu trúc 3D Articulated Knee: Sử dụng đường rã phối thân trước kết hợp với chi tiết xếp ly gối (Knee Dart). Hiệu quả vận động: Kỹ thuật này tạo khối dung tích dư thừa tại khớp gối, giúp người mặc thực hiện các', '110426-sale-5, F3 - Regular Fit (Dáng Tiêu Chuẩn), Gu đơn giản, màu xanh lá, Quần, Quần dài, Quần áo, signature, signature0226, signature0426', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_ea2e258e033c4ed2', 'cat_kaki', 'Quần Kaki DurableTex™ Vải Dày Dặn Sờ Êm Tay Non Branded 055 Màu Nâu Dáng Ôm Vừa F2', 'quan-kaki-durabletex-vai-day-dan-so-em-tay-non-branded-055-mau-nau-dang-om-vua-f2', '0024598', 'ID sản phẩm: Non Branded 055 Quần kaki dáng vừa, mềm mại, ít nhăn. 1.Kiểu sản phẩm: Quần Kaki 2.Ưu điểm: -Bền bỉ, ít nhăn: Vải Polyester có độ bền cơ học tốt, giữ màu lâu, ít nhăn, dễ bảo quản, tiện lợi. -Vải dệt chéo mềm mịn: Bề mặt mượt, đủ dày để giữ form tốt, che khuyết điểm, nhưng không quá nặn', 'ID sản phẩm: Non Branded 055 Quần kaki dáng vừa, mềm mại, ít nhăn. 1.Kiểu sản phẩm: Quần Kaki 2.Ưu điểm: -Bền bỉ, ít nhăn: Vải Polyester có độ bền cơ học tốt, giữ màu lâu, ít nhăn, dễ bảo quản, tiện lợi. -Vải dệt chéo mềm mịn: Bề mặt mượt, đủ dày để giữ form tốt, che khuyết điểm, nhưng không quá nặng. -Túi sau có nút bóp ẩn: Tinh tế và hạn chế rơi rớt đồ, tăng tính an toàn cho vật dụng cá nhân. 3.Chất liệu: Vải Khaki, 100% Polyester. 4.Kỹ thuật: Vải dệt chéo (twill weave) với mật độ sợi cao, tạo ra các đường vân chéo tinh xảo và bề mặt vải mịn màng. 5.Phù hợp với: Sinh viên, nhân viên văn phòng thích hợp mặc hàng ngày, đi làm, đi chơi, các hoạt động cần sự thoải mái và lịch sự. 6. Thuộc Bộ Sưu Tập: BST Non Branded - Vẻ đẹp nằm ở sự tối giản. 7.Tìm kiếm sản phẩm: Quần kaki nam, Quần chinos nam, Quần nam ống đứng, Quần công sở nam.', 'YAME', 472150, 497000, true, 5.0, 3708, 243, 4.5, 8, 'active', false, true, false, 'Quần Kaki DurableTex™ Vải Dày Dặn Sờ Êm Tay Non Branded 055 Màu Nâu Dáng Ôm Vừa F2', 'ID sản phẩm: Non Branded 055 Quần kaki dáng vừa, mềm mại, ít nhăn. 1.Kiểu sản phẩm: Quần Kaki 2.Ưu điểm: -Bền bỉ, ít nhăn: Vải Polyester có độ bền cơ học tốt, giữ màu lâu, ít nhăn, dễ bảo quản, tiện lợi. -Vải dệt chéo mềm mịn: Bề mặt mượt, đủ dày để giữ form tốt, che khuyết điểm, nhưng không quá nặn', 'F2 - Slim Fit (Dáng Ôm Vừa), Gu đơn giản, màu nâu, Quần, Quần dài, Quần áo, signature, signature0226, signature0426, Thời Trang Đơn Giản', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
