INSERT INTO products (id, category_id, name, slug, sku, short_description, description, brand, base_price, original_price, is_sale, discount_percent, view_count, sold_count, avg_rating, review_count, status, is_featured, is_new, is_bestseller, meta_title, meta_description, meta_keywords, created_at, updated_at) VALUES ('prod_6fbabd06e157444b', 'cat_kaki', 'Quần Kaki Ống Đứng Tôn Dáng, Vải DurableTex™ Chắc Chắn Mặc Bền The Minimalist 023 Màu Nâu Đậm Dáng Ôm Vừa F2', 'quan-kaki-ong-dung-ton-dang-vai-durabletex-chac-chan-mac-ben-the-minimalist-023-mau-nau-dam-dang-om-vua-f2', '0023651', 'Quần Kaki DurableTex™ The Minimalist 023 1. Nền tảng chất liệu: DurableTex™ Cotton Ultra Twill Định lượng bền bỉ: Sử dụng vải 310gsm dày dặn, tạo độ đứng (drape) tối ưu, kháng lại các ma sát cơ học và hạn chế đứt gãy xơ bông. Cấu trúc dệt Twill: Kiểu dệt chéo tạo mật độ sợi cao, giúp phân tán lực ké', 'Quần Kaki DurableTex™ The Minimalist 023 1. Nền tảng chất liệu: DurableTex™ Cotton Ultra Twill Định lượng bền bỉ: Sử dụng vải 310gsm dày dặn, tạo độ đứng (drape) tối ưu, kháng lại các ma sát cơ học và hạn chế đứt gãy xơ bông. Cấu trúc dệt Twill: Kiểu dệt chéo tạo mật độ sợi cao, giúp phân tán lực kéo và tăng khả năng kháng xé rách hiệu quả hơn các kiểu dệt thông thường. Đàn hồi cơ học: Sự pha trộn giữa 97% Cotton và 3% Spandex mang lại khả năng co giãn ngang (Weft Stretch), giải quyết triệt để sự cứng nhắc khi vận động. 2. Kỹ thuật rập và Kết cấu phom (Straight Fit) Tối ưu tỷ lệ: Điều chỉnh giảm độ rộng lai (-4.4cm) và gọt gọn vùng đầu gối (-4cm) để tạo trục ống thẳng, giúp chân trông thon gọn và cao ráo hơn. Cân bằng đáy: Kỹ thuật "Balanced Leg" giúp khu vực đũng quần sạch, phẳng, không bị dư hay nhăn vải khi di chuyển. Thoải mái vùng lưng: Vòng lưng được nới nhẹ (+1cm) để đảm bảo sự dễ chịu tối đa khi ngồi. 3. Tiêu chuẩn may và Hoàn thiện cao cấp Đường may gia cố: Sử dụng máy vắt sổ 5 chỉ với mũi móc xích song song, kết hợp chỉ Cotton 20/3 siêu bền để đảm bảo các đường ráp không bị nứt dưới áp lực vận động mạnh. Chi tiết "Khuy Mắt Phụng": Kỹ thuật lỗ khuy có phần đầu tròn giúp gài nút dễ dàng và chịu lực căng tốt hơn tại vị trí thắt lưng. Gia cố Bartacking: Các điểm chịu lực lớn như miệng túi và con đỉa đều được đóng bọ chốt chặn chuyên dụng để ngăn chặn hoàn toàn việc sút chỉ. TỔNG KẾT The Minimalist 023 tập trung vào giá trị cốt lõi là độ bền vật liệu và sự chuẩn xác trong phom dáng. Đây là giải pháp trang phục đa năng, kết hợp giữa tính lịch sự của môi trường công sở và khả năng vận động bền bỉ trong đời sống hằng ngày. THÔNG TIN NHANH Chất liệu: DurableTex™ Cotton Ultra Twill 310gsm, 97% Cotton 3% Spandex Chi tiết: Phom Straight Fit, khuy mắt phụng, đóng bọ gia cố tại các góc túi. Lưu ý giặt ủi: Lộn trái sản phẩm, cài khóa khi giặt. Ủi ở nhiệt độ thấp (110–120°C), ưu tiên thao tác "Đặt – Nhấc" và không kéo giãn vải khi đang nóng.', 'YAME', 472150, 497000, true, 5.0, 208, 356, 4.4, 29, 'active', true, true, false, 'Quần Kaki Ống Đứng Tôn Dáng, Vải DurableTex™ Chắc Chắn Mặc Bền The Minimalist 023 Màu Nâu Đậm Dáng Ôm Vừa F2', 'Quần Kaki DurableTex™ The Minimalist 023 1. Nền tảng chất liệu: DurableTex™ Cotton Ultra Twill Định lượng bền bỉ: Sử dụng vải 310gsm dày dặn, tạo độ đứng (drape) tối ưu, kháng lại các ma sát cơ học và hạn chế đứt gãy xơ bông. Cấu trúc dệt Twill: Kiểu dệt chéo tạo mật độ sợi cao, giúp phân tán lực ké', 'F2 - Slim Fit (Dáng Ôm Vừa), Gu đơn giản, màu nâu, Quần, Quần dài, Quần áo, signature0226, signature0426, Thời Trang Đơn Giản, Vị Nhân Sinh', NOW(), NOW()) ON CONFLICT (sku) DO NOTHING;
